// ============================================================================
// 2. THREE.JS SCENE INITIALIZATION & PROCEDURAL TEXTURES
// ============================================================================
const host = document.getElementById('sceneHost');
const labelsRoot = document.getElementById('sceneLabels');
const scene = new THREE.Scene();

// Mobile device detection (touch screens / narrow viewport)
const isMobileDevice = (typeof window !== 'undefined') && (
  window.matchMedia('(max-width: 768px)').matches ||
  /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)
);

// Global LOD (Level of Detail) Registry
const LOD_REGISTRY = [];
let lodEnabled = true;
let seasonsEnabled = !isMobileDevice; // Defaults off on mobile to save CPU/GPU, on on desktop
let walkModeAllowed = true;

function registerLOD(landmarkId, centerPos, detailGroup, thresholdDist = 65) {
  LOD_REGISTRY.push({
    landmarkId,
    center: new THREE.Vector3(...centerPos),
    detailGroup,
    thresholdDist
  });
}

function updateLODs() {
  if (!LOD_REGISTRY.length) return;
  const camPos = camera.position;
  const isMobileEco = isMobileDevice && (activeQuality === 'smooth');
  for (let i = 0; i < LOD_REGISTRY.length; i++) {
    const item = LOD_REGISTRY[i];
    if (!lodEnabled) {
      item.detailGroup.visible = true;
      continue;
    }
    const dist = camPos.distanceTo(item.center);
    if (isMobileEco) {
      // In mobile eco mode, keep heavy sub-details hidden unless camera is very close (< 32m)
      item.detailGroup.visible = dist < 32;
    } else {
      item.detailGroup.visible = dist < item.thresholdDist;
    }
  }
}

const getOptimalDpr = () => {
  const dpr = window.devicePixelRatio || 1;
  return isMobileDevice ? Math.min(dpr, 1.75) : Math.min(dpr, 2.0);
};

const camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.4, 1200);
const renderer = new THREE.WebGLRenderer({
  antialias: true,
  logarithmicDepthBuffer: true,
  preserveDrawingBuffer: true,
  powerPreference: 'high-performance'
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(getOptimalDpr());
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
host.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.065;
controls.maxPolarAngle = Math.PI / 2 - 0.025;
controls.minDistance = 1.2;
controls.maxDistance = 420;
window.__scene = scene; window.__camera = camera; window.__controls = controls; window.__renderer = renderer;

// On-Demand Demand-Driven Render Loop Manager (Saves 80%+ battery & eliminates mobile heating)
let renderDemandFrames = 90;
function requestRender(frames = 35) {
  renderDemandFrames = Math.max(renderDemandFrames, frames);
}
window.requestRender = requestRender;
controls.addEventListener('change', () => requestRender(20));
window.addEventListener('pointerdown', () => requestRender(60), { passive: true });
window.addEventListener('pointermove', e => { if (e.buttons > 0) requestRender(35); }, { passive: true });
window.addEventListener('wheel', () => requestRender(35), { passive: true });
window.addEventListener('touchstart', () => requestRender(60), { passive: true });
window.addEventListener('touchmove', () => requestRender(35), { passive: true });

// High-Fidelity Architectural Lighting Rig (Crisp shadows, soft bounce, warm corridor fill)
const hemiLight = new THREE.HemisphereLight(0xffffff, 0x8fa88a, 1.05);
scene.add(hemiLight);

