// Procedural Equirectangular Sky Generator (GXU sky.ts approach)
function createSkyTexture(presetKey) {
  const cfg = LIGHTING_PRESETS[presetKey];
  const c = document.createElement('canvas');
  c.width = 256; c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 128);
  g.addColorStop(0.0, cfg.zenith);
  g.addColorStop(0.52, cfg.horizon);
  g.addColorStop(0.62, cfg.horizon);
  g.addColorStop(1.0, cfg.lower);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 128);
  const tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// High-Resolution Procedural Ceramic Tile Texture & Bump Map (Square White School Exterior Tiles per p3.jpg/p10.jpg)
let _tileNormalMap = null;
function makeTileTexture(baseHex = '#f6f6f2', lineHex = '#c4c2ba') {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = baseHex;
  ctx.fillRect(0, 0, 512, 512);

  // Subtle ceramic surface noise & micro-grit
  let s = 97;
  const r = () => ((s = (s * 16807) % 2147483647) / 2147483647);
  for (let i = 0; i < 1800; i++) {
    ctx.fillStyle = r() > 0.5 ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.035)';
    ctx.fillRect(r() * 512, r() * 512, 2, 2);
  }

  // Realistic recessed cement grout lines (48px grid = square tile look)
  ctx.strokeStyle = lineHex;
  ctx.lineWidth = 3.5;
  for (let x = 0; x <= 512; x += 48) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 512); ctx.stroke();
  }
  for (let y = 0; y <= 512; y += 48) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(512, y); ctx.stroke();
  }

  // Inner tile edge chamfer highlight (makes each tile pop with relief in sunlight)
  ctx.strokeStyle = 'rgba(255,255,255,0.28)';
  ctx.lineWidth = 1.2;
  for (let x = 0; x < 512; x += 48) {
    for (let y = 0; y < 512; y += 48) {
      ctx.strokeRect(x + 2, y + 2, 44, 44);
    }
  }

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(6, 6);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// Procedural Window & Facade Texture Atlas (Standard aluminum window, classroom door, ventilation louvers, transom)
let _windowAtlasTex = null;
function makeWindowAtlasTexture() {
  if (_windowAtlasTex) return _windowAtlasTex;
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 512;
  const ctx = c.getContext('2d');

  // Background
  ctx.fillStyle = '#f0eee9';
  ctx.fillRect(0, 0, 1024, 512);

  // Quadrant 1 (0, 0, 512, 256): 4-pane aluminum sliding window with light blue glass
  ctx.fillStyle = '#e8e6df';
  ctx.fillRect(4, 4, 504, 248);
  ctx.fillStyle = '#b8d5e8';
  const pw = 118, ph = 232;
  for (let i = 0; i < 4; i++) {
    ctx.fillRect(12 + i * 122, 12, pw, ph);
    ctx.fillStyle = 'rgba(255,255,255,0.42)';
    ctx.fillRect(16 + i * 122, 16, pw - 8, 20);
    ctx.fillStyle = '#b8d5e8';
  }
  ctx.strokeStyle = '#8f9296';
  ctx.lineWidth = 3;
  ctx.strokeRect(4, 4, 504, 248);

  // Quadrant 2 (512, 0, 512, 256): Classroom entrance door with observation window
  ctx.fillStyle = '#8b5a2b';
  ctx.fillRect(516, 4, 504, 248);
  ctx.fillStyle = '#7a4e24';
  for (let y = 10; y < 250; y += 12) {
    ctx.fillRect(520, y, 496, 2);
  }
  ctx.fillStyle = '#c5e0ee';
  ctx.fillRect(560, 24, 180, 120);
  ctx.strokeStyle = '#4a2f15';
  ctx.lineWidth = 4;
  ctx.strokeRect(560, 24, 180, 120);
  ctx.fillStyle = '#d4af37';
  ctx.fillRect(720, 160, 16, 40);

  // Quadrant 3 (0, 256, 512, 256): Louvered ventilation screen (百葉氣窗)
  ctx.fillStyle = '#d8d7d0';
  ctx.fillRect(4, 260, 504, 248);
  ctx.fillStyle = '#4a4d50';
  for (let y = 268; y < 500; y += 16) {
    ctx.fillRect(12, y, 488, 7);
  }

  // Quadrant 4 (512, 256, 512, 256): Upper Transom Ribbon Window (走廊上端高氣窗)
  ctx.fillStyle = '#e4e2da';
  ctx.fillRect(516, 260, 504, 248);
  ctx.fillStyle = '#a9cce3';
  for (let i = 0; i < 6; i++) {
    ctx.fillRect(524 + i * 82, 270, 74, 228);
  }
  ctx.strokeStyle = '#7c8085';
  ctx.lineWidth = 3;
  ctx.strokeRect(516, 260, 504, 248);

  _windowAtlasTex = new THREE.CanvasTexture(c);
  _windowAtlasTex.colorSpace = THREE.SRGBColorSpace;
  return _windowAtlasTex;
}

// Procedural Terrazzo Corridor Floor Texture (Two-tone terrazzo per p10.jpg site photo)
function makeTerrazzoTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#dfddd5';
  ctx.fillRect(0, 0, 512, 512);

  // Authentic stone aggregate specks (grey, white, dark, brown chips)
  let s = 133;
  const r = () => ((s = (s * 16807) % 2147483647) / 2147483647);
  const chips = ['#3a3835', '#ffffff', '#8a857b', '#b3ada3', '#5a544c'];
  for (let i = 0; i < 3500; i++) {
    ctx.fillStyle = chips[(r() * chips.length) | 0];
    const sz = 1.5 + r() * 3.5;
    ctx.fillRect(r() * 512, r() * 512, sz, sz);
  }
  // Polished wax sheen joints every 256px (copper divider strips)
  ctx.strokeStyle = 'rgba(140,110,60,0.35)';
  ctx.lineWidth = 2.0;
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(512, 0); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(0, 256); ctx.lineTo(512, 256); ctx.stroke();

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(8, 4);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// Procedural Courtyard Geometric Brick Texture (True 1:1 matching p3.jpg & img4.jpg: Charcoal, Brick Red, Pearl Grey interlocking motifs)
function makeCourtyardBrickTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#dcd9d0';
  ctx.fillRect(0, 0, 512, 512);

  // Replicate the exact 4-quadrant geometric paver block seen in p3.jpg
  const drawModule = (ox, oy, sz) => {
    // Outer charcoal border
    ctx.fillStyle = '#44484d';
    ctx.fillRect(ox + 8, oy + 8, sz - 16, sz - 16);
    // Middle pearl white ring
    ctx.fillStyle = '#dedcd4';
    ctx.fillRect(ox + 28, oy + 28, sz - 56, sz - 56);
    // Inner charcoal ring
    ctx.fillStyle = '#494d52';
    ctx.fillRect(ox + 50, oy + 50, sz - 100, sz - 100);
    // Center terracotta red medallion
    ctx.fillStyle = '#b85440';
    ctx.fillRect(ox + 72, oy + 72, sz - 144, sz - 144);
    // Inner subtle cross pattern
    ctx.fillStyle = '#44484d';
    ctx.fillRect(ox + 104, oy + 104, sz - 208, sz - 208);
  };

  drawModule(0, 0, 256);
  drawModule(256, 0, 256);
  drawModule(0, 256, 256);
  drawModule(256, 256, 256);

  // Interlocking paving stone joint lines
  ctx.strokeStyle = 'rgba(0,0,0,0.18)';
  ctx.lineWidth = 1.5;
  for (let i = 0; i <= 512; i += 32) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 512); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(512, i); ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(12, 8);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// Procedural Exterior Commuter Walkway Texture (`圍牆外通學步道` 透水紅灰連鎖磚＋黃色導盲磚帶)
function makeCommuterWalkwayTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 128;
  const ctx = c.getContext('2d');
  // Warm permeable terracotta & sand-grey interlocking brick pattern
  ctx.fillStyle = '#c88068';
  ctx.fillRect(0, 0, 256, 128);
  // Outer border bands (warm concrete grey)
  ctx.fillStyle = '#d4d0c4';
  ctx.fillRect(0, 0, 256, 16);
  ctx.fillRect(0, 112, 256, 16);
  // Alternating terracotta brick courses
  const rowColors = ['#c5765e', '#b96952', '#cf846c', '#c1725a'];
  for (let y = 16; y < 112; y += 16) {
    const rowIdx = ((y - 16) / 16) | 0;
    for (let x = 0; x < 256; x += 32) {
      const shift = (rowIdx % 2) * 16;
      ctx.fillStyle = rowColors[(rowIdx + (x >> 5)) % rowColors.length];
      ctx.fillRect((x + shift) % 256, y + 1, 30, 14);
    }
  }
  // Center yellow tactile paving guide strip (`黃色導盲磚帶`)
  ctx.fillStyle = '#e0b93e';
  ctx.fillRect(0, 58, 256, 12);
  ctx.strokeStyle = 'rgba(60,40,30,0.22)';
  ctx.lineWidth = 1.5;
  for (let x = 0; x <= 256; x += 16) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 128); ctx.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(12, 1);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// 實景 Google 街景正門人行步道與迎賓廣場灰階透水連鎖地磚
function makeEntranceInterlockingBrickTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#9b9994';
  ctx.fillRect(0, 0, 512, 512);

  const brickPalette = ['#8f8d87', '#9d9b95', '#807d77', '#a5a29b', '#85827c', '#939089', '#7a7771', '#a09d96'];
  const bw = 32, bh = 16;
  let seedVal = 771;
  const rndB = () => ((seedVal = (seedVal * 16807) % 2147483647) / 2147483647);

  for (let y = 0; y < 512; y += bh) {
    const row = Math.floor(y / bh);
    const shift = (row % 2) * (bw / 2);
    for (let x = -bw; x < 512 + bw; x += bw) {
      const col = brickPalette[Math.floor(rndB() * brickPalette.length)];
      ctx.fillStyle = col;
      ctx.fillRect(x + shift + 1, y + 1, bw - 2, bh - 2);
      ctx.strokeStyle = 'rgba(30,30,30,0.28)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + shift + 0.5, y + 0.5, bw - 1, bh - 1);
    }
  }

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(10, 10);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// 實景 Google 街景大門黑色格柵上之「選擇復興 家長安心」高解析招生布條
