  ctx.fillStyle = '#f5c518';
  ctx.beginPath(); ctx.arc(245, 105, 34, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#253d37'; ctx.lineWidth = 4; ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(234, 105, 11, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(256, 105, 11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#183025';
  ctx.beginPath(); ctx.arc(234, 105, 5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(256, 105, 5, 0, Math.PI * 2); ctx.fill();
  // Orange SHING
  ctx.fillStyle = '#f26822';
  ctx.font = '900 76px "Inter", "Arial Black", sans-serif';
  ctx.fillText('SHING', 380, 105);

  // Bottom green eco-school badge
