const clickableGroups = [];
const landmarkGroupMap = new Map();

function addMesh(parent, geo, mat, x, y, z, cast = true, receive = true) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = cast;
  m.receiveShadow = receive;
  parent.add(m);
  return m;
}
function addBox(parent, w, h, d, mat, x, y, z, cast = true) {
  return addMesh(parent, new THREE.BoxGeometry(w, h, d), mat, x, y, z, cast, true);
}

