      addBox(g, 0.18, 1.12, zAx15 - cz(5025), nDadoGreenMat, xA + 0.02, y0 + 0.56, (zAx15 + cz(5025)) / 2);
      addBox(g, 0.18, 1.12, cz(5118) - zAx16, nDadoGreenMat, xA + 0.02, y0 + 0.56, (cz(5118) + zAx16) / 2);

      // 右側：白色鋁框橫百葉門 (cm 5025～5118，寬約 0.91m，高 2.10m)
      const doorZ = (cz(5025) + cz(5118)) / 2;
      const doorW = cz(5025) - cz(5118);
      const doorH = 2.10;
      addBox(g, 0.08, doorH, doorW, nAlumWhiteMat, xA + 0.03, y0 + doorH / 2, doorZ);
      addBox(g, 0.05, doorH - 0.12, doorW - 0.12, nGlassDarkMat, xA + 0.03, y0 + doorH / 2, doorZ);
      // 門扇 8 道白色水平百葉格柵
      for (let lv = 0; lv < 8; lv++) {
        addBox(g, 0.07, 0.045, doorW - 0.10, nAlumWhiteMat, xA + 0.035, y0 + 0.22 + lv * 0.24, doorZ, false);
      }
