function makeKindergartenArtWallTexture() {
  // 依實景照片高清還原（Image 1）：新棟西側 1F 露天階梯下方白磁磚牆面之幼兒園兒童繪畫成果與全彩公告展示板
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#f6f2e8';
  ctx.fillRect(0, 0, 1024, 512);
  ctx.strokeStyle = '#3d6f46';
  ctx.lineWidth = 14;
  ctx.strokeRect(7, 7, 1010, 498);

  // 綠底標題條
  ctx.fillStyle = '#2f693b';
  ctx.fillRect(24, 24, 976, 68);
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.font = 'bold 36px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('屏東復興非營利幼兒園 · 幼兒學習與作品成果展', 512, 70);

  // 8 格學生多彩童趣作品
  const hues = ['#e53935', '#1e88e5', '#43a047', '#fb8c00', '#8e24aa', '#00acc1', '#fdd835', '#6d4c41'];
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 4; col++) {
      const idx = row * 4 + col;
      const x = 40 + col * 238;
      const y = 112 + row * 186;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(x, y, 218, 168);
      ctx.strokeStyle = '#dedad0';
      ctx.lineWidth = 3;
      ctx.strokeRect(x, y, 218, 168);

      // 色塊底圖
      ctx.fillStyle = hues[idx % hues.length];
      ctx.fillRect(x + 12, y + 12, 194, 110);

      // 繪畫塗鴉圖案
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(x + 55, y + 55, 22, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#fff59d';
      ctx.fillRect(x + 105, y + 45, 80, 55);

      ctx.fillStyle = '#424242';
      ctx.font = 'bold 18px "Noto Sans TC", sans-serif';
      ctx.fillText(`主題作品 ${idx + 1}`, x + 109, y + 150);
    }
  }

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

