function makeSouthEastAbstractMuralTexture() {
  // Matches the 3-story geometric abstract mural on `⑧–⑨` South wall in `新棟南向正面_右手邊45度側面001.jpg`:
  // - 3F (top): Yellow sun with spiral center & radiating rays + slate-blue geometric blocks
  // - 2F (middle): Diagonal slate-blue musical staff / rays + orange & green geometric triangles/dots + curved brown arcs
  // - 1F (bottom): Terracotta-red concentric square spiral (`回` motif) + terracotta cross (`+`) + curved dark-brown ribs
  const c = document.createElement('canvas');
  c.width = 512; c.height = 1024;
  const ctx = c.getContext('2d');

  // Cream-white painted concrete background (`#f3efe6`)
  ctx.fillStyle = '#f3efe6';
  ctx.fillRect(0, 0, 512, 1024);

  // Subtle horizontal floor joint lines
  ctx.strokeStyle = 'rgba(180,172,158,0.45)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, 341); ctx.lineTo(512, 341);
  ctx.moveTo(0, 682); ctx.lineTo(512, 682);
  ctx.stroke();

  // --- 3F TOP SECTION (y: 40..330): Yellow Sun with Spiral & Rays ---
  ctx.save();
  // Slate-blue geometric bars on upper left
  ctx.fillStyle = '#6c7c8e';
  ctx.fillRect(48, 78, 95, 22);
  ctx.fillRect(48, 114, 24, 92);
  ctx.fillStyle = '#d47454';
  ctx.fillRect(88, 128, 52, 20);

  // Yellow Sun at upper right (cx=330, cy=180)
  const sx = 335, sy = 185;
  ctx.strokeStyle = '#f2c12e';
  ctx.lineWidth = 10;
  for (let a = 0; a < 12; a++) {
    const ang = (a / 12) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(sx + Math.cos(ang) * 58, sy + Math.sin(ang) * 58);
    ctx.lineTo(sx + Math.cos(ang) * 98, sy + Math.sin(ang) * 98);
    ctx.stroke();
  }
  ctx.fillStyle = '#f5ca3c';
  ctx.beginPath(); ctx.arc(sx, sy, 52, 0, Math.PI * 2); ctx.fill();
  // Orange spiral inside sun
  ctx.strokeStyle = '#d96b38';
  ctx.lineWidth = 5;
  ctx.beginPath();
  for (let t = 0; t < 36; t++) {
    const r = 4 + t * 1.15;
    const ang = t * 0.45;
    const px = sx + Math.cos(ang) * r, py = sy + Math.sin(ang) * r;
    if (t === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.stroke();
  ctx.restore();

  // --- 2F MIDDLE SECTION (y: 345..680): Diagonal Slate-Blue Staff & Geometric Notes ---
  ctx.save();
  ctx.strokeStyle = '#5e7086';
  ctx.lineWidth = 8;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(45, 360 + i * 24);
    ctx.lineTo(465, 555 + i * 24);
    ctx.stroke();
  }
  // Geometric color accents along the diagonal staff
  ctx.fillStyle = '#d86548';
  ctx.beginPath(); ctx.arc(210, 420, 24, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#589e64';
  ctx.beginPath(); ctx.moveTo(270, 390); ctx.lineTo(320, 435); ctx.lineTo(255, 450); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#e89c38';
  ctx.fillRect(145, 495, 42, 42);
  ctx.fillStyle = '#4c647d';
  ctx.beginPath(); ctx.arc(355, 470, 18, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  // --- 1F & LOWER-2F CURVED RIB ARCS & TERRACOTTA SPIRAL (y: 560..960) ---
  ctx.save();
  ctx.strokeStyle = '#5a3928';
  ctx.lineWidth = 10;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(165, 685, 70 + i * 24, -0.85, 0.95);
    ctx.stroke();
  }
  // Terracotta concentric square spiral (`回` labyrinth motif) on 1F right
  ctx.strokeStyle = '#c85a38';
  ctx.lineWidth = 12;
  const bx = 260, by = 710, bw = 170;
  ctx.strokeRect(bx, by, bw, bw);
  ctx.strokeRect(bx + 32, by + 32, bw - 64, bw - 64);
  ctx.fillStyle = '#c85a38';
  ctx.fillRect(bx + 68, by + 68, 34, 34);

  // Terracotta `+` cross on 1F left
  ctx.fillStyle = '#c85a38';
  ctx.fillRect(92, 775, 86, 24);
  ctx.fillRect(123, 744, 24, 86);
  ctx.restore();

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeBreezeBlockGrilleTexture() {
  // Matches the square hollow concrete breeze-block screen (`水泥空心花磚牆`) on `①–②` South 2F & 3F (`新棟正面立圖_南向.jpg`)
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#e8e4da';
  ctx.fillRect(0, 0, 512, 512);

  const cols = 10, rows = 8;
  const cw = 512 / cols, ch = 512 / rows;
  for (let r = 0; r < rows; r++) {
    for (let col = 0; col < cols; col++) {
      const x = col * cw, y = r * ch;
      // Outer mortar joint
      ctx.strokeStyle = '#c8c2b4';
      ctx.lineWidth = 3;
      ctx.strokeRect(x + 1.5, y + 1.5, cw - 3, ch - 3);
      // Dark hollow opening inside each breeze block with decorative inner ribs
      ctx.fillStyle = '#2d3235';
      ctx.fillRect(x + 7, y + 7, cw - 14, ch - 14);
      // Inner concrete diamond/cross rib inside each block
      ctx.strokeStyle = '#dcd7cb';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(x + cw / 2, y + 6); ctx.lineTo(x + cw - 6, y + ch / 2);
      ctx.lineTo(x + cw / 2, y + ch - 6); ctx.lineTo(x + 6, y + ch / 2);
      ctx.closePath();
      ctx.stroke();
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

