function makeDarkGreyTileTexture() {
  // 南棟西端牆面深灰色二丁掛磁磚 (街景照片：銜接走廊通道東側整面深灰磚牆)
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#4a4e52';
  ctx.fillRect(0, 0, 128, 128);
  const tw = 64, th = 16;
  for (let r = 0; r < 8; r++) {
    const off = (r % 2) * (tw / 2);
    for (let col = -1; col < 3; col++) {
      const x = col * tw + off, y = r * th;
      const v = 88 + ((r * 7 + col * 13) % 5) * 4;
      ctx.fillStyle = `rgb(${v},${v + 3},${v + 6})`;
      ctx.fillRect(x + 1.5, y + 1.5, tw - 3, th - 3);
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeRedBrickTexture() {
  // 通道南口磚柱 (街景照片：欄杆小門東側褐紅色磚砌方柱)
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#b9ae9d';
  ctx.fillRect(0, 0, 128, 128);
  const bw = 32, bh = 16;
  for (let r = 0; r < 8; r++) {
    const off = (r % 2) * (bw / 2);
    for (let col = -1; col < 5; col++) {
      const x = col * bw + off, y = r * bh;
      const k = (r * 5 + col * 3 + 40) % 4;
      ctx.fillStyle = ['#8e5a46', '#9a6249', '#84523f', '#a06b52'][k];
      ctx.fillRect(x + 1.5, y + 1.5, bw - 3, bh - 3);
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeGatePosterTexture() {
  // 欄杆小門右側銀灰色金屬銘牌（實景照片 20261106_142631.jpg：「屏東縣屏東復興非營利幼兒園（委託財團法人彭婉如文教基金會辦理）」）
  const c = document.createElement('canvas');
  c.width = 512; c.height = 340;
  const ctx = c.getContext('2d');
  const grad = ctx.createLinearGradient(0, 0, 512, 340);
  grad.addColorStop(0, '#dcdfe3');
  grad.addColorStop(0.5, '#cbd0d6');
  grad.addColorStop(1, '#b8bec5');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 512, 340);
  ctx.strokeStyle = '#8c929a';
  ctx.lineWidth = 8;
  ctx.strokeRect(4, 4, 504, 332);
  ctx.fillStyle = '#1e2228';
  ctx.textAlign = 'center';
  ctx.font = 'bold 31px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('屏東縣屏東復興非營利幼兒園', 256, 145);
  ctx.fillStyle = '#383e46';
  ctx.font = 'bold 20px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('（委託財團法人彭婉如文教基金會辦理）', 256, 215);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeSouthFenceBannerTexture() {
  // 銜接通道東側七彩欄杆懸掛之粉紅色幼兒園招生布條（實景照片 20261106_142631.jpg）
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 192;
  const ctx = c.getContext('2d');
  const bg = ctx.createLinearGradient(0, 0, 1024, 192);
  bg.addColorStop(0, '#f7d8e2');
  bg.addColorStop(0.5, '#f4c8d8');
  bg.addColorStop(1, '#f7d4e0');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, 1024, 192);

  // 雲朵「招生中」圖章
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.roundRect(45, 22, 165, 54, 27);
  ctx.fill();
  ctx.strokeStyle = '#5ab4e6';
  ctx.lineWidth = 4;
  ctx.stroke();
  ctx.fillStyle = '#2979b8';
  ctx.font = 'bold 30px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('招生中', 127, 60);

  // 彩虹標題字：「屏東縣屏東復興非營利幼兒園」
  const chars = ['屏', '東', '縣', '屏', '東', '復', '興', '非', '營', '利', '幼', '兒', '園'];
  const charCols = ['#e63968', '#eb6834', '#d94878', '#e65c8a', '#f08a24', '#c92a58', '#9e368c', '#e63968', '#f29f05', '#429e38', '#2575b8', '#7d3c98', '#2b8a3e'];
  ctx.font = 'bold 46px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  chars.forEach((ch, idx) => {
    const x = 250 + idx * 54;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 7;
    ctx.strokeText(ch, x, 74);
    ctx.fillStyle = charCols[idx % charCols.length];
    ctx.fillText(ch, x, 74);
  });

  // 副標題與報名資訊
  ctx.fillStyle = '#6b2d46';
  ctx.font = 'bold 28px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('（委託財團法人彭婉如文教基金會辦理）', 540, 124);
  ctx.fillStyle = '#7a1f3d';
  ctx.font = 'bold 24px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('報名專線 (08)7550700   招生對象：2歲以上至國民小學前幼兒', 540, 168);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeTerracottaTilePatternTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#c65338';
  ctx.fillRect(0, 0, 256, 256);
  ctx.strokeStyle = '#9e3b24';
  ctx.lineWidth = 3;
  for (let r = 0; r < 8; r++) {
    const y = r * 32;
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(256, y); ctx.stroke();
    const offset = (r % 2) * 32;
    for (let col = 0; col < 5; col++) {
      const x = col * 64 + offset;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 32); ctx.stroke();
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(3, 2);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// ---- 04 新棟（復興非營利幼兒園） (`buildNew` — 1:1 Floor Plan & Photo-Accurate Build) ----
{
  const g = new THREE.Group();
  g.userData = { landmarkId: 'new-building' };

  // ==========================================================================
  // 1. EXACT 11-AXIS STRUCTURAL GRID (①～⑪, Total = 3361 cm = 33.61 m)
  //    & A～G DEPTH AXES from `新棟1F/2F/3F建築平面圖.jpg` (Scale 1:150)
  // ==========================================================================
  // Span widths (cm): 452, 450, 450, 53, 397, 213, 237, 457.5, 401.5, 250
  const AXIS_CM = [0, 0, 452, 902, 1352, 1405, 1802, 2015, 2252, 2709.5, 3111, 3361];
  const xWest = -37.83; // Axis ①, so Axis ⑪ = -37.83 + 33.61 = -4.22m (exact west face of 南棟!)
  const ax = idx => xWest + AXIS_CM[idx] * 0.01;

  // Depth coordinates (Z in meters, North is smaller Z, South is larger Z):
  // Aligned so `zC = 20.28m` matches South Building's south facade and `zG_south = 8.78m` meets South Building's north corridor!
  const zG  = 8.780;   // North end of `⑩–⑪ 共用走廊` (meets South Building's North Corridor at Z = 8.78m)
  const zF  = 13.398;  // North face of `④–⑥` North Stairwell & `⑥–⑩` 1F Accessible Ramp
  const zE  = 15.918;  // North Corridor outer line (`④–⑩`) & South wall of `西棟` (`①–④`)
  const zD  = 19.053;  // North wall of 新棟 classrooms (`①–⑩`)
  const zC  = 20.280;  // South wall of `南棟` (`⑪` east connection)
  const zB  = 24.153;  // South wall of 新棟 classrooms (`①–⑧`) & South outer wall of Restrooms/Kitchen (`⑧–⑩`)
  const zA  = 26.703;  // South Corridor / Balcony outer edge (`①–⑧`)

  // Floor Heights (3 stories)
  const FH = 3.60;
  const y1F = 0.0, y2F = FH, y3F = FH * 2, yRF = FH * 3; // 0.0, 3.6, 7.2, 10.8m
  const parapetH = 1.12;

  // Custom Materials
  const creamWallMat     = new THREE.MeshStandardMaterial({ color: 0xf2eee3, roughness: 0.72 });
  const whiteTileMat     = mats.wallTile;
  const darkCopingMat    = new THREE.MeshStandardMaterial({ color: 0x45494e, roughness: 0.65 });
  const terracottaBoxMat = new THREE.MeshStandardMaterial({ map: makeTerracottaTilePatternTexture(), roughness: 0.68 });
  const greenDiamondMat  = new THREE.MeshStandardMaterial({ color: 0x1c5e3a, roughness: 0.42, metalness: 0.15 });
  const diamondRimMat    = new THREE.MeshStandardMaterial({ color: 0xf4f1e8, roughness: 0.55 });
  const roofTileRedMat   = new THREE.MeshStandardMaterial({ color: 0xb84630, roughness: 0.62 });
  const greenBlindMat    = new THREE.MeshStandardMaterial({ color: 0x289c4e, roughness: 0.58, side: THREE.DoubleSide });
  const acUnitMat        = new THREE.MeshStandardMaterial({ color: 0xdcdad2, roughness: 0.55, metalness: 0.2 });
  const pvcPipeMat       = new THREE.MeshStandardMaterial({ color: 0xf7f7f5, roughness: 0.35 });
  const handrailMat      = new THREE.MeshStandardMaterial({ color: 0xd8dfe3, roughness: 0.3, metalness: 0.65 });
  const whiteMetalMat    = new THREE.MeshStandardMaterial({ color: 0xf4f6f7, roughness: 0.35, metalness: 0.45 });
  const coneOrangeMat    = new THREE.MeshStandardMaterial({ color: 0xf25c19, roughness: 0.45 });
  const exposedConcreteBeamMat = new THREE.MeshStandardMaterial({ color: 0x545b66, roughness: 0.82 }); // 實景照片標誌性清水混凝土結構過梁
  const roofMetalMat     = new THREE.MeshStandardMaterial({ color: 0xd2d7dc, roughness: 0.42, metalness: 0.4 }); // 屋頂金屬挑簷與收邊滴水條

  // 西棟與新棟連通樓梯專屬材質
  const terrazzoStepMat  = new THREE.MeshStandardMaterial({ color: 0xcdc9bf, roughness: 0.65 });
  const stairNosingMat   = new THREE.MeshStandardMaterial({ color: 0x26282b, roughness: 0.75 });
  const brassNosingMat   = new THREE.MeshStandardMaterial({ color: 0xc8a452, roughness: 0.32, metalness: 0.75 });
  const woodHandrailMat  = new THREE.MeshStandardMaterial({ color: 0x824e2c, roughness: 0.45 });
  const stainlessMat     = new THREE.MeshStandardMaterial({ color: 0xdce2e8, roughness: 0.24, metalness: 0.84 });
  const blueShutterMat   = new THREE.MeshStandardMaterial({ map: makeBlueRollerShutterTexture(), roughness: 0.42, side: THREE.DoubleSide });
  const meshWindowMat    = new THREE.MeshStandardMaterial({ map: makeDiamondMeshWindowTexture(), roughness: 0.45, side: THREE.DoubleSide });
  const indoorSignMat    = new THREE.MeshBasicMaterial({ map: makeKindergartenIndoorPortalSignTexture(), side: THREE.DoubleSide });
  const west2FDoorMat    = new THREE.MeshStandardMaterial({ map: makeWest2FStairDoorTexture(), roughness: 0.50, side: THREE.DoubleSide });
  const dadoBrickMat     = new THREE.MeshStandardMaterial({ color: 0x7a3b2e, roughness: 0.76 });

  // Helper: Protruding Terracotta Brick Balcony Box with 45° Rotated Green Diamond Medallion
  function addTerracottaBalconyBox(cx, cy, cz, boxW, boxH, boxD, faceDirZ = -1) {
    addBox(g, boxW, boxH, boxD, terracottaBoxMat, cx, cy, cz);
    // White ceramic border trim on top & bottom of brick box
    addBox(g, boxW + 0.06, 0.08, boxD + 0.04, diamondRimMat, cx, cy + boxH / 2 + 0.04, cz);
    addBox(g, boxW + 0.06, 0.08, boxD + 0.04, diamondRimMat, cx, cy - boxH / 2 - 0.04, cz);

    // 45° Rotated Square (Diamond) Green Tile Medallion in the center
    const dGroup = new THREE.Group();
    dGroup.position.set(cx, cy, cz + faceDirZ * (boxD / 2 + 0.025));
    const rimMesh = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.56, 0.04), diamondRimMat);
    rimMesh.rotation.z = Math.PI / 4;
    dGroup.add(rimMesh);
    const gemMesh = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.42, 0.06), greenDiamondMat);
    gemMesh.rotation.z = Math.PI / 4;
    dGroup.add(gemMesh);
    g.add(dGroup);
  }

  // ==========================================================================
  // 2. MAIN CLASSROOM & RESTROOM CORE (`①–⑩`, `zD = 19.053m` to `zB = 24.153m`)
  // ==========================================================================
  const coreW = ax(10) - ax(1); // 31.11m
  const coreD = zB - zD;        // 5.10m
  const coreCx = (ax(1) + ax(10)) / 2;
  const coreCz = (zD + zB) / 2;

  // Core structural body
  addBox(g, coreW, yRF, coreD, creamWallMat, coreCx, yRF / 2, coreCz);

  // ==========================================================================
  // 2.1 【西棟與新棟 100% 緊鄰無縫銜接建築體】(`①–④`, `zE = 15.918m` 至 `zD = 19.053m`)
  // 徹底消除兩棟交接處之 3.135m 綠地空隙！西棟大樓與新棟大樓完全緊密相連：
  // - 1F: 設貫通操場跑道至中庭之挑高穿堂（底層淨空通透，上方設深灰結構梁與結構板）
  // - 2F/3F: 通暢開放之北側走廊（走廊樓板連貫，北側設白色二丁掛磁磚欄杆與深灰壓頂）
  // - RF: 屋頂層結構板與防水女兒牆無縫銜接西棟女兒牆，平屋頂防水層與收邊
  // ==========================================================================
  const juncW = ax(4) - ax(1); // 13.52m (完美銜接西棟總進深 13.80m)
  const juncD = zD - zE;        // 3.135m (無縫填滿 zE=15.918 至 zD=19.053)
  const juncCx = (ax(1) + ax(4)) / 2; // -31.07m
  const juncCz = (zE + zD) / 2;        // 17.4855m

  // 1F 地面混凝土結構地坪（貫通穿堂走道，徹底覆蓋綠地，無縫銜接西棟與新棟地坪）
  addBox(g, juncW + 0.10, 0.25, juncD + 0.04, mats.concrete, juncCx, 0.125, juncCz);

  // 2F 與 3F 開放走廊北側外護欄矮牆（帶深灰壓頂，保持走廊內部完全通透）
  for (let f = 1; f <= 2; f++) {
    const fy = f * FH;
    addBox(g, juncW, parapetH, 0.26, whiteTileMat, juncCx, fy + parapetH / 2, zE + 0.13);
    addBox(g, juncW + 0.06, 0.08, 0.32, darkCopingMat, juncCx, fy + parapetH + 0.04, zE + 0.13);
  }

  // 2F, 3F, RF 結構樓板層（自 zE = 15.918m 貫通至 zD = 19.053m）
  [y2F, y3F, yRF].forEach(fy => {
    addBox(g, juncW + 0.10, 0.30, juncD + 0.04, mats.slab, juncCx, fy + 0.15, juncCz);
  });

  // 1F 頂部結構梁（支撐 2F 樓板，梁下淨高 3.1m 為貫通穿堂與室內過渡階梯）
  addBox(g, juncW, 0.50, 0.40, exposedConcreteBeamMat, juncCx, y2F - 0.25, zE + 0.20);
  addBox(g, juncW, 0.50, 0.40, exposedConcreteBeamMat, juncCx, y2F - 0.25, zD - 0.20);

  // 沿 ①–④ 跨距（②、③、④ 軸）之結構支撐方柱（貫通 1F～3F）
  [1, 2, 3, 4].forEach(idx => {
    addBox(g, 0.44, yRF, 0.44, whiteTileMat, ax(idx), yRF / 2, zE + 0.22);
  });

  // 2F & 3F 北向採光窗戶（面向中庭/穿堂上方）
  for (let f = 1; f <= 2; f++) {
    const fy = f * FH;
    for (let bIdx = 2; bIdx <= 3; bIdx++) {
      const bx1 = ax(bIdx), bx2 = ax(bIdx + 1);
      const bw = bx2 - bx1, bcx = (bx1 + bx2) / 2;
      const winMatN = makeWindowMaterial(`new-junc-n-${f}-${bIdx}`);
      const wp = addMesh(g, new THREE.PlaneGeometry(bw - 0.85, 1.80), winMatN, bcx, fy + 1.85, zE + 0.05, false);
      wp.rotation.y = Math.PI;
    }
  }

  // 屋頂女兒牆與防水壓頂（封閉北緣與西棟交界處）
  addBox(g, juncW, parapetH, 0.28, whiteTileMat, juncCx, yRF + parapetH / 2, zE + 0.14);
  addBox(g, juncW + 0.06, 0.08, 0.34, darkCopingMat, juncCx, yRF + parapetH + 0.04, zE + 0.14);

  // Structural columns along Axes ①–⑩ at zD and zB
  for (let idx = 1; idx <= 10; idx++) {
    const colX = ax(idx);
    addBox(g, 0.42, yRF, 0.42, whiteTileMat, colX, yRF / 2, zD);
    addBox(g, 0.42, yRF, 0.42, whiteTileMat, colX, yRF / 2, zB);
  }

  // Classroom North & South Windows + Doors + Transom AC Units (依 CAD 1F/3F 平面圖：②–③、③–④、④–⑤、⑤–⑥、⑥–⑦、⑦–⑧)
  const classBays = [2, 3, 4, 5, 6, 7]; // Bays ②-③ (幼兒班101), ③-④ (幼兒班102/301), ④-⑤ (301東側/梯間), ⑤-⑦ (梯間), ⑦-⑧ (302)
  for (let f = 0; f < 3; f++) {
    const fy = f * FH;
    classBays.forEach((bIdx, i) => {
      const bx1 = ax(bIdx);
      const bx2 = ax(bIdx + 1);
      const bw = bx2 - bx1;
      const bcx = (bx1 + bx2) / 2;

      // South Classroom Windows (facing South Corridor at `zB`)
      const winMatS = makeWindowMaterial(`new-s-${f}-${i}`);
      addMesh(g, new THREE.PlaneGeometry(bw - 0.85, 1.85), winMatS, bcx, fy + 1.85, zB + 0.03, false);
      // Window-mounted AC unit in upper transom (`新棟正面立圖_南向.jpg`)
      addBox(g, 0.68, 0.44, 0.48, acUnitMat, bcx + bw * 0.24, fy + 2.95, zB + 0.22);

      // North Classroom Windows & Doors (facing North Corridor at `zD`, for bays `⑥–⑧`)
      if (bIdx >= 6) {
        const winMatN = makeWindowMaterial(`new-n-${f}-${i}`);
        const wpN = addMesh(g, new THREE.PlaneGeometry(bw - 0.85, 1.80), winMatN, bcx, fy + 1.85, zD - 0.03, false);
        wpN.rotation.y = Math.PI;
      }
    });
  }

  // ==========================================================================
  // 3. NORTH FACADE (COURTYARD SIDE — 依據實景照片與 1F 建築平面圖極致精緻化)
  //    - 紅框主立面 (④–⑩):
  //      * ④–⑥ (ax(4) 至 ax(6)，面寬 4.50m): 3 層樓挑高外凸北向主入口門樓與折返式雙跑樓梯間
  //        - 1F 迎賓門樓：深褐底燙金長橢圓「屏東縣 屏東復興非營利幼兒園」立體厚銘板招牌 (含金屬固定懸臂與射燈)
  //        - 1F 扇形/加寬迎賓磨石子階梯 (6 階，下階漸擴)、斜向雙翼洗石子導角扶手矮牆 (Cheek Walls)
  //        - 1F 雙重門禁：白色烤漆垂直方管安全柵欄門 (帶金屬天地栓與插銷) + 鋁合金雙開採光玻璃大門
  //        - 門前中庭地坪：2 頂亮橘色反光警示三角錐 (Traffic Cones)
  //        - 2F/3F 挑空半戶外通風樓梯間：外露清水斜向階梯梁板、清水混凝土水平結構深梁、中間雙向休息平台、雙層不銹鋼管防墜安全扶手、
  //          白色磁磚矮牆與深灰壓頂線腳、走廊天花板吸頂照明投光燈
  //        - 門樓頂部：高聳梯間突出部、銀白金屬防雨簷口包邊與斜向排水挑簷 (Stepped Roof Parapet & Metal Canopy Eaves)
  //      * ⑥–⑩ (ax(6) 至 ax(10)，面寬 13.09m): 1F~3F 北側主走廊
  //        - 水平結構：1F、2F、3F 過梁統一採用實景標誌性之「深灰清水混凝土深梁」(Exposed Concrete Beams)
  //        - 2F 與 3F 中央：外凸橘紅陶磚立體陽台盒 (⑧–⑨ 間)，中央嵌入 45° 菱形深綠磁磚浮雕勳章與象牙白邊框
  //        - 陶磚盒右側：白色 PVC 垂直落水引流管 (沿 1F~3F 貫穿至地面暗溝)
  //        - 走廊外牆：白色洗石子垂直柱列與白色二丁掛磁磚欄杆，教室側設鋁合金橫拉排窗
  //      * 前景花園景觀與 1F 無障礙緩坡道 (Garden Lawn & Accessible Ramp):
  //        - 翠綠草皮起伏土丘與洗石子弧形收邊緣石 (Curved Lawn Bed Curbing)
  //        - 造型優美的雞蛋花樹 (Plumeria Tree)：多歧分枝木質老幹、傘狀翠綠聚生葉簇與白色雞蛋花瓣
  //        - 挺拔直立圓錐形深綠龍柏 (Conical Juniper Evergreen)
  //        - 複層多層次常綠修剪低矮綠籬灌木帶 (Trimmed Boxwood & Privet Hedges)
  //        - 景觀造景花崗岩巨石 (Natural Landscaping Boulders)
  //        - 依 1F 平面圖精確配置之行動不便緩坡道 (+120 高程無障礙斜坡地坪、鍍鋅鋼管雙層安全護欄、新設黃色活動門)
  //    - 黃框轉折棟 (⑩–⑪):
  //      * ⑩–⑪ (ax(10) 至 ax(11)，面寬 2.50m): 3 層樓 L 型轉折共用走廊 (共用走廊 向北延伸至 zG = 8.78m)
  //      * 轉角中庭前庭植栽一株【高聳繁茂校園綠樹】(Large Courtyard Shade Tree)，枝葉扶疏貫穿 1F~3F，完美還原照片黃框構圖
  //      * 1F~3F 西向與北向白色磁磚通風欄杆，1F 平台緣石整齊陳列陶製植栽花盆與基底綠籬矮牆
  //      * 1F 西側銜接中庭花磚地坪之 4 階踏步階梯與側向引導坡道
  //      * 平屋頂頂角配置全校廣播金屬號角高音喇叭 (Broadcast Horn Speakers)
  // ==========================================================================
  {
    // ------------------------------------------------------------------------
    // 【西棟與新棟交界處・中庭轉角相接接縫與落水管】（依實景照片 Image 3）
    // 位於西棟東走廊（x=-24.31）與新棟北樓梯塔（zE=15.918）之 90 度陰角交接處
    // ------------------------------------------------------------------------
    const juncCornerX = ax(4); // -24.31m
    const juncCornerZ = zE;    // 15.918m
    // 白色垂直 PVC 雨水落水立管（貫穿 1F～3F 至地面排水暗溝，直徑 12cm）
    addMesh(g, new THREE.CylinderGeometry(0.06, 0.06, yRF + 0.6, 12), pvcPipeMat, juncCornerX + 0.12, (yRF + 0.6) / 2, juncCornerZ - 0.12, false);
    for (let f = 0; f <= 3; f++) {
      addBox(g, 0.16, 0.04, 0.16, darkCopingMat, juncCornerX + 0.12, f * FH + 1.25, juncCornerZ - 0.12, false); // 不銹鋼管箍固定座
    }

    // ------------------------------------------------------------------------
    // 3.1 【紅框右側門樓與樓梯間】⑤–⑦ (ax(5)=-23.78 至 ax(7)=-17.68, zF=13.398 至 zD=19.053)
    // ------------------------------------------------------------------------
    const stX1 = ax(5), stX2 = ax(7); // 依 1F/3F 建築平面圖：梯間位於 ⑤–⑦ 軸 (14.05m~20.15m，寬 6.10m)
    const stW = stX2 - stX1; // 6.10m
    const stCx = (stX1 + stX2) / 2;
    const stD = zD - zF;     // 5.655m
    const stCz = (zF + zD) / 2;
    const stTopY = yRF + 2.05; // 梯間塔樓高於 3F 屋頂約 2.05m (照片：3F 深梁上方尚有磁磚牆與鋼板屋頂)

    // 梯塔主體結構側牆與頂板 (西側山牆、東側隔牆、頂部結構板)
    // 西側在 1F~3F 為通往西棟之連通樓梯通道，徹底移除阻擋 1F/2F/3F 之實體封閉牆！僅在屋頂層 (y >= yRF) 保留梯塔山牆：
    addBox(g, 0.38, stTopY - yRF, stD, whiteTileMat, stX1 + 0.19, (yRF + stTopY) / 2, stCz);
    addBox(g, 0.38, stTopY, stD, whiteTileMat, stX2 - 0.19, stTopY / 2, stCz);
    addBox(g, stW, 0.35, stD, mats.roof, stCx, stTopY, stCz);

    // 梯塔頂部：磁磚牆體 + 深灰梁帶 + 低坡度鋼板屋頂與銀白包邊 (照片 3F 以上梯間頂部)
    addBox(g, stW, stTopY - yRF, 0.30, whiteTileMat, stCx, (yRF + stTopY) / 2, zF + 0.15);
    addBox(g, stW + 0.04, 0.46, 0.38, exposedConcreteBeamMat, stCx, yRF + 0.23, zF + 0.17);
    for (const side of [-1, 1]) {
      const pitch = 0.09;
      const half = stD / 2 + 0.25;
      const panel = new THREE.Mesh(new THREE.BoxGeometry(stW + 0.30, 0.06, half / Math.cos(pitch)), roofMetalMat);
      panel.position.set(stCx, stTopY + 0.30 - half * Math.sin(pitch) * 0.5, stCz + side * half * 0.5);
      panel.rotation.x = side * pitch;
      g.add(panel);
    }
    addBox(g, stW + 0.36, 0.16, 0.10, roofMetalMat, stCx, stTopY + 0.16, zF - 0.30);   // 前緣銀白包邊
    addBox(g, stW + 0.44, 0.05, 0.14, whiteMetalMat, stCx, stTopY + 0.06, zF - 0.30); // 滴水條

    // 1F 迎賓門楣橫梁：照片中 1F/2F 間為深灰清水混凝土水平深梁 (正面不貼磁磚)
    addBox(g, stW, 0.52, 0.42, exposedConcreteBeamMat, stCx, 3.36, zF + 0.20);
    addBox(g, stW + 0.10, 0.06, 0.46, darkCopingMat, stCx, 3.08, zF + 0.20);

    // 入口偏向東側 (照片畫面左側)：招牌、柵門、階梯皆對齊同一中心線 entCx
    const entCx = ax(1) + 18.25; // 1F 平面圖入口階梯中心 (⑥ 軸東側，位於梯塔東段)
    const nSteps = 6, stepRun = 0.34, stepRise = 0.12;
    const landingY = nSteps * stepRise; // 0.72m 入口平台高程
    const stairBaseMat = new THREE.MeshStandardMaterial({ color: 0xc6c3ba, roughness: 0.70 }); // 洗石子階梯
    const nosingMat = new THREE.MeshStandardMaterial({ color: 0x7c786e, roughness: 0.55 });
    const alumFrameMat = new THREE.MeshStandardMaterial({ color: 0x5a636a, roughness: 0.4, metalness: 0.6 });
    const gateGlassMat = new THREE.MeshStandardMaterial({ color: 0x7fa3b4, roughness: 0.15, metalness: 0.25, transparent: true, opacity: 0.55 });

    // 【幼兒園招牌】照片實景：黑底白字長橢圓(膠囊形)壓克力招牌「屏東復興非營利幼兒園」，
    // 單行字、緊貼 1F 玻璃門窗上方牆面、位於深梁下緣，寬約 2.15m × 高約 0.56m
    const signW = 2.38, signH = 0.78, signR = signH * 0.46, signY = 2.82;
    const signShape = new THREE.Shape();
    signShape.moveTo(-signW / 2 + signR, -signH / 2);
    signShape.lineTo(signW / 2 - signR, -signH / 2);
    signShape.absarc(signW / 2 - signR, 0, signR, -Math.PI / 2, Math.PI / 2, false);
    signShape.lineTo(-signW / 2 + signR, signH / 2);
    signShape.absarc(-signW / 2 + signR, 0, signR, Math.PI / 2, Math.PI * 1.5, false);
    const plaqueRimMat = new THREE.MeshStandardMaterial({ color: 0xdcb868, roughness: 0.25, metalness: 0.75 });
    const signBodyMat = new THREE.MeshStandardMaterial({ color: 0x15171b, roughness: 0.35, metalness: 0.2 });
    const signBody = new THREE.Mesh(
      new THREE.ExtrudeGeometry(signShape, { depth: 0.06, bevelEnabled: true, bevelThickness: 0.012, bevelSize: 0.012, bevelSegments: 1 }),
      signBodyMat);
    signBody.position.set(entCx, signY, zF - 0.01);
    signBody.rotation.y = Math.PI; // 正面朝北 (-z)
    g.add(signBody);
    const signTex = makeKindergartenBlackSignTexture();
    const signFace = addMesh(g, new THREE.PlaneGeometry(signW, signH), new THREE.MeshBasicMaterial({ map: signTex, transparent: true }), entCx, signY, zF - 0.092, false);
    signFace.rotation.y = Math.PI;

    // 1F 鋁窗玻璃帷面 (整面門樓寬度，含垂直窗框與橫向氣窗分割，位於入口平台上)
    addBox(g, stW - 0.40, landingY, 0.55, mats.concrete, stCx, landingY / 2, zF + 0.275);
    const glassBandH = 2.50 - landingY - 0.08;
    const glassBandY = landingY + 0.08 + glassBandH / 2;
    addBox(g, stW - 0.50, glassBandH, 0.06, gateGlassMat, stCx, glassBandY, zF + 0.42, false);
    addBox(g, stW - 0.46, 0.07, 0.10, alumFrameMat, stCx, 2.50, zF + 0.42);              // 上框
    addBox(g, stW - 0.46, 0.07, 0.10, alumFrameMat, stCx, landingY + 0.08, zF + 0.42);    // 下框
    addBox(g, stW - 0.46, 0.05, 0.10, alumFrameMat, stCx, 1.95, zF + 0.42);               // 橫向氣窗分割
    for (let m = 0; m <= 8; m++) {
      addBox(g, 0.06, glassBandH, 0.10, alumFrameMat, stCx - (stW - 0.46) / 2 + m * (stW - 0.46) / 8, glassBandY, zF + 0.42, false);
    }
    // 入口雙開玻璃門 (中央門框較粗)
    addBox(g, 0.08, glassBandH, 0.12, alumFrameMat, entCx, glassBandY, zF + 0.43, false);
    // 入口旁藍色公告小標示牌 (照片玻璃窗上之藍色貼牌)
    addBox(g, 0.22, 0.30, 0.02, new THREE.MeshStandardMaterial({ color: 0x2f6fb5, roughness: 0.5 }), entCx + 0.62, 1.55, zF + 0.355, false);

    // 白色烤漆垂直方管安全柵欄門 (位於入口平台前緣，寬約 2.0m)
    const gateW = 2.30;
    const gateBot = landingY + 0.10, gateTop = landingY + 1.18;
    addBox(g, gateW, 0.07, 0.07, whiteMetalMat, entCx, gateTop, zF + 0.20);
    addBox(g, gateW, 0.07, 0.07, whiteMetalMat, entCx, gateBot, zF + 0.20);
    const nPick = 16;
    for (let p = 0; p <= nPick; p++) {
      const px = entCx - gateW / 2 + (p / nPick) * gateW;
      addBox(g, 0.03, gateTop - gateBot, 0.03, whiteMetalMat, px, (gateTop + gateBot) / 2, zF + 0.20, false);
    }
    addBox(g, 0.10, 0.14, 0.06, plaqueRimMat, entCx + 0.05, landingY + 0.60, zF + 0.17, false);

    // 【1F 迎賓階梯】6 階洗石子階梯，寬約 2.1m，下階漸寬
    for (let s = 0; s < nSteps; s++) {
      const sz = zF - (nSteps - s - 0.5) * stepRun;
      const sh = (s + 1) * stepRise;
      const sw = 2.50 + (nSteps - s - 1) * 0.08;
      addBox(g, sw, sh, stepRun, stairBaseMat, entCx, sh / 2, sz);
      addBox(g, sw, 0.02, 0.05, nosingMat, entCx, sh + 0.01, sz - stepRun / 2 + 0.03, false);
    }

    // 階梯兩側：西側(照片右側)為長條白色磁磚低矮花台牆 + 深灰壓頂；東側為短翼牆
    const wallZ = zF - nSteps * stepRun * 0.5;
    const wLen = (entCx - 1.66) - (stX1 + 0.25);
    addBox(g, wLen, 1.00, nSteps * stepRun + 0.45, whiteTileMat, stX1 + 0.25 + wLen / 2, 0.50, wallZ + 0.1);
    addBox(g, wLen + 0.06, 0.08, nSteps * stepRun + 0.52, darkCopingMat, stX1 + 0.25 + wLen / 2, 1.04, wallZ + 0.1);
    for (const side of [-1, 1]) {
      const cheekX = entCx + side * 1.66;
      const nSegments = 4;
      const segLen = (nSteps * stepRun + 0.30) / nSegments;
      for (let k = 0; k < nSegments; k++) {
        const segZ = (zF + 0.15) - (k + 0.5) * segLen;
        const segH = 1.05 - k * 0.20;
        addBox(g, 0.26, segH, segLen + 0.02, whiteTileMat, cheekX, segH / 2, segZ);
        addBox(g, 0.30, 0.07, segLen + 0.03, darkCopingMat, cheekX, segH + 0.035, segZ);
      }
    }

    // 階梯東側地面一頂橘色交通錐 (照片黃色活動護欄旁)
    {
      const coneX = entCx + 2.25, coneZ = zF - nSteps * stepRun - 0.40;
      addBox(g, 0.38, 0.04, 0.38, new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.8 }), coneX, 0.02, coneZ, false);
      addMesh(g, new THREE.ConeGeometry(0.14, 0.68, 14), coneOrangeMat, coneX, 0.38, coneZ, false);
      addMesh(g, new THREE.CylinderGeometry(0.065, 0.085, 0.12, 14), whiteMetalMat, coneX, 0.44, coneZ, false);
      addMesh(g, new THREE.CylinderGeometry(0.095, 0.115, 0.10, 14), whiteMetalMat, coneX, 0.30, coneZ, false);
    }

    // ------------------------------------------------------------------------
    // 【西棟與新棟 1F / 2F / 3F 室內連通高低差向下階梯通道與景觀立面】
    // 依據建築平面圖 (new_plan_1f.jpg, new_plan_2f.jpg, new_plan_3f.jpg)
    // 與現場實景實拍照片極致精細還原：
    //   - 新棟1F通往西棟1F_樓梯通道.jpg & 西棟1F通往新棟1F_樓梯通道.jpg
    //   - 新棟2F通往西棟2F_樓梯通道.jpg & 西棟2F通往新棟2F_樓梯通道.jpg
    //   - 新棟大樓正面立圖_向北面.jpg
    //
    // 核心建築規範與方向：
    // 1. 東西走向 (X 軸)：新棟大樓在東側，西棟大樓在西側。
    //    新棟 1F/2F/3F 要通往隔壁西棟大樓，一律使用東西走向階梯【向下 (WESTWARD / DOWN)】前往！
    // 2. 梯段起訖 (X 軸)：
    //    - 西端底層門洞：ax(4) = -24.31m（西棟東走廊邊界）
    //    - 梯段長度：11 階踏階 × 0.28m = 2.80m，到達 x = -21.51m
    //    - 東端頂層平台：x = -21.51m 至 ax(6) = -19.81m（面寬 1.70m），向南銜接新棟各層走廊
    //    - 西棟端頭休息平台：xCoreEast=-27.04m 至 ax(4)=-24.31m（面寬 2.73m，中心 -25.675m）
    // 3. 南北向寬度 (Z 軸)：
    //    - 位於 Axis E (zE = 15.918m) 至 Axis F (zF = 13.398m) 之間（總跨深 2.52m）
    //    - 階梯淨寬 2.05m，中心 stairZ = 14.658m (z = 13.633m 至 15.683m)
    //    - 南側 (z = 15.80m)：實體矮牆帶暗紅原木扶手與不銹鋼立柱，底座帶紅褐色磁磚踢腳線
    //    - 北側 (z = 13.51m)：面向中庭之實體二丁掛磁磚女兒牆帶深灰壓頂與不銹鋼原木安全扶手
    // ------------------------------------------------------------------------
    const xStairWest = ax(4);       // -24.31m (西棟邊界門柱線)
    const xEast = xStairWest;       // -24.31m (西棟走廊東界)
    const xCoreEast = -27.04;       // -27.04m (西棟走廊西緣牆面線)
    const xStairEast = -21.51;      // 階梯頂部起步線 (梯段面寬 2.80m)
    const xTopLandEast = ax(6);     // -19.81m (新棟頂層平台東界，深 1.70m)
    const stairBayW = xStairEast - xStairWest; // 2.80m
    const topLandW = xTopLandEast - xStairEast; // 1.70m
    const wLandingCx = (xCoreEast + xEast) / 2; // -25.675m (西棟端頭平台中心)
    const wLandingW = xEast - xCoreEast;        // 2.73m
    const stairZ = (zE + zF) / 2;              // 14.658m
    const stairClearDepth = 2.05;               // 踏面通透淨寬
    const nStepsWest = 11;                      // 11 階踏階 (依西棟2F實拍數出 11 risers)

    // ========================================================================
    // A. 1F 室內連通向下階梯 (新棟 1F +120 -> 西棟 1F +40，高低差 0.80m，8 階踏步)
    // ========================================================================
    const y1F_west = 0.40;
    const y1F_new = 1.20;
    const n1FSteps = 8;
    const rise1F = (y1F_new - y1F_west) / n1FSteps; // 0.10m
    const run1F = stairBayW / n1FSteps;             // 0.35m

    // 1.1 西棟 1F 下層休息平台地坪 (磨石子地坪)
    addBox(g, wLandingW + 0.10, 0.40, stairClearDepth + 0.40, terrazzoStepMat, wLandingCx, y1F_west - 0.20, stairZ);
    // 西端牆面紅褐色腰壁 (實拍畫面底部)
    addBox(g, 0.08, 0.92, stairClearDepth + 0.40, dadoBrickMat, xCoreEast + 0.05, y1F_west + 0.46, stairZ);
    // 西端牆面左側：深藍色烤漆鐵捲門與頂部捲筒收納箱 (實拍畫面正前方)
    const shutter1FZ = stairZ + 0.42;
    const shutter1FW = 1.05;
    const shutterMesh = addMesh(g, new THREE.PlaneGeometry(shutter1FW, 2.35), blueShutterMat, xCoreEast + 0.10, y1F_west + 1.175, shutter1FZ, false);
    shutterMesh.rotation.y = Math.PI / 2;
    addBox(g, 0.28, 0.32, shutter1FW + 0.08, blueShutterMat, xCoreEast + 0.14, y1F_west + 2.35 + 0.16, shutter1FZ); // 鐵捲門上方外凸收納箱
    // 西端牆面右側：菱形鐵網防盜鋁排窗 (實拍畫面右側)
    const win1FZ = stairZ - 0.55;
    const win1FW = 1.00;
    const win1FMesh = addMesh(g, new THREE.PlaneGeometry(win1FW, 1.30), meshWindowMat, xCoreEast + 0.10, y1F_west + 1.60, win1FZ, false);
    win1FMesh.rotation.y = Math.PI / 2;
    // 階梯前黑色橡膠防滑除塵地墊
    addBox(g, 0.95, 0.02, 0.65, new THREE.MeshStandardMaterial({ color: 0x181a1d, roughness: 0.92 }), xStairWest - 0.55, y1F_west + 0.01, stairZ, false);

    // 1.2 8 階磨石子踏步 (向西遞減 / 向東遞升)
    for (let st = 0; st < n1FSteps; st++) {
      const sx = xStairWest + (st + 0.5) * run1F;
      const sh = (st + 1) * rise1F;
      const sy = y1F_west + sh;
      addBox(g, run1F + 0.015, sh, stairClearDepth, terrazzoStepMat, sx, y1F_west + sh / 2, stairZ);
      // 黃銅/暗色止滑嵌條
      addBox(g, 0.04, 0.015, stairClearDepth - 0.08, brassNosingMat, sx - run1F / 2 + 0.02, sy + 0.008, stairZ, false);
    }

    // 1.3 新棟 1F 上層連通平台地坪 (+120 高程)
    addBox(g, topLandW + 0.10, 0.32, stairClearDepth + 0.40, terrazzoStepMat, xStairEast + topLandW / 2, y1F_new - 0.16, stairZ);

    // 1.4 不銹鋼包邊門框過梁與門額招牌 (位於 xStairWest = -24.31m)
    addBox(g, 0.22, 2.70, 0.26, stainlessMat, xStairWest, y1F_west + 1.35, stairZ - stairClearDepth / 2 - 0.13);
    addBox(g, 0.22, 2.70, 0.26, stainlessMat, xStairWest, y1F_west + 1.35, stairZ + stairClearDepth / 2 + 0.13);
    addBox(g, 0.24, 0.45, stairClearDepth + 0.52, stainlessMat, xStairWest, y1F_west + 2.70 + 0.225, stairZ);
    // 招牌面朝西棟 (-x 方向，供自西棟走廊往東看時辨識)
    const sign1FW = 2.05, sign1FH = 0.52;
    addBox(g, 0.04, sign1FH + 0.04, sign1FW + 0.04, stainlessMat, xStairWest - 0.02, y1F_west + 2.70 + 0.24, stairZ);
    const sign1FFace = addMesh(g, new THREE.PlaneGeometry(sign1FW, sign1FH), indoorSignMat, xStairWest - 0.045, y1F_west + 2.70 + 0.24, stairZ, false);
    sign1FFace.rotation.y = -Math.PI / 2;

    // 1.5 1F 階梯扶手與安全護欄 (南側原木+不銹鋼斜向扶手，上層防跌落白色柵欄)
    const rail1FZ = stairZ + stairClearDepth / 2 - 0.08;
    for (let st = 0; st <= n1FSteps; st++) {
      const rxX = xStairWest + st * run1F;
      const rxY = y1F_west + st * rise1F;
      addMesh(g, new THREE.CylinderGeometry(0.02, 0.02, 0.88, 8), stainlessMat, rxX, rxY + 0.44, rail1FZ, false);
    }
    const stair1FLen = Math.hypot(stairBayW, y1F_new - y1F_west);
    const stair1FAngle = Math.atan2(y1F_new - y1F_west, stairBayW);
    const rail1F = new THREE.Mesh(new THREE.BoxGeometry(stair1FLen + 0.2, 0.06, 0.07), woodHandrailMat);
    rail1F.position.set(xStairWest + stairBayW / 2, (y1F_west + y1F_new) / 2 + 0.88, rail1FZ);
    rail1F.rotation.z = stair1FAngle;
    g.add(rail1F);

    // 1F 上層高差安全白色金屬防墜柵欄 (隔絕走廊跌落)
    addBox(g, topLandW, 0.05, 0.05, whiteTileMat, xStairEast + topLandW / 2, y1F_new + 0.95, rail1FZ);
    addBox(g, topLandW, 0.05, 0.05, whiteTileMat, xStairEast + topLandW / 2, y1F_new + 0.10, rail1FZ);
    for (let k = 0; k < 6; k++) {
      addBox(g, 0.025, 0.85, 0.025, whiteTileMat, xStairEast + 0.15 + k * ((topLandW - 0.3) / 5), y1F_new + 0.525, rail1FZ, false);
    }

    // ========================================================================
    // B. 2F 與 3F 室內連通向下階梯 (新棟走廊 -> 西棟走廊，直通 11 階踏階)
    // ========================================================================
    const floorsConfig = [
      { fl: 2, yWest: 3.95, yNew: 5.85, drop: 1.90, soffitAbove: true },
      { fl: 3, yWest: 7.70, yNew: 9.40, drop: 1.70, soffitAbove: false }
    ];

    floorsConfig.forEach(cfg => {
      const { fl, yWest, yNew, drop, soffitAbove } = cfg;
      const stepH = drop / nStepsWest; // 2F: ~0.173m, 3F: ~0.155m
      const stepW = stairBayW / nStepsWest; // 0.28m

      // B.1 西棟端頭休息平台地坪 (+365 / +745)
      addBox(g, wLandingW + 0.10, 0.30, stairClearDepth + 0.40, terrazzoStepMat, wLandingCx, yWest - 0.15, stairZ);

      // 西端牆面：教室雙開門 (2F 貼有「健康體位妙招」海報；3F 為標準教室門)
      if (fl === 2) {
        const dMesh = addMesh(g, new THREE.PlaneGeometry(stairClearDepth - 0.10, 2.35), west2FDoorMat, xCoreEast + 0.08, yWest + 1.175, stairZ, false);
        dMesh.rotation.y = Math.PI / 2;
      } else {
        const dMesh = addMesh(g, new THREE.PlaneGeometry(stairClearDepth - 0.10, 2.35), new THREE.MeshStandardMaterial({ map: makeWestMultiPaneWindowTex(3, 2, '#2c3035', '#68839a', '#3d5366', true), side: THREE.DoubleSide }), xCoreEast + 0.08, yWest + 1.175, stairZ, false);
        dMesh.rotation.y = Math.PI / 2;
      }

      // 西棟門洞不銹鋼包邊門柱 (實拍畫面左右金屬框線)
      addBox(g, 0.18, 2.70, 0.24, stainlessMat, xStairWest, yWest + 1.35, stairZ - stairClearDepth / 2 - 0.12);
      addBox(g, 0.18, 2.70, 0.24, stainlessMat, xStairWest, yWest + 1.35, stairZ + stairClearDepth / 2 + 0.12);

      // B.2 11 階東西向磨石子直通階梯 (踏面平整，止滑條清晰，踏面朝向西棟)
      for (let st = 0; st < nStepsWest; st++) {
        const sx = xStairWest + (st + 0.5) * stepW;
        const sh = (st + 1) * stepH;
        const sy = yWest + sh;
        addBox(g, stepW + 0.012, sh, stairClearDepth, terrazzoStepMat, sx, yWest + sh / 2, stairZ);
        // 深色防滑條 (嵌入踏面靠近西緣邊角)
        addBox(g, 0.035, 0.015, stairClearDepth - 0.06, stairNosingMat, sx - stepW / 2 + 0.025, sy + 0.008, stairZ, false);
      }

      // B.3 新棟上層走廊連通平台地坪 (+560 / +920)
      addBox(g, topLandW + 0.10, 0.32, stairClearDepth + 0.40, terrazzoStepMat, xStairEast + topLandW / 2, yNew - 0.16, stairZ);

      // 頂層平台南側防跌落護欄 (2F 實拍照片上方醒目的原木扶手欄杆與蜜桃橘矮牆)
      const topRailZ = stairZ + stairClearDepth / 2 + 0.05;
      addBox(g, topLandW, 0.70, 0.18, new THREE.MeshStandardMaterial({ color: 0xd68565, roughness: 0.6 }), xStairEast + topLandW / 2, yNew + 0.35, topRailZ);
      addBox(g, topLandW + 0.04, 0.06, 0.22, woodHandrailMat, xStairEast + topLandW / 2, yNew + 0.73, topRailZ);
      for (let rp = 0; rp < 4; rp++) {
        addBox(g, 0.04, 0.38, 0.04, woodHandrailMat, xStairEast + 0.25 + rp * ((topLandW - 0.5) / 3), yNew + 0.92, topRailZ, false);
      }
      addBox(g, topLandW + 0.04, 0.05, 0.08, woodHandrailMat, xStairEast + topLandW / 2, yNew + 1.11, topRailZ);

      // B.4 階梯雙側斜向扶手 (原木頂軌 + 不銹鋼垂直立柱)
      const flightL = Math.hypot(stairBayW, drop);
      const flightPitch = Math.atan2(drop, stairBayW);

      // 南側扶手 (靠內壁)
      const sRailZ = stairZ + stairClearDepth / 2 - 0.06;
      for (let st = 0; st <= nStepsWest; st++) {
        const px = xStairWest + st * stepW;
        const py = yWest + st * stepH;
        addMesh(g, new THREE.CylinderGeometry(0.018, 0.018, 0.88, 8), stainlessMat, px, py + 0.44, sRailZ, false);
      }
      const sHandrail = new THREE.Mesh(new THREE.BoxGeometry(flightL + 0.25, 0.06, 0.07), woodHandrailMat);
      sHandrail.position.set(xStairWest + stairBayW / 2, (yWest + yNew) / 2 + 0.88, sRailZ);
      sHandrail.rotation.z = flightPitch;
      g.add(sHandrail);

      // 北側扶手 (靠中庭矮牆側)
      const nRailZ = stairZ - stairClearDepth / 2 + 0.06;
      for (let st = 0; st <= nStepsWest; st++) {
        const px = xStairWest + st * stepW;
        const py = yWest + st * stepH;
        addMesh(g, new THREE.CylinderGeometry(0.018, 0.018, 0.88, 8), stainlessMat, px, py + 0.44, nRailZ, false);
      }
      const nHandrail = new THREE.Mesh(new THREE.BoxGeometry(flightL + 0.25, 0.06, 0.07), woodHandrailMat);
      nHandrail.position.set(xStairWest + stairBayW / 2, (yWest + yNew) / 2 + 0.88, nRailZ);
      nHandrail.rotation.z = flightPitch;
      g.add(nHandrail);

      // B.5 頂部斜向結構底梁板 (Soffit) — 還原新棟2F俯瞰視角中醒目的 3F 階梯斜底板！
      if (soffitAbove) {
        const soffitAngle = Math.atan2(1.70, stairBayW);
        const soffitL = Math.hypot(stairBayW, 1.70);
        const soffitMesh = new THREE.Mesh(new THREE.BoxGeometry(soffitL + 0.3, 0.22, stairClearDepth + 0.1), creamWallMat);
        soffitMesh.position.set(xStairWest + stairBayW / 2, 7.70 + 1.70 / 2 - 0.11, stairZ);
        soffitMesh.rotation.z = soffitAngle;
        g.add(soffitMesh);
      }

      // 天花板吸頂吸頂投光燈
      addMesh(g, new THREE.CylinderGeometry(0.12, 0.12, 0.08, 12), whiteMetalMat, xStairWest + stairBayW / 2, yNew + 2.45, stairZ, false);
    });

    // ========================================================================
    // C. 外立面 (面向中庭 / 北側 z = zF = 13.398m) 依正面立圖精確還原斜向白色護牆與深灰清水過梁
    // ========================================================================
    const facadeZ = zF + 0.14;
    for (let f = 1; f <= 2; f++) {
      const fy = f * FH;
      const yWestBase = (f === 1 ? 3.95 : 7.70) + 0.45;
      const yEastBase = (f === 1 ? 5.85 : 9.40) + 0.45;

      // C.1 斜向白色二丁掛實體側板護牆 (沿著梯段斜升)
      const slopeShape = new THREE.Shape();
      slopeShape.moveTo(xStairWest, f * FH);
      slopeShape.lineTo(xTopLandEast, f * FH);
      slopeShape.lineTo(xTopLandEast, yEastBase);
      slopeShape.lineTo(xStairWest, yWestBase);
      slopeShape.closePath();

      const slopeGeom = new THREE.ExtrudeGeometry(slopeShape, { depth: 0.26, bevelEnabled: false });
      const slopeMesh = new THREE.Mesh(slopeGeom, whiteTileMat);
      slopeMesh.position.set(0, 0, zF);
      g.add(slopeMesh);

      // C.2 斜牆深灰水泥壓頂 (Dark Coping)
      const sDx = xTopLandEast - xStairWest;
      const sDy = yEastBase - yWestBase;
      const sLen = Math.hypot(sDx, sDy);
      const sPitch = Math.atan2(sDy, sDx);
      const copingMesh = new THREE.Mesh(new THREE.BoxGeometry(sLen + 0.08, 0.08, 0.32), darkCopingMat);
      copingMesh.position.set((xStairWest + xTopLandEast) / 2, (yWestBase + yEastBase) / 2 + 0.04, facadeZ);
      copingMesh.rotation.z = sPitch;
      g.add(copingMesh);

      // C.3 上方橫貫整跨之深灰清水混凝土防雨結構過梁
      addBox(g, xTopLandEast - xStairWest + 0.2, 0.52, 0.38, exposedConcreteBeamMat, (xStairWest + xTopLandEast) / 2, fy + FH - 0.26, facadeZ);

      // C.4 兩端結構支撐方柱 (Axis 4 與 Axis 6)
      addBox(g, 0.44, FH - 0.52, 0.44, whiteTileMat, xStairWest + 0.22, fy + (FH - 0.52) / 2, facadeZ);
      addBox(g, 0.44, FH - 0.52, 0.44, whiteTileMat, xTopLandEast - 0.22, fy + (FH - 0.52) / 2, facadeZ);
    }

    // ------------------------------------------------------------------------
    // 3.2 【紅框中段北側走廊】⑥–⑩ (ax(6)=-19.81 至 ax(10)=-6.72, zE=15.918 至 zD=19.053)
    // ------------------------------------------------------------------------
    const nCorX1 = ax(7), nCorX2 = ax(10);
    const nCorW = nCorX2 - nCorX1; // 13.09m
    const nCorCx = (nCorX1 + nCorX2) / 2;
    const nCorD = zD - zE;         // 3.135m
    const nCorCz = (zE + zD) / 2;

    for (let f = 0; f < 3; f++) {
      const fy = f * FH;
      // 走廊樓板結構 (Floor Slab)
      addBox(g, nCorW, 0.32, nCorD, mats.slab, nCorCx, fy + 0.16, nCorCz);
      // 白色磁磚欄杆女兒牆 (Parapet Wall along zE)
      addBox(g, nCorW, parapetH, 0.26, whiteTileMat, nCorCx, fy + parapetH / 2, zE + 0.13);
      addBox(g, nCorW + 0.08, 0.08, 0.34, darkCopingMat, nCorCx, fy + parapetH + 0.04, zE + 0.13);
      // 實景照片核心特徵：各樓層上方之【深灰清水混凝土結構過梁】(Exposed Concrete Beam)
      addBox(g, nCorW, 0.54, 0.34, exposedConcreteBeamMat, nCorCx, fy + FH - 0.27, zE + 0.16);
      // 走廊天花板照明燈管
      for (let k = 1; k <= 3; k++) {
        const lx = nCorX1 + k * (nCorW / 4);
        addBox(g, 1.20, 0.06, 0.14, whiteMetalMat, lx, fy + FH - 0.05, nCorCz, false);
      }
    }

    // 屋頂女兒牆與防水壓頂 (Roof Parapet along zE)
    addBox(g, nCorW, 0.30, nCorD, mats.roof, nCorCx, yRF + 0.15, nCorCz);
    addBox(g, nCorW, 0.90, 0.28, whiteTileMat, nCorCx, yRF + 0.45, zE + 0.14);
    addBox(g, nCorW + 0.08, 0.09, 0.36, darkCopingMat, nCorCx, yRF + 0.92, zE + 0.14);
    // 屋頂銀白金屬防雨滴水簷口邊條 (Silver Metal Roof Trim)
    addBox(g, nCorW + 0.16, 0.06, 0.44, roofMetalMat, nCorCx, yRF + 0.97, zE + 0.14);

    // 沿 zE 外廊的主結構方柱 (Structural Columns at Axes ⑥, ⑦, ⑧, ⑨, ⑩)
    [7, 8, 9, 10].forEach(idx => {
      addBox(g, 0.44, yRF + 0.90, 0.44, whiteTileMat, ax(idx), (yRF + 0.90) / 2, zE + 0.22);
      addBox(g, 0.48, 0.18, 0.48, darkCopingMat, ax(idx), 0.09, zE + 0.22, false);
    });

    // 【北立面視覺焦點：橘紅陶磚立體陽台盒】(Terracotta Brick Balcony Box on 2F & 3F)
    const nBoxCx = (ax(8) + ax(9)) / 2;
    const nBoxW = (ax(9) - ax(8)) - 0.24; // 約 4.33m
    addTerracottaBalconyBox(nBoxCx, y2F + parapetH / 2 + 0.08, zE - 0.18, nBoxW, parapetH + 0.18, 0.48, -1);
    addTerracottaBalconyBox(nBoxCx, y3F + parapetH / 2 + 0.08, zE - 0.18, nBoxW, parapetH + 0.18, 0.48, -1);

    // 白色 PVC 垂直雨水落水立管 (Vertical Rainwater Downspout at Axis ⑧)
    addMesh(g, new THREE.CylinderGeometry(0.06, 0.06, yRF + 0.70, 12), pvcPipeMat, ax(8) + 0.20, (yRF + 0.70) / 2, zE - 0.05, false);
    for (let f = 0; f <= 3; f++) {
      addBox(g, 0.16, 0.04, 0.16, darkCopingMat, ax(8) + 0.20, f * FH + 1.2, zE - 0.05, false);
    }

    // ------------------------------------------------------------------------
    // 3.3 【紅框前景精緻花園與 1F 無障礙緩坡道】
    // ------------------------------------------------------------------------
    const rampW = nCorW - 0.35;
    const rampD = zE - zF; // 2.52m
    const rampCx = nCorCx;
    const rampCz = (zF + zE) / 2;

    // 無障礙緩坡道實體基座 (斜坡走道 + 白色磁磚保護側牆)
    addBox(g, rampW, 0.65, rampD, mats.concrete, rampCx, 0.325, rampCz);
    addBox(g, rampW, 0.90, 0.26, whiteTileMat, rampCx, 0.45, zF + 0.13);
    addBox(g, rampW + 0.06, 0.08, 0.32, darkCopingMat, rampCx, 0.92, zF + 0.13);

    // 雙層鍍鋅鋼管無障礙防護欄杆 (Dual-Height Galvanized Safety Handrails, 高度 75cm / 90cm)
    addBox(g, rampW - 0.30, 0.045, 0.045, handrailMat, rampCx, 1.10, zF + 0.13, false);
    addBox(g, rampW - 0.30, 0.045, 0.045, handrailMat, rampCx, 0.95, zF + 0.13, false);
    const nPosts = 7;
    for (let p = 0; p <= nPosts; p++) {
      const px = (rampCx - rampW / 2 + 0.2) + p * ((rampW - 0.4) / nPosts);
      addMesh(g, new THREE.CylinderGeometry(0.025, 0.025, 0.30, 8), handrailMat, px, 0.97, zF + 0.13, false);
    }

    // 平面圖標註之「新設鍍鋅鋼欄杆及活動門」黃色烤漆活動柵門 (附插銷)
    const yGateW = 1.65, yGateH = 0.92;
    const yGateX = rampCx - rampW * 0.32, yGateZ = zF - 0.18;
    const ySteelMat = new THREE.MeshStandardMaterial({ color: 0xeab308, roughness: 0.38, metalness: 0.55 });
    addBox(g, yGateW, 0.05, 0.05, ySteelMat, yGateX, 1.05, yGateZ, false);
    addBox(g, yGateW, 0.05, 0.05, ySteelMat, yGateX, 0.35, yGateZ, false);
    for (let k = 0; k < 6; k++) {
      addBox(g, 0.035, 0.70, 0.035, ySteelMat, yGateX - yGateW/2 + 0.15 + k * (yGateW - 0.3)/5, 0.70, yGateZ, false);
    }

    // 【中庭前景立體綠化花園 (Courtyard Landscape Garden Island)】
    const lawnMat = new THREE.MeshStandardMaterial({ color: 0x487a32, roughness: 0.88 });
    const curbMat = new THREE.MeshStandardMaterial({ color: 0xb5afa4, roughness: 0.68 });
    const plumeriaTrunkMat = new THREE.MeshStandardMaterial({ color: 0x6e5843, roughness: 0.92 });
    const plumeriaLeafMat = new THREE.MeshStandardMaterial({ color: 0x367c3b, roughness: 0.72 });
    const flowerWhiteMat = new THREE.MeshStandardMaterial({ color: 0xfffaea, roughness: 0.45 });
    const juniperMat = new THREE.MeshStandardMaterial({ color: 0x1f4826, roughness: 0.84 });
    const hedgeMat1 = new THREE.MeshStandardMaterial({ color: 0x4a8c3d, roughness: 0.80 });
    const hedgeMat2 = new THREE.MeshStandardMaterial({ color: 0x275e2c, roughness: 0.82 });
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x767066, roughness: 0.88 });

    // 1. 起伏草坪土丘 (Lawn Mound) 與洗石子收邊緣石
    const lawnW = rampW + 1.20;
    const lawnCx = rampCx + 0.20;
    const lawnCz = zF - 1.55;
    const lawnD = 2.40;
    addBox(g, lawnW, 0.18, lawnD, lawnMat, lawnCx, 0.09, lawnCz);
    addBox(g, lawnW + 0.20, 0.14, 0.22, curbMat, lawnCx, 0.07, lawnCz - lawnD / 2, false);
    addBox(g, 0.22, 0.14, lawnD, curbMat, lawnCx - lawnW / 2, 0.07, lawnCz, false);
    addBox(g, 0.22, 0.14, lawnD, curbMat, lawnCx + lawnW / 2, 0.07, lawnCz, false);

    // 2. 【雕塑感雞蛋花樹 (Plumeria Tree)】(位於 ax(7) 前方中庭草坪)
    const pX = ax(7) + 0.35, pZ = zF - 1.45;
    const trunk1 = addMesh(g, new THREE.CylinderGeometry(0.16, 0.22, 1.8, 10), plumeriaTrunkMat, pX, 0.9, pZ);
    trunk1.rotation.z = -0.12;
    const branch1 = addMesh(g, new THREE.CylinderGeometry(0.11, 0.15, 1.6, 8), plumeriaTrunkMat, pX - 0.35, 2.1, pZ - 0.15);
    branch1.rotation.z = 0.38;
    branch1.rotation.x = -0.15;
    const branch2 = addMesh(g, new THREE.CylinderGeometry(0.10, 0.14, 1.7, 8), plumeriaTrunkMat, pX + 0.42, 2.2, pZ + 0.12);
    branch2.rotation.z = -0.42;
    branch2.rotation.y = 0.25;
    const branch3 = addMesh(g, new THREE.CylinderGeometry(0.09, 0.13, 1.5, 8), plumeriaTrunkMat, pX + 0.05, 2.3, pZ - 0.35);
    branch3.rotation.x = -0.45;

    const foliageClusters = [
      { x: pX - 0.65, y: 2.85, z: pZ - 0.25, r: 1.15, s: [1.2, 0.75, 1.1] },
      { x: pX + 0.75, y: 2.95, z: pZ + 0.15, r: 1.25, s: [1.3, 0.78, 1.2] },
      { x: pX + 0.10, y: 3.15, z: pZ - 0.50, r: 1.05, s: [1.15, 0.7, 1.05] },
      { x: pX + 0.15, y: 3.45, z: pZ - 0.05, r: 1.35, s: [1.35, 0.82, 1.3] },
      { x: pX - 0.20, y: 2.65, z: pZ + 0.35, r: 0.95, s: [1.1, 0.68, 1.0] }
    ];
    foliageClusters.forEach(c => {
      const sp = addMesh(g, new THREE.SphereGeometry(c.r, 12, 10), plumeriaLeafMat, c.x, c.y, c.z);
      sp.scale.set(c.s[0], c.s[1], c.s[2]);
    });

    const flowerOffsets = [
      [-0.75, 2.70, -0.3], [0.85, 2.80, 0.2], [0.25, 3.55, 0.1],
      [-0.10, 3.25, -0.6], [0.45, 3.10, -0.4], [-0.40, 2.85, 0.3]
    ];
    flowerOffsets.forEach(fo => {
      addMesh(g, new THREE.SphereGeometry(0.12, 8, 6), flowerWhiteMat, pX + fo[0], fo[1], pZ + fo[2], false);
    });

    // 3. 【挺拔圓錐龍柏 (Conical Juniper)】(位於雞蛋花樹右側，ax(8)+1.3)
    const junX = ax(8) + 1.25, junZ = zF - 1.40;
    addMesh(g, new THREE.ConeGeometry(0.85, 1.6, 12), juniperMat, junX, 1.0, junZ);
    addMesh(g, new THREE.ConeGeometry(0.70, 1.5, 12), juniperMat, junX, 1.9, junZ);
    addMesh(g, new THREE.ConeGeometry(0.50, 1.4, 12), juniperMat, junX, 2.7, junZ);
    addMesh(g, new THREE.ConeGeometry(0.28, 0.9, 10), juniperMat, junX, 3.4, junZ);
    addBox(g, 0.20, 0.40, 0.20, plumeriaTrunkMat, junX, 0.20, junZ, false);

    // 4. 【複層修剪常綠綠籬帶 (Layered Manicured Shrub Hedges)】
    addBox(g, lawnW * 0.78, 0.52, 0.58, hedgeMat2, lawnCx + 0.4, 0.26, zF - 0.70);
    for (let b = 0; b < 6; b++) {
      const bx = (lawnCx - lawnW * 0.35) + b * 1.5;
      const bz = zF - 2.25 + (b % 2) * 0.25;
      const shp = addMesh(g, new THREE.SphereGeometry(0.38, 10, 8), hedgeMat1, bx, 0.35, bz, false);
      shp.scale.set(1.1, 0.85, 1.0);
    }

    // 5. 【天然景觀造景花崗岩巨石 (Natural Granite Landscaping Boulders)】
    const boulderCoords = [
      { x: pX - 1.4, y: 0.28, z: zF - 1.8, sx: 0.75, sy: 0.55, sz: 0.65, rot: 0.4 },
      { x: junX + 0.9, y: 0.24, z: zF - 1.6, sx: 0.65, sy: 0.48, sz: 0.55, rot: -0.3 },
      { x: lawnCx - 0.8, y: 0.20, z: zF - 2.3, sx: 0.52, sy: 0.38, sz: 0.45, rot: 0.8 }
    ];
    boulderCoords.forEach(b => {
      const bMesh = addMesh(g, new THREE.DodecahedronGeometry(0.48, 1), rockMat, b.x, b.y, b.z, false);
      bMesh.scale.set(b.sx, b.sy, b.sz);
      bMesh.rotation.set(b.rot * 0.5, b.rot, b.rot * 0.2);
    });

    // 6. 【西棟交接轉角石板步道與花台綠植】（依實景照片 Image 3 中庭轉角實景極致還原）
    // (A) 自中庭幾何連鎖磚廣場一路優美蜿蜒至幼兒園 1F 入口階梯之天然板岩踏石步道
    const stonePaverMat = new THREE.MeshStandardMaterial({ color: 0x88847b, roughness: 0.85 });
    const steppingPath = [
      [-21.4, 8.05],
      [-21.2, 8.65],
      [-21.0, 9.25],
      [-20.8, 9.85],
      [-20.6, 10.45],
      [-20.4, 11.05],
      [-20.1, 11.65],
      [-19.8, 12.20],
      [-19.6, 12.75]
    ];
    steppingPath.forEach(([px, pz], sIdx) => {
      const paver = addMesh(g, new THREE.BoxGeometry(0.56, 0.05, 0.44), stonePaverMat, px, 0.09, pz, false);
      paver.rotation.y = (sIdx % 2 === 0 ? 0.12 : -0.10) + sIdx * 0.03;
    });

    // (B) 步道旁與西棟東走廊轉角草坪間散落之【天然景觀石群】(Natural Landscape Boulders per Image 3)
    const junctionBoulders = [
      { x: -23.1, z: 11.2, sx: 0.68, sy: 0.45, sz: 0.58, rot: 0.4 },
      { x: -22.4, z: 11.6, sx: 0.55, sy: 0.38, sz: 0.48, rot: -0.6 },
      { x: -23.4, z: 14.2, sx: 0.48, sy: 0.32, sz: 0.42, rot: 0.8 }
    ];
    junctionBoulders.forEach(jb => {
      const bMesh = addMesh(g, new THREE.DodecahedronGeometry(0.45, 1), rockMat, jb.x, 0.18, jb.z, false);
      bMesh.scale.set(jb.sx, jb.sy, jb.sz);
      bMesh.rotation.set(jb.rot * 0.4, jb.rot, jb.rot * 0.2);
    });

    // (C) 轉角草坪修剪常綠小圓球灌木 (Pruned Spherical Shrubs per Image 3)
    [
      [-23.6, 10.4], [-23.4, 12.4], [-21.8, 8.8], [-18.8, 11.8], [-22.8, 14.8]
    ].forEach(([bx, bz], i) => {
      const shp = addMesh(g, new THREE.SphereGeometry(0.32 + (i % 2) * 0.06, 10, 8), hedgeMat1, bx, 0.28, bz, false);
      shp.scale.set(1.1, 0.88, 1.05);
    });

    // (D) 連鎖磚廣場與草坪之【弧形洗石子收邊緣石】(Curved Wash-Stone Plaza Curb per Image 3 前景)
    const juncCurbMat = new THREE.MeshStandardMaterial({ color: 0xbdb8ac, roughness: 0.72 });
    for (let c = 0; c <= 8; c++) {
      const cx = -24.31 + c * ((-19.5 - (-24.31)) / 8);
      const cz = 7.95 + Math.sin(c / 8 * Math.PI) * 0.25;
      addBox(g, 0.65, 0.12, 0.18, juncCurbMat, cx, 0.06, cz, false);
    }

    // ------------------------------------------------------------------------
    // 3.4 【共用走廊連接棟】⑩–⑪ (ax(10)=-6.72 至 ax(11)=-4.22, 面寬 2.50m)
    //     依據 20261106_142631.jpg、142638.jpg 與 新棟1F建築平面圖002.jpg 1:1 校準：
    //     - 貫通 zG=8.78m (北端階梯口) 至 zC=20.28m (南端銜接走廊通道口)
    //     - 南端 (zC=20.28m) 2F、3F、RF 具深灰清水混凝土結構橫梁 + 白色二丁掛磁磚女兒牆
    //     - 1F 走廊天花板設長條日光燈具、西側懸掛兩盞喜慶大紅燈籠，南北兩端皆設踏步階梯
    // ------------------------------------------------------------------------
    const shX1 = ax(10), shX2 = ax(11);
    const shW = shX2 - shX1; // 2.50m
    const shCx = (shX1 + shX2) / 2;
    const shD = zC - zG;     // 11.50m (自 zG=8.78m 貫通至南棟外牆線 zC=20.28m)
    const shCz = (zG + zC) / 2;
    const northExtD = zE - zG;   // 向北突出走廊部分 (zG 至 zE，長度 7.138m)
    const northExtCz = (zG + zE) / 2;
    const lightTubeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfff8e7, emissiveIntensity: 0.65, roughness: 0.2 });
    const lanternRedMat = new THREE.MeshStandardMaterial({ color: 0xd91e18, emissive: 0x550804, emissiveIntensity: 0.35, roughness: 0.45 });
    const lanternGoldMat = new THREE.MeshStandardMaterial({ color: 0xf2c029, metalness: 0.65, roughness: 0.3 });

    for (let f = 0; f < 3; f++) {
      const fy = f * FH;
      // 走廊全跨度結構樓板
      addBox(g, shW, 0.32, shD, mats.slab, shCx, fy + 0.16, shCz);

      // 西向白色二丁掛磁磚走廊欄杆 (West Parapet, facing courtyard)
      addBox(g, 0.28, parapetH, northExtD, whiteTileMat, shX1 + 0.14, fy + parapetH / 2, northExtCz);
      addBox(g, 0.34, 0.08, northExtD, darkCopingMat, shX1 + 0.14, fy + parapetH + 0.04, northExtCz);
      // 北向端頭欄杆 (North End Parapet across zG)
      addBox(g, shW, parapetH, 0.28, whiteTileMat, shCx, fy + parapetH / 2, zG + 0.14);
      addBox(g, shW + 0.08, 0.08, 0.34, darkCopingMat, shCx, fy + parapetH + 0.04, zG + 0.14);

      // 南向端頭女兒牆 (South End Parapet across zC=20.28m: 2F 與 3F 實體清水混凝土深梁 + 白色二丁掛磁磚女兒牆 + 洗石子壓頂，1F 為挑空通道入口，100% 依 20261106_142638.jpg)
      if (f > 0) {
        // 樓板處外露清水混凝土結構深梁
        addBox(g, shW, 0.54, 0.32, exposedConcreteBeamMat, shCx, fy + 0.16, zC - 0.16);
        // 上方白色二丁掛磁磚女兒牆 (高度約 0.88m)
        addBox(g, shW, 0.88, 0.28, whiteTileMat, shCx, fy + 0.44 + 0.44, zC - 0.14);
        // 頂部洗石子/深色平整壓頂 (無多餘金屬扶手，完美對齊實景照片)
        addBox(g, shW + 0.08, 0.08, 0.34, darkCopingMat, shCx, fy + 1.36, zC - 0.14);
      }

      // 上方標誌性清水混凝土結構深梁 (Spandrel Exposed Concrete Beams: 西向、北向 zG、南向 zC 頂部梁)
      addBox(g, 0.30, 0.54, northExtD, exposedConcreteBeamMat, shX1 + 0.15, fy + FH - 0.27, northExtCz);
      addBox(g, shW, 0.54, 0.32, exposedConcreteBeamMat, shCx, fy + FH - 0.27, zG + 0.16);
      addBox(g, shW, 0.56, 0.34, exposedConcreteBeamMat, shCx, fy + FH - 0.28, zC - 0.17);

      // 西向走廊欄杆頂部不銹鋼安全加高扶手 (面向中庭部分)
      addBox(g, 0.04, 0.04, northExtD, handrailMat, shX1 + 0.14, fy + parapetH + 0.14, northExtCz, false);
      addBox(g, shW - 0.1, 0.04, 0.04, handrailMat, shCx, fy + parapetH + 0.14, zG + 0.14, false);

      // 走廊天花板長條日光燈具 (Ceiling Fluorescent Light Fixtures, 20261106_142631.jpg & 142638.jpg)
      for (const lz of [11.2, 14.8, 18.2]) {
        addBox(g, 0.22, 0.05, 1.25, whiteMetalMat, shCx, fy + FH - 0.03, lz, false);
        addBox(g, 0.14, 0.04, 1.18, lightTubeMat, shCx, fy + FH - 0.06, lz, false);
      }

      // 走廊內部連通踏步階梯 (Level-change steps per 1F CAD plan)
      for (let st = 0; st < 3; st++) {
        addBox(g, shW - 0.30, 0.11 * (st + 1), 0.32, mats.concrete, shCx, fy + 0.055 * (st + 1), zD - 0.8 + st * 0.32);
      }
    }

    // 1F 南端通道口進入共用走廊之 4 階磨石子踏步 (South Entrance Steps at zC=20.28m per 新棟1F建築平面圖002.jpg & 142631.jpg)
    for (let s = 0; s < 4; s++) {
      const stepH = 0.08 * (4 - s);
      const stepZ = zC - 0.18 + s * 0.30;
      addBox(g, shW - 0.36, stepH, 0.30, mats.concrete, shCx, stepH / 2, stepZ, false);
    }

    // 1F 共用走廊內懸掛之兩盞喜慶大紅燈籠 (Festive Red Chinese Lanterns, 20261106_142631.jpg & 142638.jpg)
    for (const lz of [18.55, 15.65]) {
      const lx = shX1 + 0.52, ly = 2.82;
      addMesh(g, new THREE.CylinderGeometry(0.012, 0.012, 0.55, 6), lanternGoldMat, lx, 3.30, lz, false); // 吊線
      addMesh(g, new THREE.CylinderGeometry(0.10, 0.12, 0.05, 12), lanternGoldMat, lx, ly + 0.21, lz, false); // 上金蓋
      const lBody = addMesh(g, new THREE.SphereGeometry(0.24, 14, 12), lanternRedMat, lx, ly, lz, false);
      lBody.scale.set(1.0, 0.88, 1.0);
      addMesh(g, new THREE.CylinderGeometry(0.11, 0.09, 0.05, 12), lanternGoldMat, lx, ly - 0.21, lz, false); // 下金座
      addMesh(g, new THREE.CylinderGeometry(0.025, 0.04, 0.26, 8), lanternRedMat, lx, ly - 0.36, lz, false);   // 紅流蘇
    }

    // 1F 西向欄杆矮牆上的紅陶盆栽與垂墜綠植 (Potted Terracotta Plants on Parapet)
    const potMat = new THREE.MeshStandardMaterial({ color: 0xba5838, roughness: 0.76 });
    for (let p = 0; p < 6; p++) {
      const pz = zG + 0.8 + p * 1.15;
      addMesh(g, new THREE.CylinderGeometry(0.18, 0.13, 0.24, 10), potMat, shX1 + 0.14, parapetH + 0.16, pz, false);
      const potFoliage = addMesh(g, new THREE.SphereGeometry(0.24, 8, 8), hedgeMat1, shX1 + 0.14, parapetH + 0.38, pz, false);
      potFoliage.scale.set(1.1, 0.9, 1.1);
      addMesh(g, new THREE.SphereGeometry(0.06, 6, 6), flowerWhiteMat, shX1 + 0.08, parapetH + 0.48, pz, false);
    }

    // 1F 北側銜接中庭花磚之 4 階踏步階梯與引導斜面 (North Entrance Steps at zG=8.78m per 新棟1F建築平面圖002.jpg)
    for (let s = 0; s < 4; s++) {
      addBox(g, 0.34 * (4 - s), 0.14 * (s + 1), 2.10, mats.concrete, shX1 - 0.17 * (4 - s), 0.07 * (s + 1), zG + 1.8);
    }

    // 平屋頂結構板與南北兩端高低造型女兒牆 (含南向 zC=20.28m 頂層女兒牆與清水混凝土橫梁)
    addBox(g, shW, 0.30, shD, mats.roof, shCx, yRF + 0.15, shCz);
    addBox(g, 0.28, 0.88, zE - zG, whiteTileMat, shX1 + 0.14, yRF + 0.44, (zG + zE) / 2);
    addBox(g, shW, 0.88, 0.28, whiteTileMat, shCx, yRF + 0.44, zG + 0.14);
    addBox(g, shW, 0.88, 0.28, whiteTileMat, shCx, yRF + 0.44, zC - 0.14);
    addBox(g, 0.34, 0.08, zE - zG, darkCopingMat, shX1 + 0.14, yRF + 0.92, (zG + zE) / 2);
    addBox(g, shW + 0.06, 0.08, 0.34, darkCopingMat, shCx, yRF + 0.92, zG + 0.14);
    addBox(g, shW + 0.06, 0.08, 0.34, darkCopingMat, shCx, yRF + 0.92, zC - 0.14);

    // 結構方柱與西側實體白磁磚牆面 (Structural White-Tiled Columns & West Wall along ax(10) zE~zC, matching corridor_zoom.jpg)
    addBox(g, 0.44, yRF + 0.88, 0.44, whiteTileMat, shX1 + 0.22, (yRF + 0.88) / 2, zG + 0.22);
    addBox(g, 0.44, yRF + 0.88, 0.44, whiteTileMat, shX1 + 0.22, (yRF + 0.88) / 2, (zG + zE) / 2);
    addBox(g, 0.44, yRF + 0.88, 0.44, whiteTileMat, shX1 + 0.22, (yRF + 0.88) / 2, zE);
    addBox(g, 0.44, yRF + 0.88, 0.44, whiteTileMat, shX1 + 0.22, (yRF + 0.88) / 2, zC - 0.22);
    addBox(g, 0.46, yRF + 0.88, 0.46, whiteTileMat, shX2 - 0.23, (yRF + 0.88) / 2, zC - 0.23);
    // 走廊西側 (ax(10) zE 至 zC) 全高三層二丁掛白色磁磚實體側牆 (封閉衛生間/廚房側牆，使通道內部視野乾淨整潔)
    addBox(g, 0.28, yRF + 0.88, zC - zE, whiteTileMat, shX1 + 0.14, (yRF + 0.88) / 2, (zE + zC) / 2);

    // 屋頂轉角金屬立柱全校廣播高音號角喇叭 (Broadcast Horn Speakers on Roof Corner)
    addBox(g, 0.10, 1.45, 0.10, whiteMetalMat, shX1 + 0.22, yRF + 1.55, zG + 0.26, false);
    const horn1 = addMesh(g, new THREE.ConeGeometry(0.24, 0.42, 12), whiteMetalMat, shX1 + 0.06, yRF + 2.10, zG + 0.18, false);
    horn1.rotation.x = -Math.PI / 2.3;
    horn1.rotation.y = -Math.PI / 6;
    const horn2 = addMesh(g, new THREE.ConeGeometry(0.24, 0.42, 12), whiteMetalMat, shX1 + 0.24, yRF + 2.10, zG + 0.06, false);
    horn2.rotation.x = -Math.PI / 2.3;
    horn2.rotation.y = Math.PI / 4;

    // ========================================================================
    // 【實景黃框靈魂主景：高聳繁茂校園遮蔭大樹】(Tall Mature Courtyard Shade Tree)
    // 依據照片黃框標註：位於黃框轉折走廊西北前庭，主幹挺拔高聳，多層次繁茂綠葉枝葉扶疏，
    // 高度延伸貫穿 1F、2F 直抵 3F 女兒牆頂 (高度約 11.2 米)，完美還原照片現場空間縱深與自然意境！
    // ========================================================================
    const treeX = shX1 - 1.25;
    const treeZ = zG - 1.65;
    const treeTrunkMat = new THREE.MeshStandardMaterial({ color: 0x4d3f32, roughness: 0.92 }); // 深褐粗糙樹皮
    const treeLeafMat1 = new THREE.MeshStandardMaterial({ color: 0x2e6328, roughness: 0.80 }); // 濃綠樹冠
    const treeLeafMat2 = new THREE.MeshStandardMaterial({ color: 0x3d7b32, roughness: 0.76 }); // 亮綠向陽樹葉
    const treeLeafMat3 = new THREE.MeshStandardMaterial({ color: 0x20481d, roughness: 0.85 }); // 深綠底層陰影葉簇

    // 主樹幹 (下粗上細，高達 4.8m)
    const tMain = addMesh(g, new THREE.CylinderGeometry(0.24, 0.38, 4.8, 12), treeTrunkMat, treeX, 2.4, treeZ);
    tMain.rotation.z = -0.06;
    tMain.rotation.x = 0.04;

    // 四大向外延伸木質分枝 (Major Structural Limbs reaching up to 8.5m)
    const tB1 = addMesh(g, new THREE.CylinderGeometry(0.16, 0.22, 3.8, 8), treeTrunkMat, treeX - 0.45, 5.8, treeZ - 0.35);
    tB1.rotation.z = 0.28; tB1.rotation.x = -0.18;
    const tB2 = addMesh(g, new THREE.CylinderGeometry(0.15, 0.20, 4.2, 8), treeTrunkMat, treeX + 0.55, 6.0, treeZ + 0.25);
    tB2.rotation.z = -0.26; tB2.rotation.y = 0.22;
    const tB3 = addMesh(g, new THREE.CylinderGeometry(0.14, 0.18, 3.6, 8), treeTrunkMat, treeX + 0.15, 6.2, treeZ - 0.65);
    tB3.rotation.x = -0.32;
    const tB4 = addMesh(g, new THREE.CylinderGeometry(0.13, 0.17, 3.5, 8), treeTrunkMat, treeX - 0.30, 6.5, treeZ + 0.45);
    tB4.rotation.z = 0.22; tB4.rotation.x = 0.25;

    // 茂盛綠色樹冠球團 (Dense Multilayered Canopy Foliage Spheres, 覆蓋高度 4.5m ~ 11.2m)
    const canopySpheres = [
      // 3F 頂層向陽冠頂 (Y = 8.5 ~ 11.2m)
      { x: treeX + 0.10, y: 10.4, z: treeZ - 0.20, rx: 2.2, ry: 1.6, rz: 2.1, mat: treeLeafMat2 },
      { x: treeX - 0.85, y: 9.6,  z: treeZ - 0.55, rx: 1.9, ry: 1.5, rz: 1.8, mat: treeLeafMat1 },
      { x: treeX + 0.95, y: 9.8,  z: treeZ + 0.35, rx: 2.0, ry: 1.5, rz: 1.9, mat: treeLeafMat2 },
      { x: treeX + 0.20, y: 9.2,  z: treeZ - 0.90, rx: 1.8, ry: 1.4, rz: 1.7, mat: treeLeafMat1 },
      // 2F 中層豐滿側冠 (Y = 6.0 ~ 8.5m)
      { x: treeX - 1.20, y: 7.8,  z: treeZ - 0.30, rx: 2.1, ry: 1.7, rz: 2.0, mat: treeLeafMat1 },
      { x: treeX + 1.25, y: 8.0,  z: treeZ + 0.20, rx: 2.2, ry: 1.8, rz: 2.1, mat: treeLeafMat2 },
      { x: treeX - 0.35, y: 7.5,  z: treeZ - 1.20, rx: 1.9, ry: 1.6, rz: 1.8, mat: treeLeafMat3 },
      { x: treeX + 0.45, y: 7.6,  z: treeZ + 0.95, rx: 2.0, ry: 1.6, rz: 1.9, mat: treeLeafMat1 },
      { x: treeX + 0.05, y: 8.2,  z: treeZ + 0.10, rx: 2.4, ry: 1.9, rz: 2.3, mat: treeLeafMat1 },
      // 1F 下層底垂葉簇 (Y = 4.2 ~ 6.0m)
      { x: treeX - 0.90, y: 5.6,  z: treeZ - 0.20, rx: 1.6, ry: 1.3, rz: 1.5, mat: treeLeafMat3 },
      { x: treeX + 0.85, y: 5.8,  z: treeZ + 0.30, rx: 1.7, ry: 1.4, rz: 1.6, mat: treeLeafMat3 },
      { x: treeX - 0.15, y: 5.2,  z: treeZ - 0.70, rx: 1.5, ry: 1.2, rz: 1.4, mat: treeLeafMat3 }
    ];

    canopySpheres.forEach(cs => {
      const sp = addMesh(g, new THREE.SphereGeometry(1.0, 12, 10), cs.mat, cs.x, cs.y, cs.z);
      sp.scale.set(cs.rx, cs.ry, cs.rz);
    });

    // 樹穴花台基底與修剪低矮綠籬帶 (Tree Pit Planting Bed & Manicured Hedges along base)
    addBox(g, 2.6, 0.16, 2.6, curbMat, treeX, 0.08, treeZ, false);
    addBox(g, 2.3, 0.18, 2.3, lawnMat, treeX, 0.09, treeZ, false);
    // 黃框走廊前緣常綠綠籬
    addBox(g, 0.65, 0.62, northExtD * 0.85, hedgeMat2, shX1 - 0.55, 0.31, northExtCz, false);
  }
  // ==========================================================================
  // 4. SOUTH FACADE & SOUTHEAST 45° FACADE
  //    (Matching `新棟正面立圖_南向.jpg` & `新棟南向正面_右手邊45度側面001.jpg`)
  // ==========================================================================
  {
    const sCorD = zA - zB; // 2.55m South Corridor / Balcony depth (`①–⑧`)
    const sCorCz = (zB + zA) / 2;

    // ========================================================================
    // --- 4.1 `①–②` 西側樓梯間與操場跑道側立面（ax(1)=-37.83 至 ax(2)=-33.31，寬 4.52m）---
    // （依據 2024 現場最新實拍照片 Image 1 & Image 2 極致 1:1 還原）
    // 特徵：1F 操場側白色二丁掛磁磚低矮擋土護欄牆、高架露台、外露清水混凝土斜向露天樓梯、
    // 樓梯下幼兒園全彩兒童作品成果展覽板、跑道上著藍色運動服學生、2F 內縮走廊綠色遮陽捲簾、
    // 3F 灰色水平飾帶排窗、女兒牆壓頂；轉角處高聳茂密大樹；南向 1F 門額與 2F/3F 水泥空心花磚牆
    // ========================================================================
    const wStX1 = ax(1), wStX2 = ax(2);
    const wStW = wStX2 - wStX1; // 4.52m
    const wStCx = (wStX1 + wStX2) / 2;
    const westD = zA - zE; // 10.785m (自 zE=15.918 至 zA=26.703)
    const westCz = (zE + zA) / 2;

    // ------------------------------------------------------------------------
    // (A) 1F 操場側高架露台平台與白色磁磚低矮擋土護欄牆（Image 1 實拍前景）
    // ------------------------------------------------------------------------
    const terraceH = 0.75;
    const terraceD = zB - zE; // 8.235m
    const terraceCz = (zE + zB) / 2;
    // 高架露台結構樓板（磨石子/水泥地坪）
    addBox(g, wStW, terraceH, terraceD, mats.concrete, wStCx, terraceH / 2, terraceCz);

    // 操場跑道側白色二丁掛磁磚矮護欄牆（位於 wStX1，兩名小學生站立其前，Image 1 實拍）
    const lowWallH = 0.95;
    addBox(g, 0.28, lowWallH, westD, whiteTileMat, wStX1 + 0.14, lowWallH / 2, westCz);
    addBox(g, 0.34, 0.08, westD, darkCopingMat, wStX1 + 0.14, lowWallH + 0.04, westCz);

    // ------------------------------------------------------------------------
    // (B) 跑道上兩名身穿天藍色校服之學童人物雕塑（依 Image 1 現場實景點綴校園活力）
    // ------------------------------------------------------------------------
    const peBlueMat   = new THREE.MeshStandardMaterial({ color: 0x246cb5, roughness: 0.65 });
    const peNavyMat   = new THREE.MeshStandardMaterial({ color: 0x182c44, roughness: 0.72 });
    const skinMat     = new THREE.MeshStandardMaterial({ color: 0xf5ceb0, roughness: 0.55 });
    const hairDarkMat = new THREE.MeshStandardMaterial({ color: 0x1e1d1b, roughness: 0.9 });
    const shoeWhiteMat= new THREE.MeshStandardMaterial({ color: 0xeeeeee, roughness: 0.4 });

    const studentCoords = [
      { x: wStX1 - 0.42, z: 17.2, h: 1.35 },
      { x: wStX1 - 0.42, z: 19.5, h: 1.30 }
    ];
    studentCoords.forEach(st => {
      const cy = st.h;
      // 雙腳（球鞋 + 深藍運動短褲）
      for (const sx of [-0.08, 0.08]) {
        addBox(g, 0.09, 0.08, 0.16, shoeWhiteMat, st.x, 0.04, st.z + sx, false);
        addBox(g, 0.07, 0.18, 0.07, skinMat, st.x, 0.17, st.z + sx, false);
        addBox(g, 0.09, 0.28, 0.09, peNavyMat, st.x, 0.40, st.z + sx, false);
      }
      // 身體（天藍色短袖校服運動上衣）
      addBox(g, 0.26, 0.44, 0.20, peBlueMat, st.x, 0.74, st.z, false);
      // 手臂
      for (const sgn of [-1, 1]) {
        addBox(g, 0.06, 0.36, 0.06, peBlueMat, st.x, 0.76, st.z + sgn * 0.14, false);
        addBox(g, 0.05, 0.12, 0.05, skinMat, st.x, 0.54, st.z + sgn * 0.14, false);
      }
      // 頭部與黑髮
      addMesh(g, new THREE.SphereGeometry(0.11, 10, 8), skinMat, st.x, 1.06, st.z, false);
      addMesh(g, new THREE.SphereGeometry(0.115, 10, 8), hairDarkMat, st.x, 1.10, st.z, false);
    });

    // ------------------------------------------------------------------------
    // (C) 【西側半戶外露天結構樓梯】（Dog-Leg Exterior Concrete Staircase, Image 1）
    // 依實景照片：斜向清水混凝土梯梁自 1F 露台向南（+z）直線上升至 2F 走廊，斜梁梯底板清晰可見
    // ------------------------------------------------------------------------
    const extStairW = 1.65;
    const extStairCx = wStCx;
    const extStairZ1 = 16.30;
    const extStairZ2 = 21.80;
    const extStairRun = extStairZ2 - extStairZ1; // 5.50m
    const extStairRise = y2F - terraceH;         // 2.85m (自 0.75m 升至 3.60m)
    const extStairLen = Math.hypot(extStairRun, extStairRise);
    const extStairPitch = Math.atan2(extStairRise, extStairRun);

    // 外露斜向清水混凝土梯梁底板 (Diagonal Soffit Beam)
    const stairBeam = new THREE.Mesh(new THREE.BoxGeometry(extStairW, 0.28, extStairLen), exposedConcreteBeamMat);
    stairBeam.position.set(extStairCx, terraceH + extStairRise / 2 - 0.14, (extStairZ1 + extStairZ2) / 2);
    stairBeam.rotation.x = extStairPitch;
    g.add(stairBeam);

    // 露天梯踏步（18 階磨石子防滑台階）
    const nExtSteps = 18;
    for (let st = 0; st < nExtSteps; st++) {
      const sy = terraceH + (st + 1) * (extStairRise / nExtSteps);
      const sz = extStairZ1 + (st + 0.5) * (extStairRun / nExtSteps);
      addBox(g, extStairW - 0.10, extStairRise / nExtSteps, extStairRun / nExtSteps, mats.concrete, extStairCx, sy - (extStairRise / nExtSteps) / 2, sz, false);
    }

    // 樓梯外側白色磁磚護牆與不銹鋼安全扶手（沿斜率順勢上升）
    const outerRailX = extStairCx - extStairW / 2 + 0.08;
    const stairRailMesh = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.85, extStairLen + 0.4), whiteTileMat);
    stairRailMesh.position.set(outerRailX, terraceH + extStairRise / 2 + 0.35, (extStairZ1 + extStairZ2) / 2);
    stairRailMesh.rotation.x = extStairPitch;
    g.add(stairRailMesh);
    const stairHandrail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, extStairLen + 0.4), handrailMat);
    stairHandrail.position.set(outerRailX, terraceH + extStairRise / 2 + 0.80, (extStairZ1 + extStairZ2) / 2);
    stairHandrail.rotation.x = extStairPitch;
    g.add(stairHandrail);

    // ------------------------------------------------------------------------
    // (D) 樓梯下方 1F 室內牆體與【幼兒園兒童繪畫作品全彩展覽板】（Image 1 實拍）
    // ------------------------------------------------------------------------
    const innerWallX = wStX2 - 0.20;
    addBox(g, 0.36, yRF, westD, whiteTileMat, innerWallX, yRF / 2, westCz);

    // 1F 兒童作品成果展覽板（長 3.4m × 高 1.6m）與深木色外框
    const artWallMat = new THREE.MeshBasicMaterial({ map: makeKindergartenArtWallTexture() });
    const artFrameMat = new THREE.MeshStandardMaterial({ color: 0x4c3e32, roughness: 0.72 });
    const artRailMat  = new THREE.MeshStandardMaterial({ color: 0x8a5836, roughness: 0.55 });
    const artMetalMat = new THREE.MeshStandardMaterial({ color: 0x42464c, roughness: 0.4, metalness: 0.6 });

    // 展覽板底襯板與深色邊框
    addBox(g, 0.04, 1.75, 3.50, artFrameMat, innerWallX - 0.17, terraceH + 1.25, 18.80, false);
    const artWallPlane = addMesh(g, new THREE.PlaneGeometry(3.40, 1.65), artWallMat, innerWallX - 0.195, terraceH + 1.25, 18.80, false);
    artWallPlane.rotation.y = -Math.PI / 2;
    // 展覽板下方置物與作品展示長托木几 (Display Ledge)
    addBox(g, 0.22, 0.08, 3.52, artFrameMat, innerWallX - 0.26, terraceH + 0.38, 18.80, false);

    // 展板前方【學童防護木質不銹鋼雙層護欄】(Protective Safety Railing per Image 1 實拍)
    // 防止跑道學童撞擊或觸摸作品展板，高約 0.85m
    const railX = innerWallX - 0.58;
    addBox(g, 0.06, 0.05, 3.50, artRailMat, railX, terraceH + 0.85, 18.80, false);  // 上扶手
    addBox(g, 0.05, 0.04, 3.50, artMetalMat, railX, terraceH + 0.45, 18.80, false); // 中橫桿
    for (let rp = 0; rp <= 6; rp++) {
      const rpZ = 18.80 - 1.65 + rp * (3.30 / 6);
      addMesh(g, new THREE.CylinderGeometry(0.02, 0.02, 0.85, 8), artMetalMat, railX, terraceH + 0.425, rpZ, false);
    }

    // 1F 幼兒園鋁合金採光出入門 (含深色門框、橫向採光玻璃與踢腳板)
    addBox(g, 0.08, 2.15, 0.98, whiteMetalMat, innerWallX - 0.19, terraceH + 1.075, 21.60);
    const doorGlassMat = new THREE.MeshStandardMaterial({ color: 0x82a8be, roughness: 0.15, metalness: 0.3, transparent: true, opacity: 0.6 });
    addBox(g, 0.02, 1.45, 0.78, doorGlassMat, innerWallX - 0.19, terraceH + 1.25, 21.60, false);
    addBox(g, 0.04, 0.45, 0.82, whiteMetalMat, innerWallX - 0.19, terraceH + 0.25, 21.60, false); // 下部踢腳鋼板
    addBox(g, 0.04, 0.14, 0.03, darkCopingMat, innerWallX - 0.24, terraceH + 1.05, 21.95, false); // 金屬把手

    // ------------------------------------------------------------------------
    // (E) 2F 操場側內縮走廊、女兒牆與【綠色防焰遮光捲簾/百葉】（Image 1 實拍）
    // ------------------------------------------------------------------------
    // 2F 樓板結構
    addBox(g, wStW, 0.32, westD, mats.slab, wStCx, y2F + 0.16, westCz);
    // 2F 跑道側白色磁磚欄杆女兒牆
    addBox(g, 0.28, parapetH, westD, whiteTileMat, wStX1 + 0.14, y2F + parapetH / 2, westCz);
    addBox(g, 0.34, 0.08, westD, darkCopingMat, wStX1 + 0.14, y2F + parapetH + 0.04, westCz);
    // 2F 結構方柱
    addBox(g, 0.44, FH - 0.32, 0.44, whiteTileMat, wStX1 + 0.22, y2F + FH / 2, zE + 0.22);
    addBox(g, 0.44, FH - 0.32, 0.44, whiteTileMat, wStX1 + 0.22, y2F + FH / 2, zD);
    addBox(g, 0.44, FH - 0.32, 0.44, whiteTileMat, wStX1 + 0.22, y2F + FH / 2, zA - 0.22);
    // 2F 上方清水混凝土結構梁
    addBox(g, 0.34, 0.52, westD, exposedConcreteBeamMat, wStX1 + 0.17, y2F + FH - 0.26, westCz);
    // 2F 開口處懸掛之草綠色防焰遮陽捲簾（Image 1 實拍）
    addBox(g, 0.05, 1.65, 3.80, greenBlindMat, wStX1 + 0.24, y2F + FH - 1.15, 18.20);

    // 依 1F/3F 平面圖配置：新棟主樓梯間位於西側 ①–② 軸，內部折返樓梯自 2F 升至 3F
    const wFlight2 = new THREE.Mesh(new THREE.BoxGeometry(extStairW, 0.26, extStairLen), exposedConcreteBeamMat);
    wFlight2.position.set(extStairCx, y2F + FH / 2 - 0.13, (extStairZ1 + extStairZ2) / 2);
    wFlight2.rotation.x = extStairPitch;
    g.add(wFlight2);
    for (let st = 0; st < nExtSteps; st++) {
      const sy = y2F + (st + 1) * (FH / nExtSteps);
      const sz = extStairZ1 + (st + 0.5) * (extStairRun / nExtSteps);
      addBox(g, extStairW - 0.10, FH / nExtSteps, extStairRun / nExtSteps, mats.concrete, extStairCx, sy - (FH / nExtSteps) / 2, sz, false);
    }
    const stairRail2 = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, extStairLen + 0.2), handrailMat);
    stairRail2.position.set(outerRailX, y2F + FH / 2 + 0.80, (extStairZ1 + extStairZ2) / 2);
    stairRail2.rotation.x = extStairPitch;
    g.add(stairRail2);

    // ------------------------------------------------------------------------
    // (F) 3F 操場側橫長條排窗、灰色水平飾帶與屋頂女兒牆（Image 1 實拍）
    // ------------------------------------------------------------------------
    // 3F 樓板結構
    addBox(g, wStW, 0.32, westD, mats.slab, wStCx, y3F + 0.16, westCz);
    // 依 3F 平面圖：3F 至屋頂層內部折返樓梯（新棟主樓梯間 ①–②）
    const wFlight3 = new THREE.Mesh(new THREE.BoxGeometry(extStairW, 0.26, extStairLen), exposedConcreteBeamMat);
    wFlight3.position.set(extStairCx, y3F + FH / 2 - 0.13, (extStairZ1 + extStairZ2) / 2);
    wFlight3.rotation.x = extStairPitch;
    g.add(wFlight3);
    for (let st = 0; st < nExtSteps; st++) {
      const sy = y3F + (st + 1) * (FH / nExtSteps);
      const sz = extStairZ1 + (st + 0.5) * (extStairRun / nExtSteps);
      addBox(g, extStairW - 0.10, FH / nExtSteps, extStairRun / nExtSteps, mats.concrete, extStairCx, sy - (FH / nExtSteps) / 2, sz, false);
    }
    // 3F 實體白磁磚牆與橫向帶狀鋁合金採光排窗
    addBox(g, 0.28, 0.95, westD, whiteTileMat, wStX1 + 0.14, y3F + 0.475, westCz);
    addBox(g, 0.28, 0.85, westD, whiteTileMat, wStX1 + 0.14, y3F + FH - 0.425, westCz);
    // 灰色水平結構飾帶（Horizontal Gray Spandrel Band, Image 1）
    addBox(g, 0.32, 0.44, westD, new THREE.MeshStandardMaterial({ color: 0x565c64, roughness: 0.65 }), wStX1 + 0.14, y3F + 0.95 + 0.22, westCz);
    // 3F 鋁合金橫拉排窗
    for (let w = 0; w < 3; w++) {
      const wz = zE + 1.60 + w * 2.80;
      const winP = addMesh(g, new THREE.PlaneGeometry(2.20, 1.45), makeWindowMaterial(`new-w3f-${w}`), wStX1 - 0.01, y3F + 2.05, wz, false);
      winP.rotation.y = -Math.PI / 2;
    }
    // 屋頂層結構樓板、女兒牆與防水壓頂（封閉西側樓梯間頂部）
    addBox(g, wStW, 0.32, westD, mats.roof, wStCx, yRF + 0.16, westCz);
    addBox(g, 0.28, parapetH, westD, whiteTileMat, wStX1 + 0.14, yRF + parapetH / 2, westCz);
    addBox(g, 0.34, 0.08, westD, darkCopingMat, wStX1 + 0.14, yRF + parapetH + 0.04, westCz);
    // 南向女兒牆封邊
    addBox(g, wStW, parapetH, 0.28, whiteTileMat, wStCx, yRF + parapetH / 2, zA - 0.14);
    addBox(g, wStW + 0.06, 0.08, 0.34, darkCopingMat, wStCx, yRF + parapetH + 0.04, zA - 0.14);

    // ------------------------------------------------------------------------
    // (G) 【操場轉角校園茂密大樹】（Tall Sprawling Campus Shade Tree, Image 1 & 2）
    // 依實拍照片 Image 1 & 2：大樹雄踞於西棟與新棟交界處跑道前，主幹蒼勁向四周蓬勃伸展，
    // 繁茂濃密的多層次樹冠貫穿 1F～3F 頂層（高達 12 米），投下大片綠蔭，為全場畫龍點睛之靈魂焦點！
    // ------------------------------------------------------------------------
    const trackTreeX = -38.85;
    const trackTreeZ = 16.90;
    const tTrunkMat  = new THREE.MeshStandardMaterial({ color: 0x483a2c, roughness: 0.94 });
    const tLeafMat1  = new THREE.MeshStandardMaterial({ color: 0x275924, roughness: 0.82 });
    const tLeafMat2  = new THREE.MeshStandardMaterial({ color: 0x38752e, roughness: 0.78 });
    const tLeafMat3  = new THREE.MeshStandardMaterial({ color: 0x1b4218, roughness: 0.88 });

    // 操場跑道緣石邊之【圓形洗石子樹穴保護緣石】(Circular Tree-Well Curb per Image 1)
    const treeWellCurbMat = new THREE.MeshStandardMaterial({ color: 0xbcb7ab, roughness: 0.72 });
    addMesh(g, new THREE.CylinderGeometry(1.15, 1.25, 0.12, 18), treeWellCurbMat, trackTreeX, 0.06, trackTreeZ, false);
    const treeSoilMat = new THREE.MeshStandardMaterial({ color: 0x5a483a, roughness: 0.95 });
    addMesh(g, new THREE.CylinderGeometry(1.05, 1.05, 0.08, 18), treeSoilMat, trackTreeX, 0.08, trackTreeZ, false);

    // 主樹幹 (粗壯挺拔，下粗上微收)
    const tTrunk = addMesh(g, new THREE.CylinderGeometry(0.32, 0.52, 5.2, 12), tTrunkMat, trackTreeX, 2.6, trackTreeZ);
    tTrunk.rotation.z = 0.05;
    tTrunk.rotation.x = -0.04;

    // 四大向外伸展粗木分枝
    const b1 = addMesh(g, new THREE.CylinderGeometry(0.20, 0.28, 4.2, 8), tTrunkMat, trackTreeX + 0.65, 6.2, trackTreeZ - 0.45);
    b1.rotation.z = -0.32; b1.rotation.x = -0.22;
    const b2 = addMesh(g, new THREE.CylinderGeometry(0.18, 0.26, 4.5, 8), tTrunkMat, trackTreeX - 0.75, 6.4, trackTreeZ + 0.35);
    b2.rotation.z = 0.35;  b2.rotation.y = 0.18;
    const b3 = addMesh(g, new THREE.CylinderGeometry(0.16, 0.24, 3.8, 8), tTrunkMat, trackTreeX + 0.35, 6.6, trackTreeZ + 0.75);
    b3.rotation.x = 0.38;
    const b4 = addMesh(g, new THREE.CylinderGeometry(0.15, 0.22, 3.6, 8), tTrunkMat, trackTreeX - 0.25, 6.8, trackTreeZ - 0.85);
    b4.rotation.x = -0.35; b4.rotation.z = -0.15;

    // 繁茂濃密多層次有機樹冠球群 (Dense Multilayer Foliage Spheres, Y=4.5m ~ 12.4m)
    const trackTreeCanopy = [
      // 頂層向陽樹冠 (Y = 9.2 ~ 12.4m)
      { x: trackTreeX + 0.2, y: 11.5, z: trackTreeZ - 0.3, rx: 2.6, ry: 1.8, rz: 2.4, m: tLeafMat2 },
      { x: trackTreeX - 0.9, y: 10.8, z: trackTreeZ + 0.5, rx: 2.3, ry: 1.6, rz: 2.1, m: tLeafMat1 },
      { x: trackTreeX + 1.1, y: 11.0, z: trackTreeZ + 0.6, rx: 2.4, ry: 1.7, rz: 2.2, m: tLeafMat2 },
      { x: trackTreeX + 0.4, y: 10.2, z: trackTreeZ - 1.1, rx: 2.1, ry: 1.5, rz: 2.0, m: tLeafMat1 },
      // 中層豐厚大樹冠 (Y = 6.8 ~ 9.5m)
      { x: trackTreeX - 1.4, y: 8.4,  z: trackTreeZ - 0.4, rx: 2.5, ry: 1.8, rz: 2.3, m: tLeafMat1 },
      { x: trackTreeX + 1.5, y: 8.6,  z: trackTreeZ + 0.4, rx: 2.7, ry: 1.9, rz: 2.5, m: tLeafMat2 },
      { x: trackTreeX - 0.4, y: 8.0,  z: trackTreeZ + 1.4, rx: 2.3, ry: 1.7, rz: 2.2, m: tLeafMat3 },
      { x: trackTreeX + 0.5, y: 8.2,  z: trackTreeZ - 1.3, rx: 2.4, ry: 1.7, rz: 2.3, m: tLeafMat1 },
      { x: trackTreeX + 0.1, y: 8.8,  z: trackTreeZ + 0.1, rx: 2.8, ry: 2.0, rz: 2.7, m: tLeafMat1 },
      // 底層垂蔭枝葉 (Y = 4.5 ~ 6.8m)
      { x: trackTreeX - 1.1, y: 5.8,  z: trackTreeZ - 0.3, rx: 1.9, ry: 1.4, rz: 1.8, m: tLeafMat3 },
      { x: trackTreeX + 1.1, y: 6.0,  z: trackTreeZ + 0.5, rx: 2.0, ry: 1.5, rz: 1.9, m: tLeafMat3 },
      { x: trackTreeX + 0.2, y: 5.4,  z: trackTreeZ - 0.9, rx: 1.8, ry: 1.3, rz: 1.7, m: tLeafMat3 }
    ];
    trackTreeCanopy.forEach(tc => {
      const sp = addMesh(g, new THREE.SphereGeometry(1.0, 12, 10), tc.m, tc.x, tc.y, tc.z);
      sp.scale.set(tc.rx, tc.ry, tc.rz);
    });

    // ------------------------------------------------------------------------
    // (H) 南向臨街 1F 門樓與 2F/3F 水泥空心花磚牆（維持南向設計對齊）
    // ------------------------------------------------------------------------
    addBox(g, 0.36, yRF + 0.85, sCorD, whiteTileMat, wStX2 - 0.18, (yRF + 0.85) / 2, sCorCz);

    // 1F 南向門樓與深褐橢圓園名牌（`新棟正面立圖_南向.jpg`）
    addBox(g, wStW, 1.05, 0.36, whiteTileMat, wStCx, 3.25, zA - 0.18);
    const sOvalTex = makeKindergartenBlackSignTexture();
    addMesh(g, new THREE.PlaneGeometry(2.60, 0.68), new THREE.MeshBasicMaterial({ map: sOvalTex, transparent: true }), wStCx, 3.02, zA + 0.02, false);

    // 2F & 3F 空心花磚遮陽隔柵牆（`水泥空心花磚牆`）
    const breezeTex = makeBreezeBlockGrilleTexture();
    const breezeMat = new THREE.MeshStandardMaterial({ map: breezeTex, roughness: 0.78 });
    for (let f = 1; f <= 2; f++) {
      const fy = f * FH;
      addBox(g, wStW - 0.52, FH - 0.48, 0.22, breezeMat, wStCx, fy + FH / 2, zA - 0.14);
      addBox(g, wStW, 0.36, 0.36, whiteTileMat, wStCx, fy + FH - 0.18, zA - 0.18);
    }
    // 南向屋頂女兒牆
    addBox(g, wStW, 0.85, 0.32, whiteTileMat, wStCx, yRF + 0.42, zA - 0.16);

    // --- 4.2 `②–⑧` South Balcony Corridor (`ax(2)=-33.31` to `ax(8)=-15.31`, width 18.00m, `zB` to `zA`) ---
    const sCorX1 = ax(2), sCorX2 = ax(8);
    const sCorW = sCorX2 - sCorX1; // 18.00m
    const sCorCx = (sCorX1 + sCorX2) / 2;

    for (let f = 0; f < 3; f++) {
      const fy = f * FH;
      // Floor slab
      addBox(g, sCorW, 0.30, sCorD, mats.slab, sCorCx, fy + 0.15, sCorCz);
      // White-tiled corridor parapet at `zA` (2F & 3F full parapet, 1F low curb + columns opening to playground)
      if (f > 0) {
        addBox(g, sCorW, parapetH, 0.26, whiteTileMat, sCorCx, fy + parapetH / 2, zA - 0.13);
        addBox(g, sCorW + 0.06, 0.07, 0.32, darkCopingMat, sCorCx, fy + parapetH + 0.035, zA - 0.13);
      } else {
        addBox(g, sCorW, 0.24, 0.30, mats.concrete, sCorCx, 0.12, zA - 0.15);
      }
      // Upper spandrel beam at `zA`
      addBox(g, sCorW, 0.42, 0.30, whiteTileMat, sCorCx, fy + FH - 0.21, zA - 0.15);
    }

    // Structural piers along `zA` (`②, ③, ④, ⑥, ⑦, ⑧`)
    [2, 3, 4, 6, 7, 8].forEach(idx => {
      addBox(g, 0.42, yRF, 0.42, whiteTileMat, ax(idx), yRF / 2, zA - 0.21);
    });

    // TWO Protruding Terracotta Brick Balcony Boxes on 2F & 3F of South Facade
    // 依據建築平面圖與街景實拍：第 1 座位於 ③–④ 跨距 (教室301中央陽台)，第 2 座位於 ⑥–⑧ 跨距 (教室302南向陽台)
    const sBox1Cx = (ax(3) + ax(4)) / 2;
    const sBox1W  = (ax(4) - ax(3)) - 0.36;
    const sBox2Cx = (ax(6) + ax(8)) / 2;
    const sBox2W  = (ax(8) - ax(6)) - 0.48;
    for (const fy of [y2F, y3F]) {
      addTerracottaBalconyBox(sBox1Cx, fy + parapetH / 2 + 0.08, zA + 0.16, sBox1W, parapetH + 0.16, 0.44, 1);
      addTerracottaBalconyBox(sBox2Cx, fy + parapetH / 2 + 0.08, zA + 0.16, sBox2W, parapetH + 0.16, 0.44, 1);
    }

    // 2F Bright Green Roll-Down Sunshade Blinds (`鮮綠色防焰遮光捲簾` 依實景照片 001.jpg 與建興南路街景逐開間懸掛)
    const blindBays = [[ax(2), ax(3)], [ax(3), ax(4)], [ax(5), ax(7)], [ax(7), ax(8)]];
    blindBays.forEach(([bx1, bx2], idx) => {
      const bw = (bx2 - bx1) - 0.46;
      const bcx = (bx1 + bx2) / 2;
      const bh = (idx === 1 || idx === 3) ? 1.55 : 1.85;
      addMesh(g, new THREE.PlaneGeometry(bw, bh), greenBlindMat, bcx, y2F + FH - 0.42 - bh / 2, zA - 0.05, false);
    });

    // White PVC Vertical Downspout Pipes on South Facade
    [ax(3), ax(5), ax(7), ax(8)].forEach(px => {
      addMesh(g, new THREE.CylinderGeometry(0.05, 0.05, yRF, 10), pvcPipeMat, px + 0.22, yRF / 2, zA + 0.03, false);
    });

    // --- 4.3 `⑧–⑩` Recessed Restroom & Kitchen Wing (`ax(8)=-15.31` to `ax(10)=-6.72`, South wall at `zB=24.153m`) ---
    // Matches `新棟南向正面_右手邊45度側面001.jpg`:
    // - Left half (`⑧–⑨`, width 4.575m): Cream-white wall with 3-story Geometric Abstract Mural (1F terracotta spiral, 2F diagonal staff, 3F yellow sun)
    // - Right half (`⑨–⑩`, width 4.015m): 1F/2F/3F Horizontal Rectangular Louvered Restroom Windows with protruding white box frames on BOTH South face (`zB`) and East face (`ax(10)`)!
    const muralX1 = ax(8), muralX2 = ax(9);
    const muralW = muralX2 - muralX1; // 4.575m
    const muralCx = (muralX1 + muralX2) / 2;
    const muralTex = makeSouthEastAbstractMuralTexture();
    addMesh(g, new THREE.PlaneGeometry(muralW - 0.18, yRF - 0.35), new THREE.MeshBasicMaterial({ map: muralTex }), muralCx, yRF / 2, zB + 0.23, false);

    // Right half (`⑨–⑩`): Protruding White-Framed Horizontal Restroom Windows on 1F, 2F, 3F (`zB` South face & `ax(10)` East face)
    const wcX1 = ax(9), wcX2 = ax(10);
    const wcCx = (wcX1 + wcX2) / 2;
    const wcFrameMat = new THREE.MeshStandardMaterial({ color: 0xf7f7f4, roughness: 0.45 });
    const wcGlassMat = new THREE.MeshStandardMaterial({ color: 0x24343d, roughness: 0.25, metalness: 0.4 });
    for (let f = 0; f < 3; f++) {
      const wy = f * FH + 2.15;
      // South-facing protruding box window on `⑨–⑩` (`zB`)
      addBox(g, 2.35, 1.08, 0.34, wcFrameMat, wcCx, wy, zB + 0.22);
      addBox(g, 2.15, 0.88, 0.38, wcGlassMat, wcCx, wy, zB + 0.23);
      addBox(g, 0.06, 0.88, 0.40, wcFrameMat, wcCx, wy, zB + 0.24);
      // East-facing protruding box window on `ax(10)` (`zC` to `zB` side wall, visible in `001.jpg`!)
      const eastWinZ = (zC + zB) / 2 + 0.25;
      addBox(g, 0.34, 1.05, 1.75, wcFrameMat, wcX2 + 0.20, wy, eastWinZ);
      addBox(g, 0.38, 0.85, 1.55, wcGlassMat, wcX2 + 0.21, wy, eastWinZ);
    }
    // Roof parapet over `⑧–⑩` at `zB`
    addBox(g, ax(10) - ax(8), 0.82, 0.30, creamWallMat, (ax(8) + ax(10)) / 2, yRF + 0.41, zB - 0.15);
    addBox(g, ax(10) - ax(8) + 0.06, 0.08, 0.36, darkCopingMat, (ax(8) + ax(10)) / 2, yRF + 0.85, zB - 0.15);

    // --- 4.4 Pitched Terracotta-Red Roof (`紅瓦斜屋頂`, over `②–⑩` main block) ---
    const roofW = ax(10) - ax(2);
    const roofCx = (ax(2) + ax(10)) / 2;
    const roofD = zA - zD;
    const roofCz = (zD + zA) / 2;
    const ridgeH = 2.45;
    // South & North sloped roof planes
    for (const side of [-1, 1]) {
      const halfD = roofD / 2 + 0.45;
      const slopeLen = Math.hypot(halfD, ridgeH);
      const slopeAng = Math.atan2(ridgeH, halfD);
      const plane = new THREE.Mesh(new THREE.BoxGeometry(roofW + 0.4, 0.22, slopeLen), roofTileRedMat);
      plane.position.set(roofCx, yRF + ridgeH / 2 + 0.2, roofCz + side * (halfD / 2 - 0.15));
      plane.rotation.x = side * slopeAng;
      g.add(plane);
    }
    // Roof ridge beam & gable end triangles
    addBox(g, roofW + 0.5, 0.28, 0.36, roofTileRedMat, roofCx, yRF + ridgeH + 0.22, roofCz);
    // 西側屋頂山牆封板 (ax(2) 封閉紅瓦斜屋頂內部，免除中空透視)
    addBox(g, 0.32, ridgeH * 0.95, roofD * 0.95, creamWallMat, ax(2), yRF + ridgeH / 2, roofCz);

    // --- 4.5 `⑩–⑪` 銜接走廊通道南口凹槽與環境設施 (`20261106_142631.jpg`, `142616.jpg`, `142638.jpg`, `新棟南向_右手邊45度側面001.jpg`) ---
    const pocketX1 = ax(10), pocketX2 = ax(11); // -6.72m ~ -4.22m, 寬 2.50m
    const pocketCx = (pocketX1 + pocketX2) / 2;

    // 通道南口前庭磨石子/水泥平整地坪 (Paved Entrance Apron between zC=20.28m and sidewalk z=24.20m)
    addBox(g, pocketX2 - pocketX1 + 0.60, 0.06, 4.10, mats.concrete, pocketCx, 0.03, 22.25, false);

    // ----------------------------------------------------------------------
    // 4.6 銜接走廊通道南口與「欄杆小門」極致對位 (`20261106_142631.jpg` & `142638.jpg` & `142616.jpg`)
    //   由左至右：
    //   (1) 西側牆面 (`ax(10)` zC~zB)：全高白色二丁掛磁磚外牆 + 1F 灰白色金屬配電箱、粉黃宣導海報與低矮花台綠植
    //   (2) 東側牆柱 (`ax(11)` zG~zC)：白色二丁掛磁磚結構方柱 + 淺米白走廊側牆與各層清水混凝土梁帶
    //   (3) 通道南口「欄杆小門」(`gateZ = 22.58m`)：左側白門柱(附不鏽鋼對講機門鈴盒) + 白色垂直欄杆門扇(附藍框公告牌) + 右側白色寬方柱(正面貼「禁止吸菸」紅圈標誌與「無菸校園」標章)
    //   (4) 通道口東側柱前：白色彎頭鵝頸路燈 (`142616.jpg`)
    //   (5) 新棟 `⑨–⑩` 轉角人行道：「注意」凸面反射鏡桿與三角錐 (`001.jpg`)
    // ----------------------------------------------------------------------
    const gate10W = pocketX2 - pocketX1; // 通道口寬 2.50m
    const gateZ = 22.58;                 // 與南棟前彩虹欄杆線對齊，欄杆小門位於通道南口
    const gateH = 1.72;
    const gatePostMat = whiteMetalMat;
    const gateDarkMat = new THREE.MeshStandardMaterial({ color: 0x2a2e33, roughness: 0.45, metalness: 0.6 });

    // (1) 西側牆面 (`ax(10)` zC=20.28 至 zB=24.153)：白色二丁掛磁磚牆面、灰白色配電箱與粉黃宣導海報 (`20261106_142631.jpg`)
    const westPocketD = zB - zC; // 3.873m
    const westPocketCz = (zC + zB) / 2;
    addBox(g, 0.08, yRF, westPocketD, whiteTileMat, pocketX1 + 0.04, yRF / 2, westPocketCz);
    // 1F 西側牆面灰白色金屬配電箱與垂直配管 (`20261106_142631.jpg`)
    const elecBoxMat = new THREE.MeshStandardMaterial({ color: 0xd8dce0, roughness: 0.38, metalness: 0.45 });
    addBox(g, 0.12, 0.58, 0.42, elecBoxMat, pocketX1 + 0.10, 1.52, 21.48, false);
    addMesh(g, new THREE.CylinderGeometry(0.016, 0.016, 1.45, 8), elecBoxMat, pocketX1 + 0.09, 2.52, 21.42, false);
    // 1F 西側牆面粉紅/鵝黃雙色宣導海報 (`20261106_142631.jpg`)
    addBox(g, 0.02, 0.52, 0.38, new THREE.MeshStandardMaterial({ color: 0xf4b8c4, roughness: 0.6 }), pocketX1 + 0.09, 1.50, 20.72, false);
    addBox(g, 0.025, 0.24, 0.34, new THREE.MeshStandardMaterial({ color: 0xf7e479, roughness: 0.6 }), pocketX1 + 0.095, 1.38, 20.72, false);
    // 1F 西側牆腳低矮洗石子花台與綠植 (`20261106_142631.jpg`)
    const planterCurbMat = new THREE.MeshStandardMaterial({ color: 0xb5afa4, roughness: 0.68 });
    const planterHedgeMat = new THREE.MeshStandardMaterial({ color: 0x4a8c3d, roughness: 0.80 });
    addBox(g, 0.36, 0.24, 1.65, planterCurbMat, pocketX1 + 0.22, 0.12, 21.35, false);
    for (let p = 0; p < 3; p++) {
      const sp = addMesh(g, new THREE.SphereGeometry(0.22, 8, 8), planterHedgeMat, pocketX1 + 0.24, 0.34, 20.80 + p * 0.52, false);
      sp.scale.set(0.9, 0.85, 1.1);
    }

    // (2) 東側牆面 (`ax(11)` zG=8.78 至 zC=20.28)：淺米白走廊內牆 + 清水混凝土樓層橫梁帶 + 白色二丁掛磁磚端柱 (`142631.jpg` & `142638.jpg`)
    addBox(g, 0.16, yRF, zC - 10.78, creamWallMat, pocketX2 - 0.08, yRF / 2, (10.78 + zC) / 2);
    for (let f = 1; f <= 3; f++) {
      addBox(g, 0.20, 0.48, zC - 10.78, exposedConcreteBeamMat, pocketX2 - 0.10, f * FH - 0.24, (10.78 + zC) / 2, false);
    }

    // (3) 白色垂直欄杆小門 (`欄杆小門`, `20261106_142631.jpg` & `001.jpg`)
    const gx1 = pocketX1 + 0.12;                 // 西側門柱中心 (緊貼西側白磁磚牆)
    const whitePillarW = 0.44;                   // 東側白色寬方柱寬度
    const whitePillarCx = pocketX2 - 0.22;       // 東側白色寬方柱中心 (`x = -4.44m`)
    const gx2 = whitePillarCx - whitePillarW / 2 - 0.06; // 欄杆門扇東端柱
    const gMidX = gx1 + (gx2 - gx1) * 0.48;      // 中柱 (固定扇 / 開啟扇分界)

    // 左側門柱與不鏽鋼門鈴對講機盒 (`20261106_142631.jpg`)
    addBox(g, 0.12, gateH + 0.12, 0.12, gatePostMat, gx1, (gateH + 0.12) / 2, gateZ);
    addBox(g, 0.14, 0.22, 0.08, handrailMat, gx1 + 0.02, 1.28, gateZ + 0.08, false); // 不鏽鋼對講機盒

    for (const px of [gMidX, gx2]) {
      addBox(g, 0.08, gateH + 0.06, 0.08, gatePostMat, px, (gateH + 0.06) / 2, gateZ);
      addBox(g, 0.11, 0.04, 0.11, gatePostMat, px, gateH + 0.08, gateZ, false);
    }

    const gatePanels = [[gx1 + 0.06, gMidX - 0.04, false], [gMidX + 0.04, gx2 - 0.04, true]];
    for (const [pxa, pxb, isLeaf] of gatePanels) {
      const pw = pxb - pxa, pcx = (pxa + pxb) / 2;
      // 上 / 中 / 下 三道白色橫桿
      addBox(g, pw, 0.045, 0.045, whiteMetalMat, pcx, gateH, gateZ);
      addBox(g, pw, 0.04, 0.04, whiteMetalMat, pcx, 0.96, gateZ);
      addBox(g, pw, 0.08, 0.04, whiteMetalMat, pcx, 0.18, gateZ);
      // 垂直白色細欄杆 (間距約 8.5cm)
      const nB = Math.max(5, Math.round(pw / 0.085));
      for (let b = 0; b <= nB; b++) {
        const bx = pxa + (b / nB) * pw;
        addBox(g, 0.022, gateH - 0.16, 0.022, whiteMetalMat, bx, 0.16 + (gateH - 0.16) / 2, gateZ, false);
      }
      if (isLeaf) {
        // 門扇中央藍框白底公告牌 (`請隨手關門`) 與黃色提示卡 (`20261106_142631.jpg`)
        addBox(g, 0.26, 0.34, 0.02, new THREE.MeshStandardMaterial({ color: 0x1e62b5, roughness: 0.4 }), pcx - 0.08, 1.18, gateZ + 0.02, false);
        addBox(g, 0.22, 0.30, 0.024, whiteMetalMat, pcx - 0.08, 1.18, gateZ + 0.022, false);
        addBox(g, 0.16, 0.22, 0.02, new THREE.MeshStandardMaterial({ color: 0xf5d64e, roughness: 0.5 }), pcx + 0.16, 1.16, gateZ + 0.02, false);
        // 門閂與把手
        addBox(g, 0.08, 0.14, 0.06, gateDarkMat, pxa + 0.06, 1.00, gateZ + 0.04, false);
      }
    }

    // (4) 右側白色寬方柱 (`白色塗裝門柱`, 取代舊紅磚柱，正面貼「禁止吸菸」紅圈標誌與「無菸校園」標貼，`20261106_142631.jpg`)
    const whitePillarH = 1.82;
    addBox(g, whitePillarW, whitePillarH, 0.42, whiteTileMat, whitePillarCx, whitePillarH / 2, gateZ);
    addBox(g, whitePillarW + 0.06, 0.06, 0.48, mats.concrete, whitePillarCx, whitePillarH + 0.03, gateZ, false);
    // 柱面「禁止吸菸」白底紅圈標誌 (`y = 1.42m`) 與下方「無菸校園」綠白標貼 (`y = 1.15m`)
    addBox(g, 0.22, 0.24, 0.015, whiteMetalMat, whitePillarCx, 1.42, gateZ + 0.215, false);
    const noSmokeRing = addMesh(g, new THREE.RingGeometry(0.065, 0.088, 20), new THREE.MeshBasicMaterial({ color: 0xd9241b, side: THREE.DoubleSide }), whitePillarCx, 1.43, gateZ + 0.225, false);
    addBox(g, 0.14, 0.022, 0.01, new THREE.MeshBasicMaterial({ color: 0xd9241b }), whitePillarCx, 1.43, gateZ + 0.226, false).rotation.z = -Math.PI / 4;
    addBox(g, 0.22, 0.16, 0.015, new THREE.MeshStandardMaterial({ color: 0x2b8a44, roughness: 0.5 }), whitePillarCx, 1.16, gateZ + 0.215, false);
    addBox(g, 0.18, 0.10, 0.018, whiteMetalMat, whitePillarCx, 1.16, gateZ + 0.217, false);

    // (5) 白色彎頭鵝頸路燈 (`白色鵝頸路燈`, 立於通道東側柱前 `x = pocketX2 - 0.10, z = 21.42`, 依據 `20261106_142616.jpg` & `142631.jpg`)
    const lampX = pocketX2 - 0.10, lampZ = 21.42;
    addMesh(g, new THREE.CylinderGeometry(0.045, 0.06, 4.50, 10), whiteMetalMat, lampX, 2.25, lampZ, false);
    const lampArm = addMesh(g, new THREE.CylinderGeometry(0.03, 0.038, 0.95, 8), whiteMetalMat, lampX - 0.22, 4.62, lampZ + 0.22, false);
    lampArm.rotation.z = Math.PI / 3.2;
    lampArm.rotation.y = -Math.PI / 4;
    addMesh(g, new THREE.ConeGeometry(0.24, 0.14, 14), whiteMetalMat, lampX - 0.52, 4.72, lampZ + 0.48, false);
    addMesh(g, new THREE.SphereGeometry(0.09, 10, 8), new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfff8e7, emissiveIntensity: 0.7, roughness: 0.2 }), lampX - 0.52, 4.62, lampZ + 0.48, false);

    // (6) 新棟 `⑨–⑩` 東南轉角人行道設施：橘色三角錐與「注意」凸面反射鏡桿 (`新棟南向_右手邊45度側面001.jpg`)
    const coneX = ax(10) - 0.85, coneZ = zB + 0.65;
    addBox(g, 0.38, 0.03, 0.38, coneOrangeMat, coneX, 0.015, coneZ, false);
    addMesh(g, new THREE.ConeGeometry(0.14, 0.65, 14), coneOrangeMat, coneX, 0.35, coneZ);
    addMesh(g, new THREE.CylinderGeometry(0.09, 0.11, 0.10, 14), whiteMetalMat, coneX, 0.38, coneZ, false);

    const mirrorX = ax(10) - 0.28, mirrorZ = zB + 0.72;
    addMesh(g, new THREE.CylinderGeometry(0.042, 0.042, 3.00, 10), new THREE.MeshStandardMaterial({ color: 0x9aa0a6, roughness: 0.4, metalness: 0.7 }), mirrorX, 1.50, mirrorZ);
    for (let sgm = 0; sgm < 6; sgm++) {
      addMesh(g, new THREE.CylinderGeometry(0.048, 0.048, 0.14, 10), sgm % 2 ? gateDarkMat : new THREE.MeshStandardMaterial({ color: 0xf2c418, roughness: 0.5 }), mirrorX, 0.52 + sgm * 0.14, mirrorZ, false);
    }
    addBox(g, 0.24, 0.24, 0.03, new THREE.MeshStandardMaterial({ color: 0xf6e04a, roughness: 0.5 }), mirrorX, 1.52, mirrorZ + 0.05, false);   // 「注意」黃色警示牌
    const mirrorGrp = new THREE.Group();
    mirrorGrp.position.set(mirrorX, 2.68, mirrorZ + 0.06);
    mirrorGrp.rotation.y = -0.45;
    mirrorGrp.add(new THREE.Mesh(new THREE.CircleGeometry(0.35, 24), new THREE.MeshStandardMaterial({ color: 0xcfd8e0, roughness: 0.06, metalness: 0.95 })));
    const mirrorRim = new THREE.Mesh(new THREE.TorusGeometry(0.355, 0.036, 8, 24), new THREE.MeshStandardMaterial({ color: 0xe8541a, roughness: 0.45 }));
    mirrorRim.position.z = -0.005;
    mirrorGrp.add(mirrorRim);
    g.add(mirrorGrp);
  }

  // ==========================================================================
  // 5. KINDERGARTEN SOUTH YARD, PLAYHOUSE CANOPY, MAIN GATE & PERIMETER WALL
  //    (1:1 with `新棟正面立圖_南向.jpg` & `新棟南向正面_右手邊45度側面001.jpg`)
  // ==========================================================================
  {
    const zWall = 34.80; // Southern perimeter wall line along the street
    const zMeet = 20.28; // 南棟南牆面標高
    const gateX1 = -24.20, gateX2 = -19.20; // 5.0m wide Kindergarten Main Gate opening
    const wallYellowMat  = new THREE.MeshStandardMaterial({ color: 0xf4df8e, roughness: 0.72 });
    const capGoldMat     = new THREE.MeshStandardMaterial({ color: 0xe5b53c, roughness: 0.58 });
    const darkIronMat    = new THREE.MeshStandardMaterial({ color: 0x1e2226, roughness: 0.35, metalness: 0.72 });
    const goldIronMat    = new THREE.MeshStandardMaterial({ color: 0xd9ad42, roughness: 0.32, metalness: 0.78 });
    const woodMat        = new THREE.MeshStandardMaterial({ color: 0x9c6438, roughness: 0.78 });
    const woodRoofMat    = new THREE.MeshStandardMaterial({ color: 0x7a4624, roughness: 0.82 });
    const greenSteelMat  = new THREE.MeshStandardMaterial({ color: 0x2e8540, roughness: 0.45, metalness: 0.35 });
    const blueTarpMat    = new THREE.MeshStandardMaterial({ color: 0x2468b8, roughness: 0.55, side: THREE.DoubleSide });
    const turfGreenMat   = new THREE.MeshStandardMaterial({ color: 0x4da856, roughness: 0.86 });
    const matBluePad     = new THREE.MeshStandardMaterial({ color: 0x4c8cd6, roughness: 0.82 });

    // --- 5.1 Outdoor Playground Surface (`zA = 26.70m` to `zWall = 34.80m`, 100% Inside Perimeter Wall!) ---
    // 西段操場/前庭草坪 (ax(1) 至 gateX2 = -19.20，直壁圍牆段 z = 26.70 ~ 34.80)
    const westYardW = gateX2 - ax(1);
    const westYardCx = (ax(1) + gateX2) / 2;
    const yardD = zWall - zA; // 8.10m
    const yardCz = (zA + zWall) / 2;
    addBox(g, westYardW, 0.08, yardD, turfGreenMat, westYardCx, 0.04, yardCz);

    // 東段草坪 (gateX2 至 ax(11)，梯形斜邊段：嚴格受限於斜向圍牆內，不突出圍牆)
    const eastSegs = 8;
    const eastSegW = (ax(11) - gateX2) / eastSegs;
    for (let s = 0; s < eastSegs; s++) {
      const sx1 = gateX2 + s * eastSegW;
      const sx2 = sx1 + eastSegW;
      const scx = (sx1 + sx2) / 2;
      const tMid = (s + 0.5) / eastSegs;
      const wallZAtSeg = zWall + tMid * (zMeet - zWall);
      const segD = Math.max(0.2, wallZAtSeg - 0.3 - zA);
      const segCz = zA + segD / 2;
      addBox(g, eastSegW, 0.08, segD, turfGreenMat, scx, 0.04, segCz);
    }

    // 幼兒園遮雨棚下深藍色安全地墊 (位於遮雨棚鋼柱腳與遊具下方，完全在圍牆內)
    const padX1 = ax(5) + 0.4, padX2 = ax(8) + 0.3; // -23.38m ~ -15.01m
    const padW = padX2 - padX1;
    const padZ1 = zA + 0.3, padZ2 = 29.95; // 遠在圍牆 z=31.03m 之內
    const padD = padZ2 - padZ1;
    addBox(g, padW, 0.10, padD, matBluePad, (padX1 + padX2) / 2, 0.05, (padZ1 + padZ2) / 2);
    // --- 5.2 West Pastel-Yellow Wall with Green Glass Bulletin Board (`ax(1)=-37.83` to `gateX1=-24.20`) ---
    const westWallW = gateX1 - ax(1);       // 13.63m
    const westWallCx = (ax(1) + gateX1) / 2;
    // Solid pastel-yellow wall with sloped cap
    addBox(g, westWallW, 2.05, 0.36, wallYellowMat, westWallCx, 1.025, zWall);
    addBox(g, westWallW + 0.12, 0.14, 0.48, capGoldMat, westWallCx, 2.12, zWall);
    // West return wall closing `ax(1)` from `zA` to `zWall`
    addBox(g, 0.36, 2.05, yardD, wallYellowMat, ax(1) + 0.18, 1.025, yardCz);
    addBox(g, 0.46, 0.14, yardD + 0.1, capGoldMat, ax(1) + 0.18, 2.12, yardCz);

    // Glass-fronted Mint-Green Bulletin Board ("屏東復興非營利幼兒園 教保活動訊息：雨露與新芽") mounted on West Wall
    const bbTex = makeKindergartenBulletinBoardTexture();
    const bbX = gateX1 - 3.6;
    addBox(g, 3.40, 1.65, 0.14, new THREE.MeshStandardMaterial({ color: 0x9ec896, roughness: 0.5 }), bbX, 1.32, zWall + 0.22);
    // Green pitched rain hood over the bulletin board
    addBox(g, 3.65, 0.10, 0.38, greenSteelMat, bbX, 2.20, zWall + 0.28);
    addMesh(g, new THREE.PlaneGeometry(3.26, 1.52), new THREE.MeshBasicMaterial({ map: bbTex }), bbX, 1.32, zWall + 0.30, false);

    // --- 5.3 Kindergarten South Main Gate (`旁邊南側的幼兒園大門`, `gateX1=-24.20` to `gateX2=-19.20`) ---
    // Two grand pastel-yellow square pillars with warm-gold multi-tier molded capitals & white globe lamps
    const globeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfff6dd, emissiveIntensity: 0.35, roughness: 0.2 });
    for (const side of [-1, 1]) {
      const px = side < 0 ? gateX1 : gateX2;
      // Main square pillar
      addBox(g, 0.92, 2.55, 0.92, wallYellowMat, px, 1.275, zWall);
      // Warm-yellow multi-tier molded capital (`暖黃色多層線腳壓頂柱頭`)
      addBox(g, 1.06, 0.12, 1.06, capGoldMat, px, 2.61, zWall);
      addBox(g, 1.18, 0.14, 1.18, capGoldMat, px, 2.74, zWall);
      addBox(g, 0.96, 0.10, 0.96, capGoldMat, px, 2.86, zWall);
      // White spherical globe lamp on top of pillar (`白色圓球柱頭燈`)
      addBox(g, 0.22, 0.12, 0.22, darkCopingMat, px, 2.96, zWall);
      addMesh(g, new THREE.SphereGeometry(0.24, 14, 12), globeMat, px, 3.18, zWall, false);
    }

    // Black-and-Gold Plaque on Right Main Gate Pillar: "屏東縣 屏東復興非營利幼兒園"
    const monTex = makeKindergartenMonumentTexture();
    addBox(g, 0.84, 0.42, 0.06, darkIronMat, gateX2, 1.62, zWall + 0.47);
    addMesh(g, new THREE.PlaneGeometry(0.80, 0.38), new THREE.MeshBasicMaterial({ map: monTex }), gateX2, 1.62, zWall + 0.51, false);

    // Double-Leaf Arched Black & Gold Ornate Wrought-Iron Gate (`雙開拱形黑金鍛造大鐵門`)
    const clearGateW = (gateX2 - gateX1) - 0.92; // 4.08m
    const leafW = clearGateW / 2 - 0.04;
    for (const side of [-1, 1]) {
      const leafGrp = new THREE.Group();
      leafGrp.position.set(side < 0 ? (gateX1 + 0.46) : (gateX2 - 0.46), 0, zWall);
      const dir = -side; // +1 for left leaf, -1 for right leaf
      // Bottom, middle & arched top horizontal rails
      addBox(leafGrp, leafW, 0.06, 0.06, darkIronMat, dir * leafW / 2, 0.22, 0);
      addBox(leafGrp, leafW, 0.05, 0.05, goldIronMat, dir * leafW / 2, 0.52, 0);
      addBox(leafGrp, leafW, 0.06, 0.06, darkIronMat, dir * leafW / 2, 1.95, 0);
      // Vertical wrought-iron bars with rising arch profile & golden finials
      const nBars = 11;
      for (let b = 0; b <= nBars; b++) {
        const t = b / nBars; // 0 at hinge, 1 at center meet
        const bx = dir * t * leafW;
        const archExtra = 0.42 * Math.sin(t * Math.PI * 0.5);
        const bh = 1.85 + archExtra;
        addBox(leafGrp, 0.032, bh, 0.032, darkIronMat, bx, 0.18 + bh / 2, 0, false);
        // Gold spear finial on top of each bar
        addBox(leafGrp, 0.05, 0.12, 0.05, goldIronMat, bx, 0.18 + bh + 0.06, 0, false);
        // Gold decorative ring in lower band
        if (b < nBars && b % 2 === 1) {
          addMesh(leafGrp, new THREE.TorusGeometry(0.08, 0.015, 6, 12), goldIronMat, bx, 0.37, 0, false);
        }
      }
      // Central golden medallion rose in each gate leaf
      addMesh(leafGrp, new THREE.CylinderGeometry(0.22, 0.22, 0.04, 16), goldIronMat, dir * leafW * 0.52, 1.22, 0, false).rotation.x = Math.PI / 2;
      g.add(leafGrp);
    }

    // --- 5.4 East Stepped Pastel-Yellow Perimeter Wall (`gateX2=-19.20` to `ax(11)=-4.22`) ---
    // 參照學校平面圖進行延伸：自幼兒園大門斜向平順延伸銜接至南棟大樓西端 (Z=20.28m) 與舊南側門，形成連續通學步道界面！
    const eastWallX1 = gateX2 + 0.46, eastWallX2 = ax(11);
    const nEastBays = 4;
    const eastBayW = (eastWallX2 - eastWallX1) / nEastBays;
    const wallAng = -Math.atan2(zMeet - zWall, eastWallX2 - eastWallX1);

    for (let i = 0; i < nEastBays; i++) {
      // 依街景照片：圍牆止於新棟東南轉角，通道南口 (欄杆小門) 直接面向人行道，不再有斜牆橫亙其前
      if (i === nEastBays - 1) continue;
      const bx1 = eastWallX1 + i * eastBayW;
      const bx2 = bx1 + eastBayW;
      const bcx = (bx1 + bx2) / 2;
      const tMid = (i + 0.5) / nEastBays;
      const tEnd = (i + 1.0) / nEastBays;
      const bcz = zWall + tMid * (zMeet - zWall);
      const bz2 = zWall + tEnd * (zMeet - zWall);

      const bayGrp = new THREE.Group();
      bayGrp.position.set(bcx, 0, bcz);
      bayGrp.rotation.y = wallAng;

      // 鵝黃色梯形實體基座矮牆
      const segLen = eastBayW / Math.cos(Math.abs(wallAng));
      addBox(bayGrp, segLen, 0.92, 0.34, wallYellowMat, 0, 0.46, 0);
      addBox(bayGrp, segLen, 0.08, 0.40, capGoldMat, 0, 0.96, 0);

      // 白色垂直金屬格柵
      const gw = segLen - 0.62;
      addBox(bayGrp, gw, 0.04, 0.04, whiteMetalMat, -0.15, 1.92, 0);
      addBox(bayGrp, gw, 0.04, 0.04, whiteMetalMat, -0.15, 1.12, 0);
      for (let b = 1; b < 9; b++) {
        const barX = -0.15 - gw / 2 + (b / 9) * gw;
        addBox(bayGrp, 0.025, 0.92, 0.025, whiteMetalMat, barX, 1.48, 0, false);
      }
      g.add(bayGrp);

      // 間隔立柱 (附暖金色多層線腳壓頂)
      addBox(g, 0.62, 2.05, 0.56, wallYellowMat, bx2, 1.025, bz2);
      addBox(g, 0.74, 0.10, 0.68, capGoldMat, bx2, 2.10, bz2);
      addBox(g, 0.82, 0.12, 0.76, capGoldMat, bx2, 2.21, bz2);
    }

    // 幼兒園招生宣傳大型橫額 ("選擇復興 非營利幼兒園 家長安心")
    const bannerTex = makeFenceBannerTexture();
    const bannerMidX = (eastWallX1 + eastWallX2) / 2;
    const bannerMidZ = (zWall + zMeet) / 2;
    const bMesh = addMesh(g, new THREE.PlaneGeometry(5.6, 0.86), new THREE.MeshBasicMaterial({ map: bannerTex }), bannerMidX, 1.48, bannerMidZ + 0.25, false);
    bMesh.rotation.y = wallAng;

    // --- 5.5 Interior Wooden Gable-Roofed Playhouse & Slide Tower (West Yard, behind Bulletin Board in `新棟正面立圖_南向.jpg`) ---
    const phX = -27.5, phZ = 30.8;
    // Raised wooden deck & 4 corner timber posts
    addBox(g, 3.2, 0.18, 2.6, woodMat, phX, 1.45, phZ);
    for (const sx of [-1.4, 1.4]) {
      for (const sz of [-1.1, 1.1]) {
        addBox(g, 0.18, 3.4, 0.18, woodMat, phX + sx, 1.7, phZ + sz);
      }
    }
    // Wooden railings & gable roof
    addBox(g, 3.0, 0.72, 0.10, woodMat, phX, 1.9, phZ + 1.1);
    addBox(g, 3.0, 0.72, 0.10, woodMat, phX, 1.9, phZ - 1.1);
    for (const side of [-1, 1]) {
      const rPlane = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.14, 1.75), woodRoofMat);
      rPlane.position.set(phX, 3.65, phZ + side * 0.68);
      rPlane.rotation.x = side * 0.46;
      g.add(rPlane);
    }
    // Yellow spiral/chute slide extending from wooden playhouse
    const slideMat = new THREE.MeshStandardMaterial({ color: 0xf2c029, roughness: 0.35 });
    const slideMesh = new THREE.Mesh(new THREE.BoxGeometry(0.75, 0.18, 2.8), slideMat);
    slideMesh.position.set(phX + 2.1, 0.82, phZ + 0.2);
    slideMesh.rotation.z = -0.48;
    g.add(slideMesh);

    // --- 5.6 Green-Framed Steel Canopy with Blue Shade Tarp (East Yard, `ax(5)` to `ax(8)`) ---
    // 依據街景照片 media_1792913654156_5ae2f8a0.jpg (10 建興南路42巷) 與 media_1792913662097_0db1612f.jpg (12 建興南路42巷)：
    // 遮雨棚完全位在黃色鵝黃基座白欄杆圍牆裡面，東西向涵蓋 ax(5) 至 ax(8) (~8.0m)，
    // 南側鋼柱與簷口 (canZ2 = 29.80m) 與斜向圍牆保持至少 1.13m～5.0m 安全淨空，範圍只在圍牆裡面，絕不跨出圍牆！
    const canX1 = ax(5) + 0.6, canX2 = ax(8) + 0.1; // -23.18m ~ -15.21m, 寬度 ~7.97m
    const canW = canX2 - canX1;
    const canCx = (canX1 + canX2) / 2;
    const canZ1 = zA + 0.55, canZ2 = 29.80; // canZ2 < 圍牆 (X=-15.21時圍牆Z=30.93m，X=-23.18時圍牆Z=34.80m)
    const canD = canZ2 - canZ1; // 2.55m
    const canCz = (canZ1 + canZ2) / 2;
    const canH = 3.55;

    // 8 根翠綠色方鋼構立柱 (Green Steel H-Columns) 與縱橫向鋼圈樑
    const nCanBays = 3;
    for (let i = 0; i <= nCanBays; i++) {
      const cx = canX1 + (i / nCanBays) * canW;
      addBox(g, 0.16, canH, 0.16, greenSteelMat, cx, canH / 2, canZ1);
      addBox(g, 0.16, canH, 0.16, greenSteelMat, cx, canH / 2, canZ2);
      addBox(g, 0.14, 0.22, canD, greenSteelMat, cx, canH, canCz);
    }
    addBox(g, canW, 0.22, 0.14, greenSteelMat, canCx, canH, canZ1);
    addBox(g, canW, 0.22, 0.14, greenSteelMat, canCx, canH, canZ2);
    // 湖水藍/土耳其藍弧面防雨遮陽篷頂 (Turquoise/Blue Shade Tarp Canopy Roof)
    addBox(g, canW + 0.15, 0.12, canD + 0.15, blueTarpMat, canCx, canH + 0.12, canCz);
    // 篷頂中央微拱加強橫肋
    addBox(g, canW, 0.08, 0.08, greenSteelMat, canCx, canH + 0.19, canCz);
  }

  g.traverse(o => { if (o.isMesh) o.userData.landmarkId = 'new-building'; });
  layerGroups.buildings.add(g);
  clickableGroups.push(g);
  landmarkGroupMap.set('new-building', g);
}

// ---- 08 PU環形運動場, 09 籃球/排球場, 10 司令台 (`sports` layer — 100% Inside Rear Wall with Wide Campus Lawn Buffer Zone) ----
{
  // 08 Sports Track (`PU環形運動場` — 依據 135014.jpg、135021.jpg、135221.jpg 實景精細建模：
  // 6 跑道紅 PU、白色標線、外環平整水泥通學步道、內場草皮、跳遠專用紅橡膠助跑道、木質起跳板、長條跳遠沙坑、螢光橘色交通錐與排水溝格柵)
  const tg = new THREE.Group();
  tg.userData = { landmarkId: 'sports-track' };
  const cx = X(288), cz = Z(248), rx = 64 * S, straight = 128 * S;
  const makeStadiumShape = r => {
    const s = new THREE.Shape(), hs = straight / 2;
    s.moveTo(-r, -hs); s.lineTo(-r, hs);
    s.absarc(0, hs, r, Math.PI, 0, true);
    s.lineTo(r, -hs);
    s.absarc(0, -hs, r, 0, Math.PI, true);
    return s;
  };

  // 1) 跑道外環校園水泥通學人行步道 (實景照片 20261110_135221.jpg：外圍平整淺灰水泥休閒與通學步道，寬約 2.6m)
  const outerWalkwayMat = new THREE.MeshStandardMaterial({ color: 0xdcd8d0, roughness: 0.85, side: THREE.DoubleSide });
  const outerWalkwayMesh = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(rx + 3.8), 48),
    outerWalkwayMat
  );
  outerWalkwayMesh.rotation.x = -Math.PI / 2;
  outerWalkwayMesh.position.set(cx, 0.055, cz);
  outerWalkwayMesh.receiveShadow = true;
  tg.add(outerWalkwayMesh);

  // 2) 草地緩衝區過渡帶
  const lawnTransitionMesh = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(rx + 1.2), 48),
    new THREE.MeshStandardMaterial({ color: 0x679e58, roughness: 0.90, side: THREE.DoubleSide })
  );
  lawnTransitionMesh.rotation.x = -Math.PI / 2; lawnTransitionMesh.position.set(cx, 0.065, cz); lawnTransitionMesh.receiveShadow = true;
  tg.add(lawnTransitionMesh);

  // 3) 白色水泥路緣石 (跑道外緣)
  const outerCurbMesh = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(rx + 0.35), 48),
    new THREE.MeshStandardMaterial({ color: 0xdad6ca, roughness: 0.78, side: THREE.DoubleSide })
  );
  outerCurbMesh.rotation.x = -Math.PI / 2; outerCurbMesh.position.set(cx, 0.08, cz); outerCurbMesh.receiveShadow = true;
  tg.add(outerCurbMesh);

  // 4) 紅色 PU 跑道 (6 道)
  const trackMesh = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(rx), 48),
    new THREE.MeshStandardMaterial({ color: 0xc85a40, roughness: 0.78, side: THREE.DoubleSide })
  );
  trackMesh.rotation.x = -Math.PI / 2; trackMesh.position.set(cx, 0.10, cz); trackMesh.receiveShadow = true;
  tg.add(trackMesh);

  // 5) 白色分道線 (6 條標準田徑分道)
  for (let l = 1; l <= 5; l++) {
    const pts = makeStadiumShape(rx - l * 1.15).getPoints(80).map(p => new THREE.Vector3(cx + p.x, 0.13, cz - p.y));
    tg.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0xf5f5f0, transparent: true, opacity: 0.72 })));
  }

  // 6) 跑道內側水泥緣石與金屬排水溝蓋格柵 (照片 20261110_135021.jpg)
  const innerCurbR = rx - 6.95;
  const innerCurbMesh = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(innerCurbR + 0.18), 48),
    new THREE.MeshStandardMaterial({ color: 0xd2cebe, roughness: 0.78, side: THREE.DoubleSide })
  );
  innerCurbMesh.rotation.x = -Math.PI / 2; innerCurbMesh.position.set(cx, 0.12, cz); innerCurbMesh.receiveShadow = true;
  tg.add(innerCurbMesh);

  // 西側直線跑道內側連續排水溝金屬格柵
  const grateMat = new THREE.MeshStandardMaterial({ color: 0x3a4248, roughness: 0.6, metalness: 0.65 });
  const straightHs = straight / 2;
  const nGrates = 24;
  for (let gIdx = 0; gIdx < nGrates; gIdx++) {
    const gz = cz - straightHs + 1.2 + gIdx * ((straight - 2.4) / nGrates);
    addBox(tg, 0.28, 0.02, 1.45, grateMat, cx - innerCurbR + 0.08, 0.125, gz, false);
  }

  // 7) 內場真草皮 (照片 20261110_135014.jpg 翠綠天然草坪，無縫銜接至內緣石)
  const innerGrass = new THREE.Mesh(
    new THREE.ShapeGeometry(makeStadiumShape(innerCurbR - 0.10), 44),
    new THREE.MeshStandardMaterial({ color: 0x549b42, roughness: 0.88, side: THREE.DoubleSide })
  );
  innerGrass.rotation.x = -Math.PI / 2; innerGrass.position.set(cx, 0.14, cz); innerGrass.receiveShadow = true;
  tg.add(innerGrass);

  // =========================================================================
  // 8) 實景 1:1 還原：內場跳遠跑道、木質起跳板、長條沙坑與螢光橘警示錐 (照片 135014.jpg & 135021.jpg)
  // =========================================================================
  const ljRunwayW = 1.25, ljRunwayL = 30.0;
  const ljRunwayX = cx - innerCurbR + 3.2; // 位於西側直線內場草坪內側約 3.2m 處
  const ljRunwayCz = cz - 2.0;             // 助跑段中心偏北
  const longJumpRunwayMat = new THREE.MeshStandardMaterial({ color: 0xbd4736, roughness: 0.82 });
  const takeoffBoardMat = new THREE.MeshStandardMaterial({ color: 0xfaf8f2, roughness: 0.55 });
  const sandPitMat = new THREE.MeshStandardMaterial({ color: 0xd6b77e, roughness: 0.96 });
  const curbConcreteMat = new THREE.MeshStandardMaterial({ color: 0xd8d4cb, roughness: 0.75 });

  // (a) 紅色合成橡膠跳遠助跑道 (長 30m，寬 1.25m)
  addBox(tg, ljRunwayW, 0.035, ljRunwayL, longJumpRunwayMat, ljRunwayX, 0.155, ljRunwayCz);
  // 助跑道兩側白色 5cm 邊線
  addBox(tg, 0.05, 0.038, ljRunwayL, lineWhiteMat, ljRunwayX - ljRunwayW / 2 + 0.025, 0.158, ljRunwayCz, false);
  addBox(tg, 0.05, 0.038, ljRunwayL, lineWhiteMat, ljRunwayX + ljRunwayW / 2 - 0.025, 0.158, ljRunwayCz, false);

  // (b) 白色標準木質起跳板 (Takeoff Board) + 黑色橡皮泥犯規顯示板
  const takeoffZ = ljRunwayCz + ljRunwayL / 2 + 0.12;
  addBox(tg, ljRunwayW, 0.045, 0.22, takeoffBoardMat, ljRunwayX, 0.165, takeoffZ);
  addBox(tg, ljRunwayW, 0.048, 0.08, mats.darkMetal, ljRunwayX, 0.166, takeoffZ + 0.10); // 犯規橡皮泥板

  // (c) 長條跳遠沙坑 (Sand Pit — 長 7.5m，寬 3.2m，金屬/水泥圓角邊框)
  const pitW = 3.2, pitL = 7.5;
  const pitZ = takeoffZ + 0.15 + pitL / 2;
  // 外圍水泥圓角包邊緣石
  addBox(tg, pitW + 0.36, 0.08, pitL + 0.36, curbConcreteMat, ljRunwayX, 0.17, pitZ);
  // 金黃色顆粒跳遠專用沙坑表面
  addBox(tg, pitW, 0.075, pitL, sandPitMat, ljRunwayX, 0.175, pitZ);

  // (d) 跑道邊 4 頂螢光橘色安全警示錐 (Traffic Cones per Photo 135021.jpg)
  const coneOrangeMat = new THREE.MeshStandardMaterial({ color: 0xff4d00, roughness: 0.45 });
  const coneWhiteMat  = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35 });
  const coneBaseMat   = new THREE.MeshStandardMaterial({ color: 0x1f2326, roughness: 0.85 });
  const coneSpacing = 7.2;
  for (let c = 0; c < 4; c++) {
    const kz = ljRunwayCz - 10.5 + c * coneSpacing;
    const kx = ljRunwayX + ljRunwayW / 2 + 0.45; // 排列於助跑道東側邊緣
    // 黑色防滑橡膠方形底座
    addBox(tg, 0.38, 0.035, 0.38, coneBaseMat, kx, 0.155, kz);
    // 螢光橘色錐身
    addMesh(tg, new THREE.ConeGeometry(0.14, 0.65, 14), coneOrangeMat, kx, 0.48, kz);
    // 中央反光白色環帶
    addMesh(tg, new THREE.CylinderGeometry(0.082, 0.105, 0.15, 14), coneWhiteMat, kx, 0.45, kz);
  }

  // 9) 跑道外圍校園草地緩衝區休閒長椅
  const lawnBenchCoords = [
    [X(232), Z(412), -0.38], [X(282), Z(408), -0.38], [X(332), Z(392), -0.38],
    [X(142), Z(355), 0.88],  [X(172), Z(395), 0.88],
    [X(78),  Z(155), Math.PI / 2], [X(78), Z(235), Math.PI / 2]
  ];
  lawnBenchCoords.forEach(([bx, bz, rotY]) => {
    const bGrp = new THREE.Group();
    bGrp.position.set(bx, 0, bz);
    bGrp.rotation.y = rotY;
    addBox(bGrp, 2.2, 0.08, 1.1, mats.slab, 0, 0.05, 0, false);
    addBox(bGrp, 1.8, 0.10, 0.52, mats.wood, 0, 0.46, 0);
    addBox(bGrp, 1.8, 0.42, 0.08, mats.wood, 0, 0.72, -0.22);
    addBox(bGrp, 0.12, 0.44, 0.48, mats.darkMetal, -0.72, 0.22, 0);
    addBox(bGrp, 0.12, 0.44, 0.48, mats.darkMetal, 0.72, 0.22, 0);
    tg.add(bGrp);
  });

  tg.traverse(o => { if (o.isMesh) o.userData.landmarkId = 'sports-track'; });
  layerGroups.sports.add(tg);
  clickableGroups.push(tg);
  landmarkGroupMap.set('sports-track', tg);

  // 09 Ball Courts (`戶外籃球場與排球場` — 依據實景相片 135444.jpg、135447.jpg、135716.jpg、135708.jpg 1:1 準確建模：
  // 鮮豔藍色烤漆方管鋼構球架、防撞藍色軟墊、45度斜拉支架、透明強化壓克力/鋼化玻璃籃板、亮橘金屬防撞籃框與編織網、
  // 3.6m 高挑綠色防護菱形金屬網圍網、南側與西側圍網攀附綠色常綠藤蔓、場邊 3 階金屬條狀看台座椅與 4 座高桿球場投光照明燈塔)
  const bg = new THREE.Group();
  bg.userData = { landmarkId: 'ball-courts' };

  // 1) 排球場 (北側)
  const vx = X((102 + 184) / 2), vz = Z((112 + 165) / 2), vw = (184 - 102) * S, vd = (165 - 112) * S;
  addBox(bg, vw, 0.14, vd, new THREE.MeshStandardMaterial({ color: 0x8fa194, roughness: 0.80 }), vx, 0.08, vz, false);
  addBox(bg, vw - 1.8, 0.15, vd - 1.8, new THREE.MeshStandardMaterial({ color: 0x3b7a9c, roughness: 0.76 }), vx, 0.09, vz, false);
  // 排球場白色邊界線與攻擊線
  addBox(bg, vw - 1.8, 0.16, 0.12, lineWhiteMat, vx, 0.10, vz - (vd - 1.8) / 2, false);
  addBox(bg, vw - 1.8, 0.16, 0.12, lineWhiteMat, vx, 0.10, vz + (vd - 1.8) / 2, false);
  addBox(bg, 0.12, 0.16, vd - 1.8, lineWhiteMat, vx - (vw - 1.8) / 2, 0.10, vz, false);
  addBox(bg, 0.12, 0.16, vd - 1.8, lineWhiteMat, vx + (vw - 1.8) / 2, 0.10, vz, false);
  for (const side of [-1, 1]) {
    addMesh(bg, new THREE.CylinderGeometry(0.07, 0.07, 2.45, 8), mats.darkMetal, vx, 1.22, vz + side * (vd * 0.42));
  }
  addBox(bg, 0.08, 0.95, vd * 0.82, new THREE.MeshStandardMaterial({ color: 0xf4f4ee, transparent: true, opacity: 0.78, depthWrite: false }), vx, 1.92, vz);
  addBox(bg, 0.10, 0.08, vd * 0.84, lineWhiteMat, vx, 2.40, vz);

  // 2) 雙面戶外標準籃球場 (實景相片 135716.jpg & 135708.jpg 全面昇級)
  const bx = X((112 + 172) / 2), bz = Z((178 + 288) / 2), bw = (172 - 112) * S, bd = (288 - 178) * S;
  const courtApronMat = new THREE.MeshStandardMaterial({ color: 0xb4543e, roughness: 0.78 }); // 陶紅外圍緩衝區
  const courtDarkGreenMat = new THREE.MeshStandardMaterial({ color: 0x367a58, roughness: 0.76 }); // 墨綠主場區
  const courtLightGreenMat = new THREE.MeshStandardMaterial({ color: 0x48946e, roughness: 0.75 }); // 亮綠三分線外區
  const courtKeyMat = new THREE.MeshStandardMaterial({ color: 0xb84e38, roughness: 0.75 }); // 陶紅禁區油漆區
  const hoopBlueMat = new THREE.MeshStandardMaterial({ color: 0x1d4ed8, roughness: 0.38, metalness: 0.55 }); // 實景照片鮮豔深藍色烤漆方管
  const hoopPadMat  = new THREE.MeshStandardMaterial({ color: 0x1e40af, roughness: 0.65 }); // 實景照片立柱防撞加厚藍色護墊
  const hoopOrangeMat = new THREE.MeshStandardMaterial({ color: 0xe8562a, roughness: 0.40, metalness: 0.45 }); // 橘紅金屬籃框
  const glassBackboardMat = new THREE.MeshStandardMaterial({ color: 0xd6f0fc, transparent: true, opacity: 0.68, roughness: 0.12, metalness: 0.1, depthWrite: false }); // 實景透明鋼化玻璃/壓克力背板
  const netMat = new THREE.MeshStandardMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, depthWrite: false }); // 白色編織籃網

  // (a) 籃球場鋪面 (陶紅外圍跑道級壓克力 + 墨綠與亮綠球場)
  addBox(bg, bw + 2.4, 0.12, bd + 2.4, courtApronMat, bx, 0.06, bz, false);
  addBox(bg, bw, 0.14, bd, courtDarkGreenMat, bx, 0.07, bz, false);
  addBox(bg, bw - 2.0, 0.15, bd - 2.0, courtLightGreenMat, bx, 0.075, bz, false);

  // (b) 白色全場標準邊線、中央分隔線與跳球圈
  addBox(bg, bw - 2.0, 0.165, 0.12, lineWhiteMat, bx, 0.08, bz - (bd - 2.0) / 2, false);
  addBox(bg, bw - 2.0, 0.165, 0.12, lineWhiteMat, bx, 0.08, bz + (bd - 2.0) / 2, false);
  addBox(bg, 0.12, 0.165, bd - 2.0, lineWhiteMat, bx - (bw - 2.0) / 2, 0.08, bz, false);
  addBox(bg, 0.12, 0.165, bd - 2.0, lineWhiteMat, bx + (bw - 2.0) / 2, 0.08, bz, false);
  // 中線與中圈 (1.8m 半徑)
  addBox(bg, bw - 2.0, 0.168, 0.12, lineWhiteMat, bx, 0.082, bz, false);
  addMesh(bg, new THREE.CylinderGeometry(2.1, 2.1, 0.168, 28), courtKeyMat, bx, 0.082, bz, false, true);
  const centerCircleLine = addMesh(bg, new THREE.RingGeometry(1.75, 1.85, 28), lineWhiteMat, bx, 0.084, bz);
  centerCircleLine.rotation.x = -Math.PI / 2;

  // (c) 南北雙向籃球架 (實景照片 135716.jpg 鮮豔藍色立柱、藍色防撞墊、45度支撐臂、透明鋼化壓克力籃板、白色內框、橘紅籃框與白網)
  for (const dir of [-1, 1]) {
    const endZ = bz + dir * (bd / 2 - 0.95);
    // 陶紅禁區 (Restricted Area Key)
    addBox(bg, 4.2, 0.165, 5.8, courtKeyMat, bx, 0.082, endZ - dir * 2.9, false);
    addBox(bg, 4.2, 0.168, 0.10, lineWhiteMat, bx, 0.084, endZ - dir * 5.8, false); // 罰球線
    // 罰球半圓圈 (半徑 1.8m)
    const ftRing = addMesh(bg, new THREE.RingGeometry(1.75, 1.85, 24), lineWhiteMat, bx, 0.085, endZ - dir * 5.8);
    ftRing.rotation.x = -Math.PI / 2;

    // 籃架基座立柱 (深藍方管鋼梁，高 3.35m)
    addBox(bg, 0.22, 3.35, 0.22, hoopBlueMat, bx, 1.68, endZ);
    // 下端深藍加厚安全防撞泡棉套 (高 1.35m)
    addBox(bg, 0.38, 1.35, 0.38, hoopPadMat, bx, 0.68, endZ);
    // 45度斜向後拉地錨固定支架 (向外拉向球場外緣)
    const braceAng = dir * 0.52;
    const braceLen = 2.4;
    const brace = addBox(bg, 0.10, 0.10, braceLen, hoopBlueMat, bx, 1.15, endZ + dir * 0.95);
    brace.rotation.x = braceAng;

    // 鵝頸延伸主懸臂 (向前上方挑出 1.25m)
    addBox(bg, 0.16, 0.16, 1.25, hoopBlueMat, bx, 3.25, endZ - dir * 0.55);
    // 雙向 Y 形籃板背面支撐副斜撐
    for (const sx of [-0.45, 0.45]) {
      const arm = addBox(bg, 0.05, 0.05, 0.95, hoopBlueMat, bx + sx, 3.20, endZ - dir * 0.65);
      arm.rotation.y = -dir * (sx > 0 ? 0.38 : -0.38);
    }

    // 透明鋼化玻璃/壓克力籃板 (1.80m x 1.05m，透明帶淡藍反光，depthWrite: false 防止深度遮擋閃爍)
    const boardZ = endZ - dir * 1.18;
    addBox(bg, 1.82, 1.08, 0.045, glassBackboardMat, bx, 3.05, boardZ);
    // 籃板白色邊框與中央目標小矩形 (0.59m x 0.45m)
    addBox(bg, 1.82, 0.05, 0.05, lineWhiteMat, bx, 3.58, boardZ, false);
    addBox(bg, 1.82, 0.05, 0.05, lineWhiteMat, bx, 2.52, boardZ, false);
    addBox(bg, 0.05, 1.08, 0.05, lineWhiteMat, bx - 0.90, 3.05, boardZ, false);
    addBox(bg, 0.05, 1.08, 0.05, lineWhiteMat, bx + 0.90, 3.05, boardZ, false);
    addBox(bg, 0.59, 0.04, 0.055, lineWhiteMat, bx, 2.82, boardZ - dir * 0.01, false);
    addBox(bg, 0.59, 0.04, 0.055, lineWhiteMat, bx, 3.27, boardZ - dir * 0.01, false);
    addBox(bg, 0.04, 0.45, 0.055, lineWhiteMat, bx - 0.29, 3.05, boardZ - dir * 0.01, false);
    addBox(bg, 0.04, 0.45, 0.055, lineWhiteMat, bx + 0.29, 3.05, boardZ - dir * 0.01, false);

    // 亮橘金屬籃框 (直徑 0.45m，高 3.05m) + 彈簧減震箱
    const rimZ = boardZ - dir * 0.38;
    addBox(bg, 0.14, 0.10, 0.18, hoopOrangeMat, bx, 3.05, boardZ - dir * 0.09);
    const rim = addMesh(bg, new THREE.TorusGeometry(0.23, 0.022, 10, 24), hoopOrangeMat, bx, 3.05, rimZ);
    rim.rotation.x = Math.PI / 2;

    // 白色編織尼龍籃網 (倒圓錐形網袋)
    addMesh(bg, new THREE.CylinderGeometry(0.22, 0.12, 0.42, 12, 1, true), netMat, bx, 2.82, rimZ);
  }

  // =========================================================================
  // 3) 實景 1:1 還原：3.6m 高挑綠色球場防護金屬網圍欄 (照片 135444.jpg & 135708.jpg)
  // =========================================================================
  const fenceH = 3.65;
  const fencePostMat = new THREE.MeshStandardMaterial({ color: 0x2b4c3b, roughness: 0.55, metalness: 0.4 });
  const chainLinkMat = new THREE.MeshStandardMaterial({ color: 0x365846, transparent: true, opacity: 0.48, roughness: 0.6, depthWrite: false });

  // 沿球場外緣 (東南西北四面) 構築立柱與金屬菱形網
  const fenceMinX = bx - bw / 2 - 1.2, fenceMaxX = bx + bw / 2 + 1.2;
  const fenceMinZ = bz - bd / 2 - 1.2, fenceMaxZ = bz + bd / 2 + 1.2;
  const fenceW = fenceMaxX - fenceMinX, fenceD = fenceMaxZ - fenceMinZ;

  // 四周金屬網面
  // 北網
  addBox(bg, fenceW, fenceH, 0.04, chainLinkMat, bx, fenceH / 2 + 0.08, fenceMinZ);
  addBox(bg, fenceW, 0.05, 0.05, fencePostMat, bx, fenceH + 0.08, fenceMinZ);
  addBox(bg, fenceW, 0.05, 0.05, fencePostMat, bx, fenceH / 2 + 0.08, fenceMinZ);
  // 南網
  addBox(bg, fenceW, fenceH, 0.04, chainLinkMat, bx, fenceH / 2 + 0.08, fenceMaxZ);
  addBox(bg, fenceW, 0.05, 0.05, fencePostMat, bx, fenceH + 0.08, fenceMaxZ);
  addBox(bg, fenceW, 0.05, 0.05, fencePostMat, bx, fenceH / 2 + 0.08, fenceMaxZ);
  // 西網 (靠建興南路圍牆側)
  addBox(bg, 0.04, fenceH, fenceD, chainLinkMat, fenceMinX, fenceH / 2 + 0.08, bz);
  addBox(bg, 0.05, 0.05, fenceD, fencePostMat, fenceMinX, fenceH + 0.08, bz);
  addBox(bg, 0.05, 0.05, fenceD, fencePostMat, fenceMinX, fenceH / 2 + 0.08, bz);
  // 東網 (靠司令台/跑道側，留有出入口開放通道)
  addBox(bg, 0.04, fenceH, fenceD * 0.42, chainLinkMat, fenceMaxX, fenceH / 2 + 0.08, bz - fenceD * 0.28);
  addBox(bg, 0.04, fenceH, fenceD * 0.42, chainLinkMat, fenceMaxX, fenceH / 2 + 0.08, bz + fenceD * 0.28);
  addBox(bg, 0.05, 0.05, fenceD * 0.42, fencePostMat, fenceMaxX, fenceH + 0.08, bz - fenceD * 0.28);
  addBox(bg, 0.05, 0.05, fenceD * 0.42, fencePostMat, fenceMaxX, fenceH + 0.08, bz + fenceD * 0.28);

  // 四邊立柱 (每隔 3.8m 一根圓柱)
  for (let px = fenceMinX; px <= fenceMaxX + 0.1; px += 3.8) {
    addMesh(bg, new THREE.CylinderGeometry(0.05, 0.05, fenceH, 8), fencePostMat, px, fenceH / 2 + 0.08, fenceMinZ);
    addMesh(bg, new THREE.CylinderGeometry(0.05, 0.05, fenceH, 8), fencePostMat, px, fenceH / 2 + 0.08, fenceMaxZ);
  }
  for (let pz = fenceMinZ; pz <= fenceMaxZ + 0.1; pz += 3.8) {
    addMesh(bg, new THREE.CylinderGeometry(0.05, 0.05, fenceH, 8), fencePostMat, fenceMinX, fenceH / 2 + 0.08, pz);
    if (Math.abs(pz - bz) > 4.5) {
      addMesh(bg, new THREE.CylinderGeometry(0.05, 0.05, fenceH, 8), fencePostMat, fenceMaxX, fenceH / 2 + 0.08, pz);
    }
  }

  // =========================================================================
  // 4) 實景 1:1 還原：圍網攀附茂盛常綠藤蔓植物 (照片 135708.jpg)
  // =========================================================================
  const vineGreen1 = mats.hedge || new THREE.MeshStandardMaterial({ color: 0x3d7036, roughness: 0.85 });
  const vineGreen2 = new THREE.MeshStandardMaterial({ color: 0x4e8544, roughness: 0.82 });
  // 南側圍網攀藤叢
  for (let vx = fenceMinX + 1.5; vx <= fenceMaxX - 1.5; vx += 2.2) {
    const vH = 1.2 + ((vx * 13) % 1.6);
    addBox(bg, 1.95, vH, 0.28, (Math.floor(vx) % 2 === 0) ? vineGreen1 : vineGreen2, vx, vH / 2 + 0.08, fenceMaxZ);
  }
  // 西側圍網攀藤叢
  for (let vz = fenceMinZ + 2.0; vz <= fenceMaxZ - 2.0; vz += 2.6) {
    const vH = 1.4 + ((vz * 17) % 1.5);
    addBox(bg, 0.28, vH, 2.2, (Math.floor(vz) % 2 === 0) ? vineGreen2 : vineGreen1, fenceMinX, vH / 2 + 0.08, vz);
  }

  // =========================================================================
  // 5) 實景 1:1 還原：場邊 3 階金屬/水泥條狀看台座椅 (照片 135444.jpg & 135716.jpg)
  // =========================================================================
  const bleacherSeatMat = new THREE.MeshStandardMaterial({ color: 0xd8d6cc, roughness: 0.65 });
  const bleacherFrameMat = new THREE.MeshStandardMaterial({ color: 0x5a6368, roughness: 0.5, metalness: 0.6 });
  const bleacherConfigs = [
    { bx: fenceMaxX + 1.8, bz: bz - 12.0, len: 8.5 },
    { bx: fenceMaxX + 1.8, bz: bz + 12.0, len: 8.5 }
  ];
  bleacherConfigs.forEach(({ bx: seatX, bz: seatZ, len }) => {
    // 3 階踏板與座椅
    for (let tier = 0; tier < 3; tier++) {
      const stepH = 0.38 + tier * 0.36;
      const stepD = 0.42;
      const offX = tier * 0.48;
      // 水泥/金屬支撐立架
      const nFrames = Math.floor(len / 1.8);
      for (let f = 0; f <= nFrames; f++) {
        const fz = seatZ - len / 2 + f * 1.8;
        addBox(bg, 0.08, stepH, 0.08, bleacherFrameMat, seatX + offX, stepH / 2, fz);
      }
      // 條狀座板
      addBox(bg, stepD, 0.06, len, bleacherSeatMat, seatX + offX, stepH, seatZ);
    }
  });

  // =========================================================================
  // 6) 實景 1:1 還原：4 座高桿球場夜間投光照明水銀燈塔 (照片 135444.jpg & 135447.jpg)
  // =========================================================================
  const poleMetalMat = new THREE.MeshStandardMaterial({ color: 0x8a949c, roughness: 0.38, metalness: 0.65 });
  const floodlightHousingMat = new THREE.MeshStandardMaterial({ color: 0x364047, roughness: 0.4 });
  const floodlightFaceMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const floodlightCorners = [
    [fenceMinX - 0.8, fenceMinZ - 0.8, 0.42, 0.42],
    [fenceMaxX + 0.8, fenceMinZ - 0.8, -0.42, 0.42],
    [fenceMinX - 0.8, fenceMaxZ + 0.8, 0.42, -0.42],
    [fenceMaxX + 0.8, fenceMaxZ + 0.8, -0.42, -0.42]
  ];
  floodlightCorners.forEach(([fx, fz, rotY, tiltX]) => {
    const fPoleH = 8.8;
    // 鍍鋅鋼管主桿 (高 8.8m)
    addMesh(bg, new THREE.CylinderGeometry(0.09, 0.13, fPoleH, 12), poleMetalMat, fx, fPoleH / 2, fz);
    // 桿頂 T 形水平燈架 (寬 1.8m)
    addBox(bg, 1.8, 0.08, 0.08, poleMetalMat, fx, fPoleH + 0.04, fz);
    // 2 盞高亮度大型矩形投光燈 (傾斜投向球場中心)
    for (const lx of [-0.65, 0.65]) {
      const lampGrp = new THREE.Group();
      lampGrp.position.set(fx + lx, fPoleH - 0.15, fz);
      lampGrp.rotation.x = tiltX;
      lampGrp.rotation.y = rotY;
      addBox(lampGrp, 0.46, 0.32, 0.18, floodlightHousingMat, 0, 0, 0);
      addBox(lampGrp, 0.42, 0.28, 0.02, floodlightFaceMat, 0, 0, -0.10);
      bg.add(lampGrp);
    }
  });

  bg.traverse(o => { if (o.isMesh) o.userData.landmarkId = 'ball-courts'; });
  layerGroups.sports.add(bg);
  clickableGroups.push(bg);
  landmarkGroupMap.set('ball-courts', bg);

// Helper: Create authentic sign texture for North Wall of Command Stage ("復興國小籃球場使用規則")
function makeBasketballRulesSignTexture() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 384;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, 512, 384);
  ctx.strokeStyle = '#c82828';
  ctx.lineWidth = 6;
  ctx.strokeRect(8, 8, 496, 368);

  ctx.textAlign = 'center';
  ctx.fillStyle = '#c82828';
  ctx.font = 'bold 30px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('復興國小籃球場使用規則', 256, 48);

  ctx.textAlign = 'left';
  ctx.fillStyle = '#1e242b';
  ctx.font = 'bold 15px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  const rules = [
    '一、開放時間：依學校課外活動及開放辦法規定。',
    '二、進入球場請穿著運動鞋，嚴禁穿著高跟鞋或釘鞋。',
    '三、愛惜場地公物與籃球架設施，請勿攀爬籃網及籃框。',
    '四、球場內全面禁菸、禁止嚼食檳榔及攜帶寵物進入。',
    '五、使用完畢請隨手將垃圾帶走，共同維護校園環境整潔。',
    '六、若有損壞公物行為，照價賠償並依相關規定究辦。'
  ];
  rules.forEach((r, idx) => {
    ctx.fillText(r, 26, 92 + idx * 38);
  });

  ctx.textAlign = 'right';
  ctx.fillStyle = '#c82828';
  ctx.font = 'bold 17px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
  ctx.fillText('屏東市復興國民小學 敬啟', 484, 345);

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

// =========================================================================
// Helper: 1:1 中華民國國旗 (Flag of the Republic of China) 精確幾何材質產生器
// 依法規《中華民國國徽國旗法》第三、四條規範：
// 1. 旗面橫縱比為 3:2 (1200 x 800)
// 2. 青天面積為全旗四分之一 (長 600、寬 400)，位於左上方旗桿側
// 3. 白日十二道光芒頂角各為 30 度，呈正向北南西東及均勻排列
// 4. 白日與光芒間留一青圈，寬度等於白日體直徑十五分之一
// 5. 靠旗桿邊具備防撕裂白色帆布旗帶與金屬扣環細節
// =========================================================================
function makeROCFlagTexture() {
  const c = document.createElement('canvas');
  c.width = 1200;
  c.height = 800;
  const ctx = c.getContext('2d');

  // 1. 紅地 (滿地紅 - 正式標準色 #de2910)
  ctx.fillStyle = '#de2910';
  ctx.fillRect(0, 0, 1200, 800);

  // 2. 青天 (長方形青天面積為全旗四分之一，長 600、寬 400，正式標準海軍藍 #000095)
  ctx.fillStyle = '#000095';
  ctx.fillRect(0, 0, 600, 400);

  // 3. 白日十二道光芒 ({12/5} 幾何正星形多邊形，頂點位於外接圓半徑 150，頂角精確為 30 度)
  const cx = 300, cy = 200;
  const rRay = 150;
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  for (let i = 0; i <= 12; i++) {
    const step = (i * 5) % 12;
    const angle = -Math.PI / 2 + step * (2 * Math.PI / 12);
    const x = cx + rRay * Math.cos(angle);
    const y = cy + rRay * Math.sin(angle);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fill();

  // 4. 青圈 (直徑 150 的十五分之一為 10，青圈外半徑為 75 + 10 = 85)
  ctx.fillStyle = '#000095';
  ctx.beginPath();
  ctx.arc(cx, cy, 85, 0, Math.PI * 2);
  ctx.fill();

  // 5. 白日體圓 (半徑為 75 之純白正圓)
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(cx, cy, 75, 0, Math.PI * 2);
  ctx.fill();

  // 6. 旗桿側 (左側 x = 0..14) 白色加強旗帶 (Hoist Header) 與黃銅扣環 (Grommets)
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, 14, 800);
  ctx.fillStyle = '#cbd5e1';
  ctx.fillRect(13, 0, 1, 800); // 邊緣縫線細節

  // 上下金屬穿孔扣環
  [[7, 28], [7, 772]].forEach(([gx, gy]) => {
    ctx.fillStyle = '#b45309';
    ctx.beginPath(); ctx.arc(gx, gy, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fef3c7';
    ctx.beginPath(); ctx.arc(gx, gy, 2, 0, Math.PI * 2); ctx.fill();
  });

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

  // 10 Command Stage & Flagpoles (`司令台` 雙層洗石子挑簷、半月形洗石子拱額、動物彩繪磁磚台座壁畫、「復興國小」雙幅童趣舞台布幕與三階升旗台)
  const sg = new THREE.Group();
  sg.userData = { landmarkId: 'command-stage' };
  const sx = X(192), sz = Z(252);

  // 實景照片萃取之「復興國小」雙幅舞台背景布幕與台座白鷺鷥彩繪磁磚壁畫 Base64 貼圖
  window.STAGE_CURTAIN_DATA = "data:image/jpeg;base64,";
  window.STAGE_MURAL_DATA   = "data:image/jpeg;base64,";

  function makeCommandStageCurtainTexture() {
    const c = document.createElement('canvas');
    c.width = 512; c.height = 340;
    const ctx = c.getContext('2d');
    // 1. 雙幅米白帆布底色與折痕陰影 (Procedural Fallback)
    ctx.fillStyle = '#EAE4DC';
    ctx.fillRect(0, 0, 512, 340);
    // 左右雙幅中央垂直拼接縫
    ctx.fillStyle = '#C5BDB2';
    ctx.fillRect(253, 0, 6, 340);
    ctx.strokeStyle = 'rgba(160, 150, 138, 0.35)';
    ctx.lineWidth = 2;
    [64, 128, 192, 320, 384, 448].forEach(vx => {
      ctx.beginPath(); ctx.moveTo(vx, 0); ctx.lineTo(vx, 340); ctx.stroke();
    });
    // 2. 頂部綠葉藤蔓花邊與「復興 國小」可愛圓體大字
    ctx.fillStyle = '#8AB868';
    for (let lx = 70; lx <= 440; lx += 22) {
      ctx.beginPath(); ctx.ellipse(lx, 24 + (lx % 16 === 0 ? 6 : 0), 10, 6, 0.3, 0, Math.PI * 2); ctx.fill();
    }
    ctx.textAlign = 'center';
    ctx.font = '900 58px "Noto Sans TC", "Microsoft JhengHei", sans-serif';
    ctx.lineWidth = 7;
    ctx.strokeStyle = '#2B1810';
    ctx.fillStyle = '#D84A28';
    [['復', 118, 72], ['興', 192, 72], ['國', 326, 72], ['小', 396, 72]].forEach(([ch, cx, cy]) => {
      ctx.strokeText(ch, cx, cy);
      ctx.fillText(ch, cx, cy);
    });
    // 3. 底部翠綠草坡、白色蒲公英小花與 6 位歡呼卡通學童
    ctx.fillStyle = '#92B558';
    ctx.beginPath();
    ctx.moveTo(0, 265);
    ctx.quadraticCurveTo(128, 240, 256, 262);
    ctx.quadraticCurveTo(384, 280, 512, 250);
    ctx.lineTo(512, 340);
    ctx.lineTo(0, 340);
    ctx.closePath();
    ctx.fill();
    const kidColors = ['#D63031', '#0984E3', '#6C5CE7', '#E17055', '#00CEC9', '#D63031'];
    [135, 182, 228, 285, 335, 382].forEach((kx, idx) => {
      ctx.fillStyle = '#FAD390';
      ctx.beginPath(); ctx.arc(kx, 258, 13, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#2D3436';
      ctx.beginPath(); ctx.arc(kx, 253, 13, Math.PI, Math.PI * 2); ctx.fill();
      ctx.fillStyle = kidColors[idx];
      ctx.fillRect(kx - 9, 271, 18, 26);
      ctx.fillStyle = '#2D3436';
      ctx.fillRect(kx - 8, 297, 6, 16);
      ctx.fillRect(kx + 2, 297, 6, 16);
    });

    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    if (window.STAGE_CURTAIN_DATA && typeof Image !== 'undefined') {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0, 512, 340);
        tex.needsUpdate = true;
      };
      img.src = window.STAGE_CURTAIN_DATA;
    }
    return tex;
  }

  function makeCommandStageMuralTexture() {
    const c = document.createElement('canvas');
    c.width = 640; c.height = 176;
    const ctx = c.getContext('2d');
    // 1. 淺灰磨石子底板
    ctx.fillStyle = '#9BA0A4';
    ctx.fillRect(0, 0, 640, 176);
    // 左側直排黑色書法題字
    ctx.fillStyle = '#181A1C';
    [35, 68, 102, 135].forEach(vy => {
      ctx.beginPath(); ctx.arc(118, vy, 7, 0, Math.PI * 2); ctx.fill();
    });
    // 2. 中央高低階梯狀藍底白鷺鷥生態彩繪磁磚壁畫
    const stepCols = [
      [132, 14, 65, 148], [197, 46, 72, 116], [269, 74, 138, 88],
      [407, 44, 58, 118], [465, 14, 70, 148]
    ];
    ctx.fillStyle = '#1B3B82';
    stepCols.forEach(([rx, ry, rw, rh]) => ctx.fillRect(rx, ry, rw, rh));
    ctx.fillStyle = '#4A6E3D';
    ctx.fillRect(140, 96, 386, 56);
    // 白鷺鷥剪影
    ctx.fillStyle = '#F5F7FA';
    ctx.beginPath(); ctx.ellipse(230, 92, 18, 26, -0.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(512, 95, 16, 24, 0.2, 0, Math.PI * 2); ctx.fill();

    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    if (window.STAGE_MURAL_DATA && typeof Image !== 'undefined') {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0, 640, 176);
        tex.needsUpdate = true;
      };
      img.src = window.STAGE_MURAL_DATA;
    }
    return tex;
  }

  // Materials Palette based on Authentic Photo (media_1793881139036_522c6b4e.jpg)
  const terrazzoPebbleMat = new THREE.MeshStandardMaterial({ color: 0x544944, roughness: 0.90 }); // 深褐灰洗石子（挑簷、拱額與台座）
  const baseWingStoneMat  = new THREE.MeshStandardMaterial({ color: 0x66625b, roughness: 0.88 }); // 台座兩側灰褐洗石子
  const lightTerrazzoMat  = new THREE.MeshStandardMaterial({ color: 0x9ca0a3, roughness: 0.78 }); // 台座正面中央淺灰磨石子面板
  const platformFloorMat  = new THREE.MeshStandardMaterial({ color: 0xd6d3cb, roughness: 0.75 }); // 舞台磨石子平坦地坪
  const whiteWallMat      = new THREE.MeshStandardMaterial({ color: 0xf5f2ea, roughness: 0.68 }); // 暖米白水泥粉刷壁身与柱身
  const soffitMat         = new THREE.MeshStandardMaterial({ color: 0xf7f5ef, roughness: 0.62 }); // 屋簷與圓弧拱底純白平頂
  const darkTrimMat       = new THREE.MeshStandardMaterial({ color: 0x2e2f32, roughness: 0.75 }); // 黑色/深灰金屬收邊件
  const steelBracketMat   = new THREE.MeshStandardMaterial({ color: 0x7c848c, roughness: 0.50, metalness: 0.48 }); // 斜撐角鋼支架與投光燈架
  const louverSlatMat     = new THREE.MeshStandardMaterial({ color: 0xf2f0e8, roughness: 0.60 }); // 白色直立百葉通風窗葉片
  const speakerMat        = new THREE.MeshStandardMaterial({ color: 0x22252a, roughness: 0.42, metalness: 0.65 }); // 廣播號角喇叭金屬黑
  const columnBaseMat     = new THREE.MeshStandardMaterial({ color: 0x635c54, roughness: 0.88 }); // 柱基與後背牆洗石子腰壁
  const elecBoxGreyMat    = new THREE.MeshStandardMaterial({ color: 0xb8bcc0, roughness: 0.45, metalness: 0.25 }); // 舞台右側淺灰配電箱

  // 1) 司令台主台座 (高 1.10m，寬 10.4m，深 5.6m，面向東方跑道)
  const stageFloorH = 1.10;
  addBox(sg, 5.60, stageFloorH, 10.40, baseWingStoneMat, sx, stageFloorH / 2, sz);
  addBox(sg, 5.45, 0.06, 10.20, platformFloorMat, sx, stageFloorH + 0.03, sz);
  // 台座前緣頂部深色洗石子壓頂邊梁 (Front Edge Coping)
  addBox(sg, 0.28, 0.14, 7.60, terrazzoPebbleMat, sx + 2.72, stageFloorH + 0.02, sz);

  // 2) 台座正面中央：淺灰磨石子底板與高低階梯狀白鷺鷥彩繪磁磚壁畫 (Photo 正面中央 1:1 還原)
  const muralPanelW = 6.20, muralPanelH = 0.98;
  addBox(sg, 0.05, muralPanelH, muralPanelW, lightTerrazzoMat, sx + 2.80, (stageFloorH - 0.06) / 2, sz);
  const muralMat = new THREE.MeshStandardMaterial({ map: makeCommandStageMuralTexture(), roughness: 0.48 });
  const muralMesh = addMesh(sg, new THREE.PlaneGeometry(muralPanelW, muralPanelH), muralMat, sx + 2.835, (stageFloorH - 0.06) / 2, sz, false);
  muralMesh.rotation.y = Math.PI / 2;

  // 3) 南北兩側登台階梯與洗石子側翼護牆 (正面兩側對稱洗石子翼牆)
  [-1, 1].forEach(side => {
    const wz = sz + side * 5.20;
    const stairZ = sz + side * 5.95;
    const wingWallZ = sz + side * 6.72;

    // 正面兩側向外延伸之洗石子翼台 (與台座正面齊平，高 1.10m)
    addBox(sg, 1.85, stageFloorH, 1.52, baseWingStoneMat, sx + 1.88, stageFloorH / 2, sz + side * 5.96);

    // 側向五階登台踏步 (自後側地面 y=0 升至舞台面 y=1.10m)
    for (let st = 0; st < 5; st++) {
      const stepY = (stageFloorH / 5) * (st + 1);
      const stepX = sx - 1.60 + st * 0.42;
      addBox(sg, 0.42, stepY, 1.50, baseWingStoneMat, stepX, stepY / 2, stairZ);
    }

    // 階梯外側洗石子護牆
    addBox(sg, 3.80, stageFloorH + 0.05, 0.26, baseWingStoneMat, sx + 0.90, (stageFloorH + 0.05) / 2, wingWallZ);

    // 舞台南北兩側洗石子矮座腰牆 (高 0.38m，與前柱及後背牆洗石子腰牆齊平！)
    addBox(sg, 4.90, 0.38, 0.32, columnBaseMat, sx - 0.10, stageFloorH + 0.19, sz + side * 3.80);
  });

  // 4) 結構柱身、後背牆、「復興國小」雙幅童趣舞台布幕、兩側百葉窗與右側配電箱
  const wallH = 3.05;
  const colY = stageFloorH + wallH / 2;
  const dadoH = 0.38; // 舞台面上方 0.38m 深灰褐洗石子腰壁/柱座 (自 y=1.10m 至 y=1.48m)

  // 前排兩根複合柱 (下段 1.48m 洗石子方柱座 + 上段暖米白圓潤柱身 + 黑色廣播號角喇叭)
  for (const pz of [sz - 3.80, sz + 3.80]) {
    // 下段：深色洗石子柱座 (自地面 y=0 至 y=1.48m，斷面 0.76m x 0.76m)
    addBox(sg, 0.76, stageFloorH + dadoH, 0.76, columnBaseMat, sx + 2.30, (stageFloorH + dadoH) / 2, pz);
    // 上段：暖米白圓潤柱身 (自 y=1.48m 至 y=4.15m)
    const upperColH = (stageFloorH + wallH) - (stageFloorH + dadoH);
    addBox(sg, 0.64, upperColH, 0.64, whiteWallMat, sx + 2.30, stageFloorH + dadoH + upperColH / 2, pz);
    addMesh(sg, new THREE.CylinderGeometry(0.35, 0.35, upperColH, 20), whiteWallMat, sx + 2.34, stageFloorH + dadoH + upperColH / 2, pz);
  }

  // 後背牆主體 (厚 0.34m，寬 7.92m，高 3.05m)
  addBox(sg, 0.34, wallH, 7.92, whiteWallMat, sx - 2.50, colY, sz);
  // 後背牆底部深色洗石子踢腳腰牆 (高 0.38m，橫跨整個後背牆，還原照片布幕下方深色洗石子底座！)
  addBox(sg, 0.40, dadoH, 7.60, columnBaseMat, sx - 2.46, stageFloorH + dadoH / 2, sz);

  // 【司令台核心背景】：「復興 國小」雙幅童趣學童插畫帆布背景幕 (緊貼洗石子腰牆上方 y = 1.48m ~ 3.60m，寬 4.16m)
  const curtainW = 4.16, curtainH = 2.12;
  const curtainCy = stageFloorH + dadoH + curtainH / 2; // 1.48 + 1.06 = 2.54m
  const curtainMat = new THREE.MeshStandardMaterial({ map: makeCommandStageCurtainTexture(), roughness: 0.62 });
  const curtainMesh = addMesh(sg, new THREE.PlaneGeometry(curtainW, curtainH), curtainMat, sx - 2.31, curtainCy, sz, false);
  curtainMesh.rotation.y = Math.PI / 2;
  // 布幕頂部金屬吊掛橫桿與吊環細節
  addBox(sg, 0.03, 0.03, curtainW + 0.08, steelBracketMat, sx - 2.315, stageFloorH + dadoH + curtainH + 0.015, sz, false);

  // 後背牆左右兩側直立白色百葉通風窗 (位於布幕兩側 lz = sz ± 3.02m，高 2.04m，密集白色水平百葉片)
  for (const lz of [sz - 3.02, sz + 3.02]) {
    const lvW = 0.68, lvH = 2.04;
    const lvCy = stageFloorH + dadoH + lvH / 2;
    // 窗框深色內襯與白色外框
    addBox(sg, 0.36, lvH, lvW, darkTrimMat, sx - 2.49, lvCy, lz);
    addBox(sg, 0.38, lvH + 0.06, 0.05, louverSlatMat, sx - 2.48, lvCy, lz - lvW / 2);
    addBox(sg, 0.38, lvH + 0.06, 0.05, louverSlatMat, sx - 2.48, lvCy, lz + lvW / 2);
    // 22 片密集白色水平百葉片 (照片清晰可見之白色橫百葉)
    for (let sl = 0; sl < 22; sl++) {
      const sly = (stageFloorH + dadoH + 0.06) + sl * ((lvH - 0.10) / 21);
      addBox(sg, 0.39, 0.032, lvW - 0.06, louverSlatMat, sx - 2.47, sly, lz, false);
    }
  }

  // 舞台右側（北側百葉窗前方）淺灰色金屬配電/廣播機櫃 (Photo 右側百葉窗下清晰可見之淺灰方箱！)
  const cabW = 0.52, cabH = 0.78, cabD = 0.34;
  addBox(sg, cabD, cabH, cabW, elecBoxGreyMat, sx - 2.16, stageFloorH + cabH / 2, sz - 2.98);
  addBox(sg, 0.02, 0.14, 0.04, darkTrimMat, sx - 1.98, stageFloorH + cabH * 0.55, sz - 2.78, false); // 電箱門扣把手

  // 5) 南北兩側造型側牆：中柱與兩道直立長橢圓梭形採光鏤空孔 (完全通透可見後方綠樹，無遮擋百葉！)
  function makeOvalWallGeometry() {
    const wallShape = new THREE.Shape();
    wallShape.moveTo(-2.40, 0);
    wallShape.lineTo(2.40, 0);
    wallShape.lineTo(2.40, 2.67);
    wallShape.lineTo(-2.40, 2.67);
    wallShape.closePath();
    [-0.92, 0.92].forEach(hx => {
      const hole = new THREE.Path();
      hole.absellipse(hx, 1.32, 0.34, 0.98, 0, Math.PI * 2, false);
      wallShape.holes.push(hole);
    });
    return new THREE.ExtrudeGeometry(wallShape, { depth: 0.28, bevelEnabled: false });
  }

  const ovalWallGeo = makeOvalWallGeometry();
  [-1, 1].forEach(side => {
    const sideWallMesh = new THREE.Mesh(ovalWallGeo, whiteWallMat);
    sideWallMesh.position.set(sx - 0.10, stageFloorH + dadoH, sz + side * 3.80 - 0.14);
    sideWallMesh.castShadow = true;
    sideWallMesh.receiveShadow = true;
    sg.add(sideWallMesh);
  });

  // 6) 北向山牆外側實景細節（籃球場管理規範告示牌）
  const northExtZ = sz - 3.80 - 0.15;
  const rulesTex = makeBasketballRulesSignTexture();
  const rulesMat = new THREE.MeshStandardMaterial({ map: rulesTex, roughness: 0.45 });
  const rulesMesh = addMesh(sg, new THREE.PlaneGeometry(1.10, 0.85), rulesMat, sx - 0.10, stageFloorH + 1.45, northExtZ - 0.01, false);
  rulesMesh.rotation.y = Math.PI;

  // 7) 【司令台標誌性外觀】雙層深褐灰洗石子挑簷屋頂、中央圓弧拱簷、半月形洗石子內凹額牆、中央梯形短柱與頂部斜山牆翼板
  //    完全依據上傳照片 media_1793881139036_522c6b4e.jpg 比例建構！
  const lowerEaveY = 4.02;                            // 下層兩側水平挑簷高度
  const archSpan   = 5.80;                            // 中央圓弧拱跨度 (介於兩前柱內側 z = sz - 2.90m ~ sz + 2.90m)
  const archHalfW  = archSpan / 2;                    // 2.90m
  const archRise   = 0.76;                            // 圓弧拱高 0.76m (拱頂達 y = 4.78m)
  const archR      = (archHalfW * archHalfW + archRise * archRise) / (2 * archRise);
  const archYc     = (lowerEaveY + archRise) - archR;

  // (a) 中央圓弧拱下方【半月形深褐灰洗石子內凹額牆】(Recessed Dark Washed-Stone Crescent Tympanum per Photo!)
  //     在照片中，舞台正上方圓弧拱簷底下是一整片深褐灰洗石子半月形額牆，底緣有白色水平收邊條！
  const nArchSegs = 28;
  for (let s = 0; s < nArchSegs; s++) {
    const t1 = s / nArchSegs;
    const t2 = (s + 1) / nArchSegs;
    const z1 = (sz - archHalfW) + t1 * archSpan;
    const z2 = (sz - archHalfW) + t2 * archSpan;
    const zMid = (z1 + z2) / 2;

    const y1 = archYc + Math.sqrt(Math.max(0.01, archR * archR - Math.pow(z1 - sz, 2)));
    const y2 = archYc + Math.sqrt(Math.max(0.01, archR * archR - Math.pow(z2 - sz, 2)));
    const yMid = (y1 + y2) / 2;
    const dz = z2 - z1;
    const dy = y2 - y1;
    const segLen = Math.hypot(dz, dy);
    const segAng = Math.atan2(dy, dz);

    // 1. 圓弧挑簷正面深褐灰洗石子厚邊梁 (Front Curved Washed-Stone Arch Fascia)
    const rimGrp = new THREE.Group();
    rimGrp.position.set(sx + 2.98, yMid + 0.14, zMid);
    rimGrp.rotation.x = -segAng;
    addBox(rimGrp, 0.96, 0.30, segLen + 0.04, terrazzoPebbleMat, 0, 0, 0);
    sg.add(rimGrp);

    // 2. 圓弧挑簷底面純白弧形底板 (White Curved Arch Soffit Band)
    const vaultGrp = new THREE.Group();
    vaultGrp.position.set(sx + 2.86, yMid - 0.03, zMid);
    vaultGrp.rotation.x = -segAng;
    addBox(vaultGrp, 1.08, 0.07, segLen + 0.04, soffitMat, 0, 0, 0, false);
    sg.add(vaultGrp);

    // 3. 圓弧拱內部半月形深褐灰洗石子額牆 (Dark Washed-Stone Crescent Spandrel Wall at x = sx + 2.32m)
    const tympH = Math.max(0.04, yMid - lowerEaveY + 0.08);
    addBox(sg, 0.24, tympH, Math.abs(dz) + 0.02, terrazzoPebbleMat, sx + 2.32, lowerEaveY - 0.08 + tympH / 2, zMid);
  }
  // 半月形額牆底部白色水平收邊線條 (White Horizontal Trim under Crescent Tympanum)
  addBox(sg, 0.28, 0.06, archSpan + 0.20, soffitMat, sx + 2.32, lowerEaveY - 0.09, sz);

  // (b) 下層左右兩側水平深褐灰洗石子挑簷 (與中央圓弧拱無縫相接，向外挑出至 z = sz ± 5.35m)
  [-1, 1].forEach(side => {
    const wingSpan = 5.35 - archHalfW;                // 2.45m (自 z = sz ± 2.90m 延伸至 sz ± 5.35m)
    const wingCz   = sz + side * (archHalfW + wingSpan / 2); // sz ± 4.125m
    addBox(sg, 1.18, 0.30, wingSpan, terrazzoPebbleMat, sx + 2.86, lowerEaveY + 0.07, wingCz);
    addBox(sg, 1.14, 0.07, wingSpan - 0.04, soffitMat,  sx + 2.84, lowerEaveY - 0.09, wingCz, false);
  });

  // (c) 拱頂中央【上窄下寬梯形洗石子短柱】(Tapered Trapezoidal Keystone Strut connecting Arch Apex to Upper Roof)
  addBox(sg, 0.32, 0.22, 0.40, terrazzoPebbleMat, sx + 3.05, 4.98, sz);
  addBox(sg, 0.30, 0.24, 0.30, terrazzoPebbleMat, sx + 3.05, 5.18, sz);

  // (d) 上下兩層挑簷之間：米白色平頂天花與左右兩道白色垂直側壁 (位於 z = sz ± 3.80m，與前柱完全對齊！)
  const upperRoofBotY = 5.26;
  const upperRoofH    = 0.56;                         // 上層厚實深褐灰洗石子大橫簷高 0.56m
  const upperRoofTopY = upperRoofBotY + upperRoofH;   // 5.82m
  [-1, 1].forEach(side => {
    const sideWallZ = sz + side * 3.80;
    // 上下層之間白色垂直側牆 (y = 4.02m ~ 5.26m, x = sx - 2.50m ~ sx + 2.68m)
    addBox(sg, 5.18, upperRoofBotY - lowerEaveY, 0.32, whiteWallMat, sx + 0.09, (upperRoofBotY + lowerEaveY) / 2, sideWallZ);
    // 側牆前端金屬斜撐桿與水平投射燈支架 (Photo 左右兩側上簷下方斜撐與燈架)
    const brace = addBox(sg, 0.85, 0.06, 0.06, steelBracketMat, sx + 2.88, 4.92, sideWallZ, false);
    brace.rotation.z = -0.68;
    addBox(sg, 0.42, 0.05, 0.48, steelBracketMat, sx + 3.05, 5.22, sideWallZ, false);
  });

  // (e) 上層厚實圓潤深褐灰洗石子大挑簷平屋頂 (寬 10.70m，向左右兩側白色側牆外挑出 1.55m！)
  const upperSpanZ = 10.70;
  addBox(sg, 6.45, upperRoofH - 0.10, upperSpanZ, terrazzoPebbleMat, sx + 0.48, upperRoofBotY + (upperRoofH - 0.10) / 2 + 0.08, sz);
  // 上簷底部倒角內縮深色洗石子唇緣 (模擬照片中厚實圓弧底緣)
  addBox(sg, 6.25, 0.14, upperSpanZ - 0.16, terrazzoPebbleMat, sx + 0.42, upperRoofBotY + 0.05, sz);
  // 上層挑簷下方純白平頂天花板 (White Ceiling Soffit under Upper Roof)
  addBox(sg, 6.05, 0.06, upperSpanZ - 0.30, soffitMat, sx + 0.35, upperRoofBotY - 0.02, sz, false);

  // (f) 最頂層左右兩道【前高後低斜山牆式白色女兒牆翼板】(位於 z = sz ± 3.80m，與前柱及中層白側牆同平面！)
  //     照片清晰可見：大洗石子橫簷向左右挑出於這兩道白色山牆翼板之外，且翼板前端高聳垂直、向後傾斜下降！
  [-1, 1].forEach(side => {
    const finZ = sz + side * 3.80;
    const finShape = new THREE.Shape();
    finShape.moveTo(-2.50, 0);                        // 後端底部 (x = sx - 2.50m)
    finShape.lineTo(2.45, 0);                         // 前端底部 (x = sx + 2.45m)
    finShape.lineTo(2.45, 1.05);                      // 前端垂直高聳立面 (+1.05m)
    finShape.lineTo(2.05, 1.05);                      // 前端頂部平段 (寬 0.40m)
    finShape.lineTo(-2.50, 0.18);                     // 向後下方斜降之山牆斜邊
    finShape.closePath();

    const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.24, bevelEnabled: false });
    const finMesh = new THREE.Mesh(finGeo, whiteWallMat);
    finMesh.position.set(sx, upperRoofTopY, finZ - 0.12);
    finMesh.castShadow = true;
    sg.add(finMesh);

    // 翼板前端頂部深灰洗石子壓頂與斑駁歲月痕跡
    addBox(sg, 0.44, 0.07, 0.26, terrazzoPebbleMat, sx + 2.25, upperRoofTopY + 1.06, finZ);
  });

  // 前柱上端外側黑色廣播號角喇叭与黑色支架 (Photo 左右前柱頂端外側喇叭)
  for (const pz of [sz - 3.80, sz + 3.80]) {
    const dir = pz > sz ? 1 : -1;
    addBox(sg, 0.14, 0.14, 0.12, speakerMat, sx + 2.58, 3.65, pz + dir * 0.36);
    const horn = addMesh(sg, new THREE.ConeGeometry(0.20, 0.36, 14), speakerMat, sx + 2.76, 3.65, pz + dir * 0.42);
    horn.rotation.z = -Math.PI / 2;
    horn.rotation.y = -dir * 0.35;
  }

  // 8) 左右兩側三階梯狀台座與右側（北側）單一不銹鋼升旗桿 (Photo 右下與左下跑道邊三階梯台座)
  [-1, 1].forEach(side => {
    const platZ = sz + side * 7.85;
    const platX = sx + 1.15;
    addBox(sg, 2.50, 0.13, 2.50, baseWingStoneMat, platX, 0.065, platZ);
    addBox(sg, 1.95, 0.13, 1.95, baseWingStoneMat, platX, 0.195, platZ);
    addBox(sg, 1.40, 0.13, 1.40, baseWingStoneMat, platX, 0.325, platZ);
    addBox(sg, 1.34, 0.03, 1.34, platformFloorMat, platX, 0.395, platZ);
  });

  const flagMeshes = [];
  const poleX = sx + 1.15, poleZ = sz - 7.85;
  addMesh(sg, new THREE.CylinderGeometry(0.14, 0.16, 1.15, 14), baseWingStoneMat, poleX, 0.40 + 0.575, poleZ);
  addMesh(sg, new THREE.CylinderGeometry(0.055, 0.095, 10.6, 16), mats.stainless, poleX, 0.40 + 5.30, poleZ);
  addMesh(sg, new THREE.SphereGeometry(0.14, 16, 12), mats.yellow, poleX, 11.05, poleZ);

  // 升旗拉繩與旗桿底部固定扣 (Halyard & Cleat)
  addMesh(sg, new THREE.CylinderGeometry(0.007, 0.007, 10.6, 6), mats.stainless, poleX + 0.065, 0.40 + 5.30, poleZ);
  addBox(sg, 0.05, 0.12, 0.06, mats.stainless, poleX + 0.07, 1.35, poleZ);

  // 中華民國國旗 (依憲法與《中華民國國徽國旗法》規範 3:2 寬高比，寬 1.95m、高 1.30m)
  const flagW = 1.95, flagH = 1.30;
  const flagGeo = new THREE.PlaneGeometry(flagW, flagH, 24, 12);
  const flagTex = makeROCFlagTexture();
  const flagMat = new THREE.MeshStandardMaterial({
    map: flagTex,
    roughness: 0.60,
    metalness: 0.05,
    side: THREE.DoubleSide
  });
  const flagMesh = new THREE.Mesh(flagGeo, flagMat);
  flagMesh.position.set(poleX + flagW / 2 + 0.045, 10.20, poleZ);
  flagMesh.castShadow = true;
  sg.add(flagMesh);
  flagMeshes.push({
    mesh: flagMesh,
    baseAttr: flagGeo.attributes.position.clone(),
    halfW: flagW / 2,
    phase: 0
  });

  // 全域旗幟動畫清單（供主渲染迴圈計算微風飄動）
  window.__campusFlags = flagMeshes;

  sg.traverse(o => { if (o.isMesh) o.userData.landmarkId = 'command-stage'; });
  layerGroups.sports.add(sg);
  clickableGroups.push(sg);
  landmarkGroupMap.set('command-stage', sg);
}

