// ============================================================================
const foliageMats = [
  new THREE.MeshStandardMaterial({ color: 0x3b7a42, roughness: 0.84 }), // Broad shade crown
  new THREE.MeshStandardMaterial({ color: 0x528e4e, roughness: 0.82 }), // Broad sunlit crown
  new THREE.MeshStandardMaterial({ color: 0x356e3f, roughness: 0.85 }), // Evergreen / Palm crown
  new THREE.MeshStandardMaterial({ color: 0x689e54, roughness: 0.80 })  // Flowering / Accent crown (Spring pink / Autumn gold)
];
const SEASON_PALETTES = {
  spring: { foliage: [0x589c56, 0x76b569, 0x46824b, 0xe895b4], fogTint: 0xf4f2eb, label: '春 · 新綠繁花' },
  summer: { foliage: [0x3b7a42, 0x528e4e, 0x2f6839, 0x689e54], fogTint: 0xebe9e1, label: '夏 · 濃蔭蟬鳴' },
  autumn: { foliage: [0xc97b36, 0xd89c3e, 0x4f7348, 0xe06d3b], fogTint: 0xf0e9dc, label: '秋 · 金風楓染' },
  winter: { foliage: [0x566b5c, 0x6c7d70, 0x45584b, 0x7a8a7d], fogTint: 0xe4e8eb, label: '冬 · 朗潤清寒' }
};
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x69543e, roughness: 0.9 });
const palmTrunkMat = new THREE.MeshStandardMaterial({ color: 0x8c897e, roughness: 0.86 });
const campusTreeRecords = []; // Stored for 2D Architectural Plan (`#plan`) canopy rendering!

// Multi-Species Procedural Tree Builder — 升級為高挑、透光、具層次分支的真實校園景觀喬木
function addTree(x, z, scale = 1, species = 'broad') {
  const tg = new THREE.Group();
  campusTreeRecords.push({ x, z, r: 2.2 * scale, species });

  if (species === 'palm') {
    // Royal Palm (`高聳大王椰子`)：樹幹高挺筆拔，葉冠高懸於空中，絕不阻擋地面校舍立面
    const h = 9.8 * scale;
    addMesh(tg, new THREE.CylinderGeometry(0.18 * scale, 0.28 * scale, h, 10), palmTrunkMat, x, h / 2, z);
    addMesh(tg, new THREE.CylinderGeometry(0.20 * scale, 0.18 * scale, 1.4 * scale, 8), foliageMats[2], x, h + 0.5 * scale, z);
    for (let f = 0; f < 9; f++) {
      const ang = (f / 9) * Math.PI * 2;
      const frond = new THREE.Mesh(new THREE.BoxGeometry(2.6 * scale, 0.08 * scale, 0.42 * scale), foliageMats[2]);
      frond.position.set(x + Math.cos(ang) * 1.25 * scale, h + 0.85 * scale, z + Math.sin(ang) * 1.25 * scale);
      frond.rotation.y = -ang;
      frond.rotation.z = -0.28;
      frond.castShadow = true;
      tg.add(frond);
    }
    layerGroups.vegetation.add(tg);
    return;
  }

  // 升級景觀喬木：提高主幹高度 (3.8m~4.6m)，枝椏向上自然發散，樹冠由多簇輕巧透光葉團構成，地面視野極為通透
  const mainMat = species === 'flowering' ? foliageMats[3] : foliageMats[1];
  const shadeMat = foliageMats[0];
  const trunkH = 3.8 * scale;

  // 主幹 (拔高以確保人行視線貫通後方校舍)
  addMesh(tg, new THREE.CylinderGeometry(0.22 * scale, 0.36 * scale, trunkH, 8), trunkMat, x, trunkH / 2, z);
  
  // 自然分枝 (向上向外延展)
  for (let b = 0; b < 3; b++) {
    const ba = b * 2.09 + (scale * 3.7);
    const branchLen = 2.1 * scale;
    const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.08 * scale, 0.14 * scale, branchLen, 6), trunkMat);
    const bx = x + Math.cos(ba) * 0.72 * scale;
    const bz = z + Math.sin(ba) * 0.72 * scale;
    const by = trunkH + 0.65 * scale;
    branch.position.set(bx, by, bz);
    branch.rotation.z = -Math.cos(ba) * 0.48;
    branch.rotation.x = Math.sin(ba) * 0.48;
    tg.add(branch);

    // 分枝末梢輕盈葉簇 (高度於 5.0m ~ 6.5m 高空，微扁圓造型，通透自然)
    const cluster = addMesh(tg, new THREE.DodecahedronGeometry(1.25 * scale, 1), (b % 2 === 0) ? mainMat : shadeMat, bx * 1.02, by + 0.9 * scale, bz * 1.02);
    cluster.scale.set(1.25, 0.75, 1.20);
  }

  // 主樹冠頂部光照簇團
  const topCrown = addMesh(tg, new THREE.DodecahedronGeometry(1.55 * scale, 1), mainMat, x, trunkH + 1.85 * scale, z);
  topCrown.scale.set(1.30, 0.80, 1.25);

  layerGroups.vegetation.add(tg);
}

