// ---- Animated 3D Articulated Campus Pedestrians (`校園師生行人`, PKU-3D `pedestrians-v46.js` style) ----
const pedestriansGroup = new THREE.Group();
scene.add(pedestriansGroup);
const pedestrianAgents = [];
{
  // PKU-3D `PALETTES`: [coat/shirt, pants, shoe/collar, backpack, skin]
  const shirtColors = [0x315b4e, 0x923c32, 0xd89c3e, 0x36536b, 0x768b81, 0xa16851, 0x59727f];
  const packColors = [0xe4dfcc, 0x7b563c, 0xa37e56, 0x3a554c, 0x9f6345, 0x4c5544];
  const skinMat = new THREE.MeshStandardMaterial({ color: 0xe6bea0, roughness: 0.7 });
  const pantsMat = new THREE.MeshStandardMaterial({ color: 0x2f3b45, roughness: 0.8 });
  const hairMat = new THREE.MeshStandardMaterial({ color: 0x2c2623, roughness: 0.85 });
  const shoeMat = new THREE.MeshStandardMaterial({ color: 0xe8e6dc, roughness: 0.75 });
  const shadowDiscMat = new THREE.MeshBasicMaterial({ color: 0x1d2621, transparent: true, opacity: 0.24, depthWrite: false });

  const loops = [
    // Loop 1: Main Gate -> East Breezeway -> Courtyard Plaza -> North 愛悅樓
    [[X(940), Z(232)], [X(800), Z(232)], [X(745), Z(205)], [X(680), Z(205)], [X(575), Z(205)], [X(575), Z(158)], [X(680), Z(158)], [X(745), Z(205)], [X(800), Z(232)]],
    // Loop 2: Courtyard Perimeter Walk (North -> West -> South -> East)
    [[X(455), Z(156)], [X(705), Z(156)], [X(705), Z(268)], [X(455), Z(268)]],
    // Loop 3: West Breezeway -> Sports Track -> South Building
    [[X(455), Z(225)], [X(382), Z(225)], [X(382), Z(305)], [X(500), Z(305)], [X(500), Z(268)], [X(455), Z(268)]],
    // Loop 4: Running Track Oval (Students jogging on the 200m PU track inside the Rear Wall & Campus Lawn Buffer Zone)
    (() => {
      const pts = [];
      const cx = X(288), cz = Z(248), r = 56 * S, hs = 64 * S;
      for (let i = 0; i < 16; i++) {
        const a = (i / 16) * Math.PI * 2;
        pts.push([cx + Math.cos(a) * r, cz + Math.sin(a) * (r + hs)]);
      }
      return pts;
    })(),
    // Loop 5: Exterior Commuter Walkway Buffer (`後圍牆外通學步道師生步行路線`: 西側後門 -> 運動場西側通學步道 -> 西南轉角 -> 建興南路42巷通學步道 -> 南側門)
    [
      [X(46), Z(90)], [X(46), Z(328)], [X(174), Z(490)], [X(406), Z(402)], [X(506), Z(380)],
      [X(722), Z(373)], [X(506), Z(380)], [X(406), Z(402)], [X(174), Z(490)], [X(46), Z(328)]
    ]
  ];

  for (let i = 0; i < 28; i++) {
    const loop = loops[i % loops.length];
    const isRunner = (i % loops.length) === 3;
    const scale = (i % 5 === 0) ? 1.06 : (0.80 + (i % 3) * 0.06); // Teachers & elementary students
    const fig = new THREE.Group();
    const sMat = new THREE.MeshStandardMaterial({ color: shirtColors[i % shirtColors.length], roughness: 0.68 });
    const pMat = new THREE.MeshStandardMaterial({ color: packColors[i % packColors.length], roughness: 0.72 });

    // Soft Ground Contact Shadow Disc (`PKU-3D SHADOW_FRAG` equivalent)
    const shadowDisc = new THREE.Mesh(new THREE.CircleGeometry(0.32 * scale, 12), shadowDiscMat);
    shadowDisc.rotation.x = -Math.PI / 2;
    shadowDisc.position.y = 0.02;
    fig.add(shadowDisc);

    // Torso, Neck, Head & Hair cap (`PKU-3D pedestrians-v46 pose`)
    addBox(fig, 0.36 * scale, 0.52 * scale, 0.22 * scale, sMat, 0, 0.94 * scale, 0);
    addMesh(fig, new THREE.SphereGeometry(0.155 * scale, 10, 10), skinMat, 0, 1.38 * scale, 0);
    addMesh(fig, new THREE.SphereGeometry(0.162 * scale, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.58), hairMat, 0, 1.40 * scale, -0.01 * scale);
    // School Backpack (`學生書包`) on 2/3 of walkers
    if (i % 3 !== 0) {
      addBox(fig, 0.28 * scale, 0.34 * scale, 0.15 * scale, pMat, 0, 0.96 * scale, -0.17 * scale);
    }
    // Articulated Left & Right Arms + Hands
    const armL = addBox(fig, 0.10 * scale, 0.46 * scale, 0.11 * scale, sMat, -0.23 * scale, 0.92 * scale, 0);
    const armR = addBox(fig, 0.10 * scale, 0.46 * scale, 0.11 * scale, sMat, 0.23 * scale, 0.92 * scale, 0);
    // Articulated Left & Right Legs + Shoes
    const legL = new THREE.Group();
    legL.position.set(-0.09 * scale, 0.66 * scale, 0);
    addBox(legL, 0.13 * scale, 0.56 * scale, 0.14 * scale, pantsMat, 0, -0.28 * scale, 0);
    addBox(legL, 0.13 * scale, 0.09 * scale, 0.22 * scale, shoeMat, 0, -0.58 * scale, 0.04 * scale);
    fig.add(legL);

    const legR = new THREE.Group();
    legR.position.set(0.09 * scale, 0.66 * scale, 0);
    addBox(legR, 0.13 * scale, 0.56 * scale, 0.14 * scale, pantsMat, 0, -0.28 * scale, 0);
    addBox(legR, 0.13 * scale, 0.09 * scale, 0.22 * scale, shoeMat, 0, -0.58 * scale, 0.04 * scale);
    fig.add(legR);

    pedestriansGroup.add(fig);

    pedestrianAgents.push({
      mesh: fig,
      legL,
      legR,
      armL,
      armR,
      loop,
      segIdx: i % loop.length,
      segT: (i * 0.27) % 1,
      speed: isRunner ? (4.2 + (i % 3) * 0.45) : (1.95 + (i % 4) * 0.22),
      phase: i * 1.3
    });
  }
}

