// Smooth Camera Flight Tween
let camAnim = null;
const prefersReducedMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function updateUrlParams(bldgId, floor, roomCode) {
  try {
    const url = new URL(window.location.href);
    if (bldgId) url.searchParams.set('bldg', bldgId);
    else url.searchParams.delete('bldg');
    if (floor && floor !== '1F') url.searchParams.set('floor', floor);
    else url.searchParams.delete('floor');
    if (roomCode) url.searchParams.set('room', roomCode);
    else url.searchParams.delete('room');
    window.history.replaceState(null, '', url.pathname + url.search);
  } catch {}
}

function flyTo(posArr, targetArr, duration = 900) {
  followingPedestrianIdx = -1;
  requestRender(Math.ceil((duration / 1000) * 60) + 40);
  const toPos = new THREE.Vector3(...posArr);
  const toTarget = new THREE.Vector3(...targetArr);
  controls.maxPolarAngle = Math.PI - 0.01;
  controls.minPolarAngle = 0.01;
  if (prefersReducedMotion() || !motionEnabled || duration <= 0) {
    camera.position.copy(toPos);
    controls.target.copy(toTarget);
    controls.update();
    camAnim = null;
    requestRender(20);
    return;
  }
  camAnim = {
    fromPos: camera.position.clone(),
    fromTarget: controls.target.clone(),
    toPos,
    toTarget,
    start: performance.now(),
    duration
  };
}

// PKU-3D `PanelOffset` Camera Projection Framing (`app-v29.js` lines 112-123 & 149)
function computeTargetPanelOffset() {
  if (activeMode !== '3d' || walkState.active) return { x: 0, y: 0 };
  const w = window.innerWidth, h = window.innerHeight;
  const catEl = document.getElementById('catalog');
  const detEl = document.getElementById('detail');
  const envEl = document.getElementById('environment');
  const catOpen = catEl && !catEl.classList.contains('is-collapsed');
  const rightOpen = (detEl && !detEl.hidden) || (envEl && !envEl.hidden);

  if (w <= 820) {
    return { x: 0, y: (detEl && !detEl.hidden) ? h * 0.14 : 0 };
  }
  let leftPad = catOpen ? 360 : 16;
  let rightPad = rightOpen ? 390 : 16;
  // Positive x in Three.js setViewOffset shifts the frustum window right (so the 3D center moves left/right to balance panels)
  const shiftX = (rightPad - leftPad) * 0.42;
  return { x: shiftX, y: 0 };
}

function updateCameraViewOffset(dtSec) {
  const goal = computeTargetPanelOffset();
  panelOffsetState.goalX = goal.x;
  panelOffsetState.goalY = goal.y;
  const alpha = (prefersReducedMotion() || !motionEnabled) ? 1 : Math.min(1, dtSec * 10);
  panelOffsetState.curX += (panelOffsetState.goalX - panelOffsetState.curX) * alpha;
  panelOffsetState.curY += (panelOffsetState.goalY - panelOffsetState.curY) * alpha;

  const w = window.innerWidth, h = window.innerHeight;
  if (Math.abs(panelOffsetState.curX) > 0.5 || Math.abs(panelOffsetState.curY) > 0.5) {
    camera.setViewOffset(w, h, panelOffsetState.curX, panelOffsetState.curY, w, h);
  } else {
    camera.clearViewOffset();
  }
}

// PKU-3D Compact Detail Mode (`setDetailCompact` from `app-v29.js` lines 155-165)
function setDetailCompact(compact) {
  const det = document.getElementById('detail');
  const expBtn = document.getElementById('detail-expand');
  if (!det || !expBtn) return;
  const shouldCompact = Boolean(compact && !det.hidden && activeMode === '3d' && !walkState.active && (window.innerWidth <= 820 || window.innerHeight <= 640));
  det.classList.toggle('detail-compact', shouldCompact);
  expBtn.hidden = !shouldCompact;
  expBtn.setAttribute('aria-expanded', String(!shouldCompact));
}

document.getElementById('detail-expand')?.addEventListener('click', () => setDetailCompact(false));

function fitPrecinct(key) {
  const preset = PRECINCT_PRESETS[key] || PRECINCT_PRESETS.campus;
  if (walkState.active) exitWalkMode();
  if (isIsolated) setIsolationMode(false);
  followingPedestrianIdx = -1;
  isTopView = false;
  isOrbiting = false;
  updateToolButtons();

  document.querySelectorAll('#precinct-bar .precinct-pill').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.precinct === key);
  });

  if (activeMode === 'plan') {
    const cx = preset.plan.x + preset.plan.w / 2;
    const cz = preset.plan.y + preset.plan.h / 2;
    flyTo([cx, Math.max(85, preset.plan.w * 0.65), cz + 0.5], [cx, 0, cz], 750);
  } else {
    flyTo(preset.p, preset.t, 900);
  }
  if (key !== 'campus') showToast(`已定位至片區：${preset.label}`);
  else showToast('已返回全校鳥瞰視角');
  if (window.innerWidth <= 820 || window.innerHeight <= 640) {
    setCatalogOpen(false);
    detailEl.hidden = true;
  }
}

document.querySelectorAll('#precinct-bar .precinct-pill').forEach(btn => {
  btn.addEventListener('click', () => fitPrecinct(btn.dataset.precinct));
});

function resetOverview() {
  fitPrecinct('campus');
  updateUrlParams(null, null, null);
  requestRender(70);
  if (window.innerWidth <= 820 || window.innerHeight <= 640) {
    setCatalogOpen(false);
    detailEl.hidden = true;
  }
}

// ---- Building Isolation Mode (`單體欣賞`, PKU-3D Signature Feature) ----
function setIsolationMode(enable) {
  isIsolated = Boolean(enable && selectedId);
  const banner = document.getElementById('isolation-banner');
  const isoBtn = document.getElementById('isolate');
  if (isoBtn) {
    isoBtn.classList.toggle('is-isolated', isIsolated);
    isoBtn.textContent = isIsolated ? '返回校園' : '單體欣賞';
  }
  if (!isIsolated) {
    banner.hidden = true;
    layerGroups.context.visible = layerState.context;
    layerGroups.vegetation.visible = layerState.vegetation;
    layerGroups.boundary.visible = layerState.boundary;
    pedestriansGroup.visible = layerState.people;
    clickableGroups.forEach(grp => { grp.visible = true; });
    return;
  }
  const lm = LANDMARKS.find(l => l.id === selectedId);
  document.getElementById('isolation-name').textContent = lm ? lm.name : '';
  banner.hidden = false;

  // Hide surrounding distractions so the selected building can be inspected in pure architectural isolation
  layerGroups.context.visible = false;
  layerGroups.boundary.visible = false;
  pedestriansGroup.visible = false;
  const targetGrp = landmarkGroupMap.get(selectedId);
  clickableGroups.forEach(grp => {
    grp.visible = (grp === targetGrp);
  });
  showToast(`已進入「${lm ? lm.name : ''}」單體觀察模式`);
}

document.getElementById('isolation-banner').addEventListener('click', () => setIsolationMode(false));

// Highlight Selected Building Outline
function updateSelectionOutline(landmarkId) {
  while (selectionOutlineGroup.children.length) {
    selectionOutlineGroup.remove(selectionOutlineGroup.children[0]);
  }
  if (!landmarkId) return;
  const lm = LANDMARKS.find(l => l.id === landmarkId);
  if (!lm || !lm.pxBounds) return;
  const [x1, y1, x2, y2] = lm.pxBounds;
  const w = (x2 - x1) * S + 2.2, d = (y2 - y1) * S + 2.2;
  const cx = X((x1 + x2) / 2), cz = Z((y1 + y2) / 2);
  const ringGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(cx - w / 2, 0.32, cz - d / 2),
    new THREE.Vector3(cx + w / 2, 0.32, cz - d / 2),
    new THREE.Vector3(cx + w / 2, 0.32, cz + d / 2),
    new THREE.Vector3(cx - w / 2, 0.32, cz + d / 2),
    new THREE.Vector3(cx - w / 2, 0.32, cz - d / 2)
  ]);
  const ringLine = new THREE.Line(ringGeo, new THREE.LineBasicMaterial({ color: 0x923c32, linewidth: 2 }));
  selectionOutlineGroup.add(ringLine);
}

// Create HTML Floating Labels for all 12 Landmarks + 66 Classroom Pins
const labelElements = new Map();
const roomPinElements = [];

function buildSceneLabels() {
  labelsRoot.innerHTML = '';
  labelElements.clear();
  roomPinElements.length = 0;

  LANDMARKS.forEach(lm => {
    const btn = document.createElement('button');
    btn.className = 'map-label';
    btn.innerHTML = `<span class="idx">${lm.index}</span><span class="lm-lbl-text">${lm.name}</span>`;
    btn.addEventListener('click', e => {
      e.stopPropagation();
      selectLandmark(lm.id, 'manual', activePlanFloor === 'ALL' ? '1F' : activePlanFloor);
      if (window.innerWidth <= 820 || window.innerHeight <= 640) {
        detailEl.hidden = false;
        setDetailCompact(true);
      }
    });
    btn.addEventListener('pointerenter', () => setHovered(lm.id));
    btn.addEventListener('pointerleave', () => setHovered(null));
    labelsRoot.appendChild(btn);
    labelElements.set(lm.id, { el: btn, pos: new THREE.Vector3(...lm.center), lm });

    if (lm.pxBounds && lm.rooms) {
      const [x1, y1, x2, y2] = lm.pxBounds;
      const bw = (x2 - x1) * S, bd = (y2 - y1) * S;
      const bx0 = X(x1);
      Object.entries(lm.rooms).forEach(([floorKey, roomArr]) => {
        const floorNum = floorKey === 'B1' ? -0.5 : (floorKey === '1F' ? 0 : (floorKey === '2F' ? 1 : 2));
        const ry = floorNum * 3.5 + 2.4;
        roomArr.forEach(rm => {
          const rEl = document.createElement('button');
          const codeStr = rm.code || '';
          const nameStr = rm.name || '';
          let catClass = 'cat-pub';
          if (floorKey === 'B1') catClass = 'cat-b1';
          else if (lm.id === 'new-building' || codeStr.startsWith('K') || codeStr === 'S1-KOFF' || /幼兒/.test(nameStr)) catClass = 'cat-kinder';
          else if (/[一二三四五六]年級| (10[1-3]|20[1-4]|30[1-3]|40[1-4]|50[1-4]|60[1-4]) /.test(nameStr)) catClass = 'cat-class';
          else if (['11', '21', '12', '13', '14', '71'].includes(codeStr) || /校長室|人事室|教務處|學務處|總務處|輔導/.test(nameStr)) catClass = 'cat-admin';
          else if (['41', '43', '46', '47', '44', '48', '49', '45-M', '65', '63', '62', '70', '64', '35', '33', '38', '37', '76'].includes(codeStr)) catClass = 'cat-spec';

          rEl.className = `map-label room-pin ${catClass}`;
          const shortDisp = rm.short ? (/^\d+$/.test( codeStr ) && !rm.short.includes(codeStr) ? `${rm.short} (${codeStr})` : rm.short) : rm.name;
          rEl.dataset.fullText = `${floorKey === 'B1' ? 'BF' : floorKey} ${rm.name}`;
          rEl.dataset.shortText = shortDisp;
          rEl.textContent = rEl.dataset.fullText;
          rEl.title = `${lm.name} · ${floorKey === 'B1' ? 'BF' : floorKey} · ${rm.name}（單擊對焦詳情，雙擊進入 3D 走廊視角）`;
          const worldPos = new THREE.Vector3(
            bx0 + rm.rx * bw,
            ry,
            Z((y1 + y2) / 2) + rm.rz * bd
          );
          rEl.addEventListener('click', e => {
            e.stopPropagation();
            selectedId = lm.id;
            updateSelectionOutline(lm.id);
            focusClassroom(lm, floorKey, rm, worldPos);
            renderDetailCard(lm, floorKey);
            detailEl.hidden = false;
          });
          rEl.addEventListener('dblclick', e => {
            e.stopPropagation();
            selectedId = lm.id;
            activeRoomCode = rm.code;
            if (activeMode !== '3d') switchViewMode('3d');
            const corridorV = getClassroomCorridorView(lm, floorKey, rm, worldPos);
            flyTo(corridorV.p, corridorV.t, 780);
            showToast(`已進入 3D 走廊視角：${lm.name} ${floorKey} · ${rm.name}`);
          });
          labelsRoot.appendChild(rEl);
          roomPinElements.push({ el: rEl, code: rm.code, landmarkId: lm.id, floorKey, pos: worldPos, room: rm, catClass });
        });
      });
    }
  });
}
buildSceneLabels();

function setHovered(id) {
  hoveredId = id;
  labelElements.forEach((v, k) => v.el.classList.toggle('hovered', k === id));
  document.querySelectorAll('.place-item').forEach(row => {
    row.classList.toggle('hovered', row.dataset.id === id);
  });
}

// ============================================================================
// 7. PKU-3D LEFT CATALOG (`#catalog`) & RIGHT DETAIL PANEL (`#detail`)
// ============================================================================
const placesListEl = document.getElementById('placesList');
const searchInputEl = document.getElementById('searchInput');
const detailEl = document.getElementById('detail');

// ============================================================================
// 115學年度 校園空間分類對應邏輯（依據 2026_0801 校園平面圖圖例設定）
// 空間分類：班級、專科、行政、公共、幼兒園、其他、運動、出入口*6、精選、全部
// ============================================================================
function getRoomCategory(rm, lm) {
  const code = rm.code || '';
  const name = rm.name || '';
  const lmId = lm?.id || '';

  // 1. 幼兒園（深紅框）：新棟復興非營利幼兒園全棟及南棟非營幼辦公室
  if (lmId === 'new-building' || code.startsWith('K') || code === 'S1-KOFF' || /幼兒園/.test(name)) {
    return '幼兒園';
  }

  // 2. 班級（綠框）：101~103, 201~204, 301~303, 401~404, 501~504, 601~604
  if (/[一二三四五六]年級|(10[1-3]|20[1-4]|30[1-3]|40[1-4]|50[1-4]|60[1-4])/.test(name)) {
    return '班級';
  }

  // 3. 行政（橙框）：校長室(11)、教務處(12)、學務處(13)、總務處(14)、人事室(21)、輔導室(71)
  if (['11', '21', '12', '13', '14', '71'].includes(code) || /校長室|人事室|教務處|學務處|總務處|輔導室/.test(name)) {
    return '行政';
  }

  // 4. 其他（紫框）：儲藏室 (74)
  if (code === '74' || /儲藏室/.test(name)) {
    return '其他';
  }

  // 5. 公共（黃框）：健康中心/保健室(20)、圖書室(32)、視聽教室(36)、展演廳(30)、會議室(40)、課照3(72)、課照4(73)、幼兒活動室/閱讀室(S2-KACT, S3-KACT)、國際柑仔店(42)、防空避難室(45, B1-W)
  if (['20', '32', '36', '30', '40', '72', '73', 'S2-KACT', 'S3-KACT', '42', '45', 'B1-W'].includes(code) ||
      /健康中心|保健室|圖書室|共讀站|視聽教室|展演廳|會議室|課照[34]|閱讀室|活動室|柑仔店|防空避難室/.test(name)) {
    return '公共';
  }

  // 6. 專科（藍框）：自然一~四、英語一~二、社會一~三、美術、音樂、電腦、數位學習、巡輔資源班一~二、多功能、體育室、體適能
  if (['41', '43', '46', '47', '44', '48', '49', '45-M', '65', '63', '62', '70', '64', '35', '33', '38', '37', '76'].includes(code) ||
      /自然|英語|社會|美術|音樂|電腦|數位學習|巡輔|資源班|多功能|體育室|體適能/.test(name)) {
    return '專科';
  }

  return '公共';
}

function getLandmarkCategories(lm) {
  const cats = [];
  const id = lm.id;

  if (FEATURED_IDS.includes(id)) cats.push('featured');
  cats.push('all');

  if (['north-building', 'south-building'].includes(id)) {
    cats.push('班級');
  }
  if (['west-building'].includes(id)) {
    cats.push('專科');
  }
  if (['east-building'].includes(id)) {
    cats.push('行政');
  }
  if (['courtyard-plaza', 'breezeway-hub', 'playground-zone', 'east-south-mosaic'].includes(id)) {
    cats.push('公共');
  }
  if (['new-building'].includes(id)) {
    cats.push('幼兒園');
  }
  if (['command-stage', 'carport', 'organic-farm', 'recycling-depot'].includes(id)) {
    cats.push('其他');
  }
  if (['sports-track', 'ball-courts', 'command-stage'].includes(id)) {
    cats.push('運動');
  }
  if (['main-gate', 'east-gate', 'west-back-gate', 'stage-back-gate', 'new-south-gate', 'old-south-gate'].includes(id)) {
    cats.push('出入口');
  }

  return cats;
}

function renderPlacesList() {
  const q = searchInputEl.value.trim().toLowerCase();
  placesListEl.innerHTML = '';

  // 1. NON-SEARCH MODE: When query is empty, filter by activeFilter
  if (!q) {
    if (activeFilter === 'featured') {
      const featLms = LANDMARKS.filter(lm => FEATURED_IDS.includes(lm.id));
      featLms.forEach(lm => {
        const btn = document.createElement('button');
        btn.className = 'place-item' + (selectedId === lm.id ? ' is-selected' : '');
        btn.dataset.id = lm.id;
        btn.innerHTML = `
          <span class="place-number">${lm.index}</span>
          <span>
            <strong class="place-title">${lm.name}</strong>
            <small class="place-sub">${lm.enName}</small>
          </span>
          <span class="place-tag">精選</span>
        `;
        btn.addEventListener('click', () => {
          selectLandmark(lm.id, 'manual');
          if (window.innerWidth <= 820 || window.innerHeight <= 640) {
            setCatalogOpen(false);
            detailEl.hidden = false;
          }
        });
        btn.addEventListener('pointerenter', () => setHovered(lm.id));
        btn.addEventListener('pointerleave', () => setHovered(null));
        placesListEl.appendChild(btn);
      });
      document.getElementById('result-count').textContent = `${featLms.length} 處精選地標`;
      return;
    }

    if (activeFilter === 'all') {
      LANDMARKS.forEach(lm => {
        const roomCount = Object.values(lm.rooms || {}).flat().length;
        const btn = document.createElement('button');
        btn.className = 'place-item' + (selectedId === lm.id ? ' is-selected' : '');
        btn.dataset.id = lm.id;
        btn.innerHTML = `
          <span class="place-number">${lm.index}</span>
          <span>
            <strong class="place-title">${lm.name}</strong>
            <small class="place-sub">${lm.enName}${roomCount ? ` · ${roomCount} 間空間處室` : ''}</small>
          </span>
          <span class="place-tag">${lm.category ? lm.category.slice(0, 3) : '校園'}</span>
        `;
        btn.addEventListener('click', () => {
          selectLandmark(lm.id, 'manual');
          if (window.innerWidth <= 820 || window.innerHeight <= 640) {
            setCatalogOpen(false);
            detailEl.hidden = false;
          }
        });
        btn.addEventListener('pointerenter', () => setHovered(lm.id));
        btn.addEventListener('pointerleave', () => setHovered(null));
        placesListEl.appendChild(btn);
      });
      document.getElementById('result-count').textContent = `全校 ${LANDMARKS.length} 處地標與設施`;
      return;
    }

    // SPATIAL CATEGORIES FROM UPLOADED MAP:
    // ['班級', '專科', '行政', '公共', '幼兒園', '其他', '運動', '出入口']
    const matchingLms = LANDMARKS.filter(lm => getLandmarkCategories(lm).includes(activeFilter));
    const matchingRooms = [];

    LANDMARKS.forEach(lm => {
      Object.entries(lm.rooms || {}).forEach(([fl, arr]) => {
        arr.forEach(rm => {
          const cat = getRoomCategory(rm, lm);
          if (cat === activeFilter || (activeFilter === '運動' && ['41', '44'].includes(rm.code))) {
            matchingRooms.push({ lm, fl, rm });
          }
        });
      });
    });

    // Special sort for '班級': grade order (101~103, 201~204, 301~303, 401~404, 501~504, 601~604)
    if (activeFilter === '班級') {
      matchingRooms.sort((a, b) => {
        const getNum = str => {
          const m = str.match(/\b([1-6]0[1-4])\b/);
          return m ? parseInt(m[1]) : 999;
        };
        return getNum(a.rm.name) - getNum(b.rm.name);
      });
    }

    // Render matching landmarks first
    matchingLms.forEach(lm => {
      const roomCount = Object.values(lm.rooms || {}).flat().length;
      const btn = document.createElement('button');
      btn.className = 'place-item' + (selectedId === lm.id ? ' is-selected' : '');
      btn.dataset.id = lm.id;
      btn.innerHTML = `
        <span class="place-number">${lm.index}</span>
        <span>
          <strong class="place-title">${lm.name}</strong>
          <small class="place-sub">${lm.enName}${roomCount ? ` · ${roomCount} 間空間處室` : ''}</small>
        </span>
        <span class="place-tag">${activeFilter}</span>
      `;
      btn.addEventListener('click', () => {
        selectLandmark(lm.id, 'manual');
        if (window.innerWidth <= 820 || window.innerHeight <= 640) {
          setCatalogOpen(false);
          detailEl.hidden = false;
        }
      });
      btn.addEventListener('pointerenter', () => setHovered(lm.id));
      btn.addEventListener('pointerleave', () => setHovered(null));
      placesListEl.appendChild(btn);
    });

    // Render matching rooms
    matchingRooms.forEach(({ lm, fl, rm }) => {
      const btn = document.createElement('button');
      btn.className = 'place-item';
      btn.innerHTML = `
        <span class="place-number" style="color:var(--seal);font-weight:700">${fl}</span>
        <span>
          <strong class="place-title">${rm.name}</strong>
          <small class="place-sub">${lm.name} · ${fl}空間</small>
        </span>
        <span class="place-tag">定位 ›</span>
      `;
      btn.addEventListener('click', () => {
        selectLandmark(lm.id, 'manual', fl, rm.code);
        if (window.innerWidth <= 820 || window.innerHeight <= 640) {
          setCatalogOpen(false);
          detailEl.hidden = false;
        }
      });
      placesListEl.appendChild(btn);
    });

    // Summary count text
    if (matchingLms.length && matchingRooms.length) {
      document.getElementById('result-count').textContent = `${matchingRooms.length} 間空間 · ${matchingLms.length} 棟主體`;
    } else if (matchingRooms.length) {
      document.getElementById('result-count').textContent = `${matchingRooms.length} 間${activeFilter}教室`;
    } else {
      document.getElementById('result-count').textContent = `${matchingLms.length} 處${activeFilter}設施`;
    }
    return;
  }

  // 2. SEARCH MODE: When query is entered
  const matchedLms = LANDMARKS.filter(lm =>
    lm.name.toLowerCase().includes(q) ||
    lm.enName.toLowerCase().includes(q) ||
    lm.summary.toLowerCase().includes(q)
  );

  matchedLms.forEach(lm => {
    const btn = document.createElement('button');
    btn.className = 'place-item' + (selectedId === lm.id ? ' is-selected' : '');
    btn.dataset.id = lm.id;
    btn.innerHTML = `
      <span class="place-number">${lm.index}</span>
      <span>
        <strong class="place-title">${lm.name}</strong>
        <small class="place-sub">${lm.enName}</small>
      </span>
      <span class="place-tag">建築地標</span>
    `;
    btn.addEventListener('click', () => {
      selectLandmark(lm.id, 'manual');
      if (window.innerWidth <= 820 || window.innerHeight <= 640) {
        setCatalogOpen(false);
        detailEl.hidden = false;
      }
    });
    btn.addEventListener('pointerenter', () => setHovered(lm.id));
    btn.addEventListener('pointerleave', () => setHovered(null));
    placesListEl.appendChild(btn);
  });

  let matchedRoomCount = 0;

  // 1) Match Official Extension Numbers (e.g. 11 校長室, 14 總務處, 12 教務處, 20 保健室)
  const allExts = [...EXTENSION_DIR_COL1, ...EXTENSION_DIR_COL2];
  allExts.forEach(ext => {
    if (ext.ext === q || ext.label.toLowerCase().includes(q) || (q.length >= 2 && ext.ext.includes(q))) {
      matchedRoomCount++;
      const btn = document.createElement('button');
      btn.className = 'place-item';
      btn.innerHTML = `
        <span class="place-number" style="color:var(--accent);font-weight:700">分機 ${ext.ext}</span>
        <span>
          <strong class="place-title">${ext.label}</strong>
          <small class="place-sub">學校處室分機直達 · ${ext.floor}</small>
        </span>
        <span class="place-tag" style="background:var(--accent);color:#fff">分機 ⌕</span>
      `;
      btn.addEventListener('click', () => {
        selectLandmark(ext.pid, 'manual', ext.floor, ext.code);
        if (window.innerWidth <= 820 || window.innerHeight <= 640) {
          setCatalogOpen(false);
          detailEl.hidden = false;
        }
      });
      placesListEl.appendChild(btn);
    }
  });

  // 2) Match Classrooms, Rooms & Short Codes (e.g. 401, 101, 幼幼, 居禮)
  LANDMARKS.forEach(lm => {
    Object.entries(lm.rooms || {}).forEach(([fl, arr]) => {
      arr.forEach(rm => {
        const matchesName = rm.name.toLowerCase().includes(q);
        const matchesCode = rm.code.toLowerCase().includes(q);
        const matchesShort = rm.short && rm.short.toLowerCase().includes(q);
        if (matchesName || matchesCode || matchesShort) {
          matchedRoomCount++;
          const btn = document.createElement('button');
          btn.className = 'place-item';
          btn.innerHTML = `
            <span class="place-number" style="color:var(--accent);font-weight:700">${fl}</span>
            <span>
              <strong class="place-title">${rm.name}</strong>
              <small class="place-sub">${lm.name} · 115學年度空間定位</small>
            </span>
            <span class="place-tag">空間 ⌖</span>
          `;
          btn.addEventListener('click', () => {
            selectLandmark(lm.id, 'manual', fl, rm.code);
            if (window.innerWidth <= 820 || window.innerHeight <= 640) {
              setCatalogOpen(false);
              detailEl.hidden = false;
            }
          });
          placesListEl.appendChild(btn);
        }
      });
    });
  });

  const totalCount = matchedLms.length + matchedRoomCount;
  document.getElementById('result-count').textContent = `搜尋結果 ${totalCount} 項`;

  if (totalCount === 0) {
    placesListEl.innerHTML = `
      <div style="padding:28px 12px;text-align:center;color:var(--muted);font-size:12px">
        找不到符合「${searchInputEl.value}」的空間。<br>
        <button type="button" onclick="document.getElementById('searchInput').value='';document.getElementById('searchInput').dispatchEvent(new Event('input'))" style="margin-top:8px;padding:5px 12px;border-radius:5px;background:var(--wash);color:var(--accent);font-weight:600">重設搜尋</button>
      </div>
    `;
  }
}

searchInputEl.addEventListener('input', () => renderPlacesList());

document.querySelectorAll('#category-filters .chip').forEach(chip => {
  chip.addEventListener('click', () => {
    activeFilter = chip.dataset.filter;
    document.querySelectorAll('#category-filters .chip').forEach(c => c.classList.toggle('is-active', c === chip));
    renderPlacesList();
  });
});

// PKU-3D Catalog Open/Collapse Synchronization (`setCatalogOpen` & `syncDisclosure` from `app-v29.js` lines 403-405)
function setCatalogOpen(open, focusControl = false) {
  const cat = document.getElementById('catalog');
  const toggleBtn = document.getElementById('catalog-toggle');
  const restoreBtn = document.getElementById('catalog-restore');
  cat.classList.toggle('is-collapsed', !open);
  toggleBtn.setAttribute('aria-expanded', String(open));
  if (restoreBtn) {
    restoreBtn.hidden = open;
    restoreBtn.setAttribute('aria-expanded', String(open));
  }
  try { localStorage.setItem('fuxing.catalog.collapsed', open ? '0' : '1'); } catch {}
  if (open && window.innerWidth <= 820) {
    detailEl.hidden = true;
  }
  if (focusControl) {
    (open ? searchInputEl : restoreBtn)?.focus();
  }
}

document.getElementById('catalog-toggle').addEventListener('click', () => {
  const isCollapsed = document.getElementById('catalog').classList.contains('is-collapsed');
  setCatalogOpen(isCollapsed);
});
document.getElementById('catalog-collapse')?.addEventListener('click', () => setCatalogOpen(false, true));
document.getElementById('catalog-restore')?.addEventListener('click', () => setCatalogOpen(true, true));

// Restore saved catalog state on load
try {
  const savedCat = localStorage.getItem('fuxing.catalog.collapsed');
  if (savedCat === '1' || (savedCat === null && window.innerWidth <= 820)) {
    setCatalogOpen(false);
  }
} catch {}

document.getElementById('reset-view').addEventListener('click', resetOverview);

// ============================================================================
// CLASSROOM FRONT CORRIDOR VIEW & DIRECT FRONT FACADE POSITION CALCULATION
// ============================================================================
function getClassroomCorridorView(lm, floorKey, rm, worldPos) {
  const lmId = lm?.id || '';
  const flNum = floorKey === 'B1' ? -0.5 : (floorKey === '1F' ? 0 : (floorKey === '2F' ? 1 : 2));
  const eyeY = (worldPos ? worldPos.y : flNum * 3.5 + 2.4) + 0.35;
  const wx = worldPos ? worldPos.x : (lm?.center ? lm.center[0] : 0);
  const wz = worldPos ? worldPos.z : (lm?.center ? lm.center[2] : 0);

  let p, t;

  if (lmId === 'north-building') {
    // 北棟・愛悅樓：前走廊位於南側（面向中庭花園，走廊軸線 Z ≈ -25.5m），視線朝北 (-Z) 正對教室前門窗與課桌椅
    p = [wx, eyeY + 0.25, -23.0];
    t = [wx, eyeY - 0.20, -30.5];
  } else if (lmId === 'south-building') {
    // 南棟・興學樓：前走廊位於北側（面向中庭花園，走廊軸線 Z ≈ 8.78~10.78m），視線朝南 (+Z) 正對教室前門窗與新配備課桌椅黑板
    p = [wx, eyeY + 0.25, 6.8];
    t = [wx, eyeY - 0.20, 13.8];
  } else if (lmId === 'west-building') {
    // 西棟・育樂樓：前走廊位於東側（面向中庭花園，走廊軸線 X ≈ -25.7m），視線朝西 (-X) 正對教室前走廊與內部空間
    p = [-21.8, eyeY + 0.25, wz];
    t = [-30.6, eyeY - 0.20, wz];
  } else if (lmId === 'east-building') {
    // 東棟・彩繪行政大樓：前走廊位於東側（彩繪外立面前走廊，走廊軸線 X ≈ 63.5~65.0m），視線朝西 (-X) 正對處室與教室
    p = [68.5, eyeY + 0.25, wz];
    t = [58.5, eyeY - 0.20, wz];
  } else if (lmId === 'new-building') {
    // 新棟・幼兒園：前走廊位於北側（面向中庭與草皮區，走廊軸線 Z ≈ 16.0~19.0m），視線朝南 (+Z) 正對幼兒園活動室教室
    p = [wx, eyeY + 0.25, 13.8];
    t = [wx, eyeY - 0.20, 21.6];
  } else {
    // 通用開放場域或其它空間備用視角
    p = [wx, eyeY + 1.2, wz + 6.5];
    t = [wx, eyeY, wz];
  }

  return { p, t };
}

// ============================================================================
// CLASSROOM BIRD-EYE OBLIQUE VIEW & SURROUNDING CAMPUS BACKGROUND CALCULATION
// ============================================================================
function getClassroomBirdEyeView(lm, floorKey, rm, worldPos) {
  const lmId = lm?.id || '';
  const flNum = floorKey === 'B1' ? -0.5 : (floorKey === '1F' ? 0 : (floorKey === '2F' ? 1 : 2));
  const ry = worldPos ? worldPos.y : (flNum * 3.5 + 2.4);
  const wx = worldPos ? worldPos.x : (lm?.center ? lm.center[0] : 0);
  const wz = worldPos ? worldPos.z : (lm?.center ? lm.center[2] : 0);

  let p, t;

  if (lmId === 'north-building') {
    // 北棟・愛悅樓：教室朝向南側中庭，從中庭偏西南斜上方俯瞰北棟，教室標籤清晰居中，背景包含北側樹林與圍牆街道
    p = [wx - 10.0, 26.0, 10.0];
    t = [wx, Math.max(ry, 5.0), -31.5];
  } else if (lmId === 'south-building') {
    // 南棟・興學樓：教室朝向北側中庭，從中庭北側斜上方俯瞰南棟，背景呈現南側街景與校園全貌
    p = [wx + 8.0, 26.0, -26.0];
    t = [wx, Math.max(ry, 5.0), 14.5];
  } else if (lmId === 'west-building') {
    // 西棟・育樂樓：教室朝向中庭東側，從操場西側斜上方俯瞰西棟（如運動場空拍視角），背景呈現綠意中庭與對面東棟
    p = [-85.0, 28.0, wz + 16.0];
    t = [-31.0, Math.max(ry, 5.0), wz];
  } else if (lmId === 'east-building') {
    // 東棟・彩繪行政大樓：教室與處室朝向前庭，從復興路前庭斜上方俯瞰東棟彩繪立面，背景呈現中庭與穿堂綠意
    p = [112.0, 30.0, wz + 16.0];
    t = [60.0, Math.max(ry, 5.0), wz];
  } else if (lmId === 'new-building') {
    // 新棟・幼兒園：從南側草皮區斜上方俯瞰幼兒園，背景呈現中庭與北棟
    p = [wx + 10.0, 28.0, wz + 38.0];
    t = [wx, Math.max(ry, 5.0), 20.0];
  } else {
    // 通用地點或開放空間鳥瞰角度
    p = [wx + 24.0, 26.0, wz + 28.0];
    t = [wx, ry || 3.0, wz];
  }

  return { p, t };
}

function selectLandmark(id, origin = 'manual', initialFloor = '1F', highlightRoomCode = null, initialViewpoint = null) {
  if (walkState.active) exitWalkMode();
  followingPedestrianIdx = -1;
  selectedId = id;
  activeRoomCode = highlightRoomCode;
  const lm = LANDMARKS.find(l => l.id === id);
  updateSelectionOutline(id);
  setDetailCompact(false);

  if (isIsolated && id) setIsolationMode(true);

  labelElements.forEach((v, k) => v.el.classList.toggle('selected', k === id));
  roomPinElements.forEach(p => p.el.classList.toggle('active-room', p.code === highlightRoomCode));
  document.querySelectorAll('.place-item').forEach(r => r.classList.toggle('is-selected', r.dataset.id === id));
  updateMinimap();
  renderPlanSvg();

  if (!lm) {
    detailEl.hidden = true;
    return;
  }

  document.getElementById('minimapLabel').textContent = lm.name;

  if (origin === 'manual' || origin === 'card') {
    stopTour(false);
    // Hide environment panel if open so right `#detail` card is clearly visible
    document.getElementById('environment').hidden = true;
    document.getElementById('environment-open').setAttribute('aria-expanded', 'false');
    if (window.innerWidth <= 820 || window.innerHeight <= 640) {
      setCatalogOpen(false);
      detailEl.hidden = false;
      setDetailCompact(false);
    } else {
      detailEl.hidden = false;
      detailEl.scrollTop = 0;
    }
  }

  isOrbiting = (origin === 'tour');

  if (activeMode === '3d') {
    if (highlightRoomCode) {
      let pin = roomPinElements.find(p => p.code === highlightRoomCode);
      if (!pin && lm.rooms) {
        const [x1, y1, x2, y2] = lm.pxBounds || [0,0,0,0];
        const bw = (x2 - x1) * S, bd = (y2 - y1) * S;
        const bx0 = X(x1);
        const floorNum = initialFloor === 'B1' ? -0.5 : (initialFloor === '1F' ? 0 : (initialFloor === '2F' ? 1 : 2));
        const ry = floorNum * 3.5 + 2.4;
        const foundRm = Object.values(lm.rooms).flat().find(r => r.code === highlightRoomCode);
        if (foundRm) {
          const wPos = new THREE.Vector3(bx0 + foundRm.rx * bw, ry, Z((y1 + y2) / 2) + foundRm.rz * bd);
          pin = { pos: wPos, room: foundRm, floorKey: initialFloor };
        }
      }
      if (pin) {
        // 定位至指定班級/教室之宏偉鳥瞰視角，清晰顯示教室標籤與周遭校園背景
        const birdEyeV = getClassroomBirdEyeView(lm, pin.floorKey || initialFloor, pin.room, pin.pos);
        activeViewMode = 'oblique';
        flyTo(birdEyeV.p, birdEyeV.t, 850);
        showToast(`已定位：${lm.name} ${pin.floorKey || initialFloor} · ${pin.room?.name || highlightRoomCode}（鳥瞰視角）`);
      } else {
        const targetV = (lm.views && (lm.views.oblique || lm.views.front || Object.values(lm.views)[0])) || { p: [-12, 42, 22], t: [10, 5.5, -31.5] };
        activeViewMode = 'oblique';
        flyTo(targetV.p, targetV.t, 900);
      }
    } else {
      let targetV;
      if (initialViewpoint && lm.views && lm.views[initialViewpoint]) {
        targetV = lm.views[initialViewpoint];
        activeViewMode = initialViewpoint;
      } else {
        // 全校 21 處地標與各棟建築在選取後，一律優先定位至宏偉鳥瞰角度 (views.oblique)，清晰呈現該地點與周遭背景
        targetV = (lm.views && lm.views.oblique) || (lm.views && (lm.views.front || lm.views.entrance || Object.values(lm.views)[0])) || { p: [-12, 42, 22], t: [10, 5.5, -31.5] };
        activeViewMode = (lm.views && lm.views.oblique) ? 'oblique' : 'front';
      }
      flyTo(targetV.p, targetV.t, 900);
      if (origin === 'manual' && !highlightRoomCode) {
        showToast(`已定位至地標：${lm.name}（鳥瞰視角）`);
      }
    }
  } else if (lm.pxBounds) {
    // In 3D Plan Cutaway Mode: switch floor if needed and fly top-down camera above the selected landmark/room
    if (highlightRoomCode && initialFloor && ['1F', '2F', '3F', 'B1'].includes(initialFloor)) {
      activePlanFloor = initialFloor;
      document.querySelectorAll('[data-plan-floor]').forEach(b => b.classList.toggle('is-active', b.dataset.planFloor === activePlanFloor));
    }
    const [x1, y1, x2, y2] = lm.pxBounds;
    const cx = X((x1 + x2) / 2), cz = Z((y1 + y2) / 2);
    const pin = highlightRoomCode ? roomPinElements.find(p => p.code === highlightRoomCode) : null;
    const tx = pin ? pin.pos.x : cx;
    const tz = pin ? pin.pos.z : cz;
    const ty = pin ? pin.pos.y : 2.0;
    flyTo([tx, pin ? 56 : 92, tz + 0.4], [tx, ty, tz], 680);
    renderPlanSvg();
  }

  updateUrlParams(id, initialFloor, highlightRoomCode);
  requestRender(80);
  updateToolButtons();
  renderDetailCard(lm, initialFloor);
}

function focusClassroom(lm, floorKey, rm, worldPos) {
  activeRoomCode = rm.code;
  activePlanFloor = floorKey;
  updateUrlParams(lm.id, floorKey, rm.code);
  requestRender(80);
  document.querySelectorAll('[data-plan-floor]').forEach(b => b.classList.toggle('is-active', b.dataset.planFloor === floorKey));
  roomPinElements.forEach(p => p.el.classList.toggle('active-room', p.code === rm.code));
  activeViewMode = 'oblique';
  updateToolButtons();
  if (activeMode === '3d') {
    // 定位至指定教室之宏偉鳥瞰視角，清晰顯示教室標籤與周遭校園背景
    const birdEyeV = getClassroomBirdEyeView(lm, floorKey, rm, worldPos);
    flyTo(birdEyeV.p, birdEyeV.t, 820);
    showToast(`已定位：${lm.name} ${floorKey} · ${rm.name}（鳥瞰視角）`);
  } else {
    renderPlanSvg();
    if (worldPos) {
      flyTo([worldPos.x, 56, worldPos.z + 0.4], [worldPos.x, worldPos.y, worldPos.z], 650);
    }
    showToast(`已定位：${lm.name} ${floorKey === 'B1' ? 'BF' : floorKey} · ${rm.name}（雙擊標籤可直接進入 3D 走廊）`);
  }
}

function renderDetailCard(lm, activeFloor = '1F') {
  document.getElementById('detail-category').textContent = `NO.${lm.index} · ${lm.category}`;
  document.getElementById('detail-title').textContent = lm.name;
  document.getElementById('detail-english').textContent = lm.enName;
  document.getElementById('detail-summary').textContent = lm.summary;

  const roomCount = Object.values(lm.rooms || {}).flat().length;
  document.getElementById('detail-tags').innerHTML = `
    <span class="detail-tag seal">編號 ${lm.index}</span>
    <span class="detail-tag">${lm.floors}</span>
    <span class="detail-tag">${lm.height}</span>
    ${roomCount ? `<span class="detail-tag">${roomCount} 間教室處室</span>` : ''}
  `;

  // Update viewpoints active state & dynamic visibility
  document.querySelectorAll('#viewpoints-bar button').forEach(btn => {
    const vp = btn.dataset.viewpoint;
    if (vp !== 'orbit' && vp !== 'oblique') {
      btn.hidden = !(lm.views && lm.views[vp]);
    } else {
      btn.hidden = false;
    }
    btn.classList.toggle('is-active', vp === 'orbit' ? isOrbiting : (vp === activeViewMode && !isOrbiting));
  });

  // Update Isolation button state
  const isoBtn = document.getElementById('isolate');
  isoBtn.classList.toggle('is-isolated', isIsolated);
  isoBtn.textContent = isIsolated ? '返回校園' : '單體欣賞';

  // Render 1F/2F/3F Classrooms inside `#detail-floors`
  const floorsEl = document.getElementById('detail-floors');
  const floorKeys = Object.keys(lm.rooms || {});
  if (floorKeys.length > 0) {
    floorsEl.hidden = false;
    const currentFloor = floorKeys.includes(activeFloor) ? activeFloor : floorKeys[0];
    const rooms = lm.rooms[currentFloor] || [];
    floorsEl.innerHTML = `
      <p class="eyebrow">115學年度 樓層教室與處室定位</p>
      <div class="floor-tabs">
        ${floorKeys.map(fk => `<button type="button" class="floor-tab ${fk === currentFloor ? 'is-active' : ''}" data-floor="${fk}">${fk} 樓層</button>`).join('')}
      </div>
      <div class="room-pills">
        ${rooms.map(r => `<button type="button" class="room-pill ${activeRoomCode === r.code ? 'is-active' : ''}" data-rcode="${r.code}">${r.name}</button>`).join('')}
      </div>
    `;
    floorsEl.querySelectorAll('[data-floor]').forEach(fBtn => {
      fBtn.addEventListener('click', () => {
        activePlanFloor = fBtn.dataset.floor;
        document.querySelectorAll('[data-plan-floor]').forEach(b => b.classList.toggle('is-active', b.dataset.planFloor === activePlanFloor));
        renderDetailCard(lm, fBtn.dataset.floor);
        renderPlanSvg();
      });
    });
    floorsEl.querySelectorAll('[data-rcode]').forEach(rBtn => {
      rBtn.addEventListener('click', () => {
        const code = rBtn.dataset.rcode;
        activeRoomCode = code;
        floorsEl.querySelectorAll('[data-rcode]').forEach(b => b.classList.toggle('is-active', b.dataset.rcode === code));
        const pin = roomPinElements.find(p => p.code === code);
        if (pin) {
          focusClassroom(lm, pin.floorKey, pin.room, pin.pos);
        } else {
          const rm = (lm.rooms[currentFloor] || []).find(r => r.code === code);
          if (rm && lm.pxBounds) {
            const [x1, y1, x2, y2] = lm.pxBounds;
            const bw = (x2 - x1) * S, bd = (y2 - y1) * S;
            const bx0 = X(x1);
            const floorNum = currentFloor === 'B1' ? -0.5 : (currentFloor === '1F' ? 0 : (currentFloor === '2F' ? 1 : 2));
            const ry = floorNum * 3.5 + 2.4;
            const worldPos = new THREE.Vector3(bx0 + rm.rx * bw, ry, Z((y1 + y2) / 2) + rm.rz * bd);
            focusClassroom(lm, currentFloor, rm, worldPos);
          }
        }
      });
    });
  } else {
    floorsEl.hidden = true;
    floorsEl.innerHTML = '';
  }

  // Render Horizontal Reference Strip (`#detail-references`)
  const refsEl = document.getElementById('detail-references');
  if (lm.photos && lm.photos.length) {
    refsEl.hidden = false;
    refsEl.innerHTML = `
      <p class="eyebrow" style="margin-bottom:6px">立面測繪與實景圖集（點擊放大）</p>
      <div class="reference-strip">
        ${lm.photos.map(p => `
          <button type="button" class="reference-thumb" data-src="${p.src}" data-title="${p.title}">
            <img src="${p.src}" alt="${p.title}" loading="lazy" />
            <span>${p.title}</span>
          </button>
        `).join('')}
      </div>
    `;
    refsEl.querySelectorAll('.reference-thumb').forEach(thumb => {
      thumb.addEventListener('click', () => window.openLightbox(thumb.dataset.src, thumb.dataset.title));
    });
  } else {
    refsEl.hidden = true;
  }

  // Compute envelope dimensions in meters (PKU-3D `envelopeMetres` style)
  let envDims = '開放場域';
  if (lm.pxBounds) {
    const [x1, y1, x2, y2] = lm.pxBounds;
    const wm = ((x2 - x1) * S * 1.15).toFixed(1);
    const dm = ((y2 - y1) * S * 1.15).toFixed(1);
    envDims = `約 ${wm} × ${dm} 公尺`;
  }

  // Render `<dl id="detail-facts">`
  document.getElementById('detail-facts').innerHTML = `
    <div><dt>空間分區</dt><dd>${lm.category}</dd></div>
    <div><dt>外包尺寸</dt><dd>${envDims}</dd></div>
    <div><dt>建築層數</dt><dd>${lm.floors}</dd></div>
    <div><dt>設計高度</dt><dd>${lm.height}</dd></div>
    <div style="grid-column:1 / -1"><dt>建模依據</dt><dd>${lm.basis}</dd></div>
  `;
}

document.getElementById('detail-close').addEventListener('click', () => {
  if (isIsolated) setIsolationMode(false);
  setDetailCompact(false);
  detailEl.hidden = true;
  selectedId = null;
  activeRoomCode = null;
  roomPinElements.forEach(p => p.el.classList.remove('active-room'));
  updateSelectionOutline(null);
  renderPlacesList();
  renderPlanSvg();
});

document.getElementById('focus').addEventListener('click', () => {
  const lm = LANDMARKS.find(l => l.id === selectedId);
  if (!lm) return;
  if (activeMode !== '3d') switchViewMode('3d');
  flyTo(lm.views.entrance.p, lm.views.entrance.t, 800);
});

document.getElementById('isolate').addEventListener('click', () => {
  if (activeMode !== '3d') switchViewMode('3d');
  setIsolationMode(!isIsolated);
});

document.querySelectorAll('#viewpoints-bar button').forEach(btn => {
  btn.addEventListener('click', () => {
    const lm = LANDMARKS.find(l => l.id === selectedId);
    if (!lm) return;
    if (activeMode !== '3d') switchViewMode('3d');
    const vp = btn.dataset.viewpoint;
    if (vp === 'orbit') {
      isOrbiting = !isOrbiting;
    } else {
      isOrbiting = false;
      activeViewMode = vp;
      setDetailCompact(['front', 'back', 'entrance', 'top', 'west_toilet', 'west_stair_side', 'track_junction', 'courtyard_junction', 'indoor_junction', 'south_new_junction', 'dinosaur', 'read', 'train'].includes(vp));
      if (lm.views[vp]) flyTo(lm.views[vp].p, lm.views[vp].t, 820);
    }
    document.querySelectorAll('#viewpoints-bar button').forEach(b => {
      const bvp = b.dataset.viewpoint;
      b.classList.toggle('is-active', bvp === 'orbit' ? isOrbiting : (bvp === activeViewMode && !isOrbiting));
    });
    updateToolButtons();
  });
});

