function formatTimeLabel(hr) {
  const h = Math.floor(hr);
  const m = Math.round((hr - h) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function updateEnvironmentSimulation() {
  const timeStr = formatTimeLabel(timeOfDay);
  document.getElementById('time-label').textContent = timeStr;
  document.getElementById('time-of-day').value = String(timeOfDay);

  // Determine solar elevation & phase from continuous hour (6.0 .. 21.0)
  const isNight = timeOfDay >= 18.5 || timeOfDay < 6.3;
  const isDuskOrDawn = (timeOfDay >= 16.5 && timeOfDay < 18.5) || (timeOfDay >= 6.3 && timeOfDay < 7.8);
  const presetKey = isNight ? 'night' : (timeOfDay < 8.5 ? 'morning' : (timeOfDay >= 16.5 ? 'evening' : 'day'));

  document.documentElement.dataset.theme = isNight ? 'night' : 'day';
  labelsRoot.dataset.light = isNight ? 'night' : 'day';

  // Compute solar trajectory across Pingtung sky
  const dayProgress = THREE.MathUtils.clamp((timeOfDay - 6) / 12.5, 0, 1);
  const sunAngle = dayProgress * Math.PI; // 0 (East sunrise) -> PI/2 (Noon) -> PI (West sunset)
  const sunX = Math.cos(sunAngle) * 165;
  const sunY = isNight ? 95 : Math.max(24, Math.sin(sunAngle) * 170);
  const sunZ = 75 + Math.sin(sunAngle * 0.8) * 35;
  sunLight.position.set(sunX, sunY, sunZ);

  const cfg = LIGHTING_PRESETS[presetKey];

  // Apply seasonal foliage colors across all 4 botanical material groups
  if (seasonsEnabled) {
    const seasonCfg = SEASON_PALETTES[activeSeason] || SEASON_PALETTES.summer;
    foliageMats.forEach((mat, idx) => {
      mat.color.setHex(seasonCfg.foliage[idx % seasonCfg.foliage.length]);
    });
  }

  // Sky & Fog with Weather adjustments
  const skyTex = createSkyTexture(presetKey);
  scene.background = skyTex;
  scene.environment = skyTex;

  let fogNear = cfg.fogNear, fogFar = cfg.fogFar;
  if (activeWeather === 'mist') { fogNear = 55; fogFar = 235; }
  else if (activeWeather === 'rain') { fogNear = 95; fogFar = 320; }
  else if (activeWeather === 'snow') { fogNear = 85; fogFar = 290; }
  scene.fog = new THREE.Fog(cfg.horizon, fogNear, fogFar);

  sunLight.color.setHex(cfg.sunColor);
  sunLight.intensity = activeWeather === 'clear' ? cfg.sunIntensity : cfg.sunIntensity * 0.68;
  hemiLight.color.setHex(cfg.hemiSky);
  hemiLight.groundColor.setHex(cfg.hemiGround);
  hemiLight.intensity = cfg.hemiIntensity;
  renderer.toneMappingExposure = cfg.exposure;

  // Toggle Night / Dusk Window Glow & Streetlights
  const winGlow = isNight ? 0.92 : (isDuskOrDawn ? 0.32 : 0);
  nightWindowMaterials.forEach(m => { m.emissiveIntensity = winGlow; });
  streetLightBulbs.forEach(b => { b.visible = isNight || isDuskOrDawn; });

  // Weather Particle configuration
  if (activeWeather === 'rain') {
    weatherPoints.visible = true;
    weatherMat.color.setHex(0xbfd8ee);
    weatherMat.size = 0.55;
    weatherMat.opacity = 0.68;
  } else if (activeWeather === 'snow') {
    weatherPoints.visible = true;
    weatherMat.color.setHex(0xffffff);
    weatherMat.size = 1.05;
    weatherMat.opacity = 0.88;
  } else {
    weatherPoints.visible = false;
  }

  const seasonWord = { spring: '春', summer: '夏', autumn: '秋', winter: '冬' }[activeSeason];
  const weatherWord = { clear: '晴', rain: '雨', mist: '霧', snow: '雪' }[activeWeather];
  document.getElementById('env-button-label').textContent = `光影與生活 · ${timeStr} ${seasonWord}·${weatherWord}`;
  updateMinimap();
  renderPlanSvg();
}

