// ============================================================================
// 9. `沿路探索` (`#route-panel`) CAMPUS WALKWAY GRAPH & AUTO-WALK PLAYBACK
// ============================================================================
const routeFromSel = document.getElementById('route-from');
const routeToSel = document.getElementById('route-to');
const routeSummaryEl = document.getElementById('route-summary');
const routeProgressWrap = document.getElementById('route-progress-wrap');
const routeProgressInput = document.getElementById('route-progress');
const routeProgressLabel = document.getElementById('route-progress-label');

LANDMARKS.forEach((lm, idx) => {
  routeFromSel.add(new Option(`${lm.index} ${lm.name}`, lm.id, idx === 11, idx === 11)); // Default From: 12 復興路正門
  routeToSel.add(new Option(`${lm.index} ${lm.name}`, lm.id, idx === 0, idx === 0));       // Default To: 01 北棟（愛悅樓）
});

// Campus Walkway Nodes & Edges (in pixel coordinates, converted via X(px), Z(py))
const ROUTE_NODES = {
  'main-gate':       [945, 232],
  'front-plaza':     [815, 215],
  'east-building':   [760, 205],
  'east-south-mosaic': [760, 315],
  'breezeway-hub':   [735, 205],
  'courtyard-east':  [695, 205],
  'playground-zone': [682, 162],
  'north-building':  [575, 155],
  'courtyard-plaza': [578, 211],
  'south-building':  [605, 270],
  'courtyard-west':  [455, 215],
  'west-building':   [425, 225],
  'new-building':    [445, 305],
  'old-south-gate':  [657, 318],
  'new-south-gate':  [772, 320],
  'track-east':      [382, 235],
  'sports-track':    [294, 255],
  'command-stage':   [192, 268],
  'ball-courts':     [145, 205]
};

const ROUTE_EDGES = [
  ['main-gate', 'front-plaza'],
  ['front-plaza', 'east-building'],
  ['east-building', 'breezeway-hub'],
  ['east-building', 'east-south-mosaic'],
  ['main-gate', 'east-south-mosaic'],
  ['east-south-mosaic', 'new-south-gate'],
  ['new-south-gate', 'old-south-gate'],
  ['old-south-gate', 'new-building'],
  ['breezeway-hub', 'courtyard-east'],
  ['courtyard-east', 'playground-zone'],
  ['playground-zone', 'north-building'],
  ['courtyard-east', 'courtyard-plaza'],
  ['courtyard-plaza', 'north-building'],
  ['courtyard-plaza', 'south-building'],
  ['courtyard-east', 'south-building'],
  ['courtyard-plaza', 'courtyard-west'],
  ['north-building', 'courtyard-west'],
  ['south-building', 'courtyard-west'],
  ['courtyard-west', 'west-building'],
  ['courtyard-west', 'new-building'],
  ['south-building', 'new-building'],
  ['west-building', 'track-east'],
  ['new-building', 'track-east'],
  ['track-east', 'sports-track'],
  ['sports-track', 'command-stage'],
  ['command-stage', 'ball-courts'],
  ['sports-track', 'ball-courts']
];

function findShortestRoute(startId, endId) {
  const adj = {};
  Object.keys(ROUTE_NODES).forEach(k => { adj[k] = []; });
  ROUTE_EDGES.forEach(([a, b]) => {
    const [ax, ay] = ROUTE_NODES[a], [bx, by] = ROUTE_NODES[b];
    const d = Math.hypot(ax - bx, ay - by);
    adj[a].push({ to: b, d });
    adj[b].push({ to: a, d });
  });
  const dist = {}, prev = {}, visited = new Set();
  Object.keys(ROUTE_NODES).forEach(k => { dist[k] = Infinity; });
  dist[startId] = 0;

  while (true) {
    let u = null, best = Infinity;
    for (const k of Object.keys(ROUTE_NODES)) {
      if (!visited.has(k) && dist[k] < best) { best = dist[k]; u = k; }
    }
    if (!u || u === endId) break;
    visited.add(u);
    for (const edge of adj[u]) {
      const alt = dist[u] + edge.d;
      if (alt < dist[edge.to]) {
        dist[edge.to] = alt;
        prev[edge.to] = u;
      }
    }
  }
  const path = [];
  let cur = endId;
  while (cur) { path.unshift(cur); cur = prev[cur]; }
  return path.length > 1 ? path : [startId, endId];
}

function computeAndRenderRoute() {
  const fromId = routeFromSel.value;
  const toId = routeToSel.value;
  while (route3DGroup.children.length) route3DGroup.remove(route3DGroup.children[0]);

  if (fromId === toId) {
    activeRoutePoints3D = [];
    activeRouteLengthMeters = 0;
    routeSummaryEl.textContent = '起點與終點相同，請選擇不同的校園地標。';
    routeProgressWrap.hidden = true;
    syncWalkHUD();
    renderPlanSvg();
    return;
  }

  const nodeIds = findShortestRoute(fromId, toId);
  const rawPts = nodeIds.map(nid => {
    const [px, py] = ROUTE_NODES[nid];
    return new THREE.Vector3(X(px), 0.42, Z(py));
  });

  // Build smooth CatmullRom spline for walking & 3D ribbon
  const curve = new THREE.CatmullRomCurve3(rawPts, false, 'catmullrom', 0.18);
  activeRoutePoints3D = curve.getSpacedPoints(80);

  // 3D Glowing Pine-Green / Vermilion Route Ribbon
  const tubeGeo = new THREE.TubeGeometry(curve, 64, 0.42, 8, false);
  const tubeMat = new THREE.MeshBasicMaterial({ color: 0x923c32 });
  route3DGroup.add(new THREE.Mesh(tubeGeo, tubeMat));

  // Start & End Beacon Rings
  [rawPts[0], rawPts[rawPts.length - 1]].forEach((pt, idx) => {
    const marker = new THREE.Mesh(
      new THREE.CylinderGeometry(1.3, 1.3, 0.35, 20),
      new THREE.MeshBasicMaterial({ color: idx === 0 ? 0x315b4e : 0x923c32 })
    );
    marker.position.copy(pt);
    route3DGroup.add(marker);
  });

  // Calculate real-world meters & walking time
  let lengthM = 0;
  for (let i = 1; i < activeRoutePoints3D.length; i++) {
    lengthM += activeRoutePoints3D[i].distanceTo(activeRoutePoints3D[i - 1]);
  }
  activeRouteLengthMeters = Math.round(lengthM * 1.15);
  const walkMin = Math.max(1, Math.round(activeRouteLengthMeters / 65));
  const fromName = LANDMARKS.find(l => l.id === fromId)?.name || '';
  const toName = LANDMARKS.find(l => l.id === toId)?.name || '';

  routeSummaryEl.innerHTML = `<strong>${fromName} → ${toName}</strong><br>校園連通步道約 <strong>${activeRouteLengthMeters} 公尺</strong> · 步行約需 <strong>${walkMin} 分鐘</strong>`;
  routeProgressWrap.hidden = false;
  routeWalkProgress = 0;
  routeProgressInput.value = '0';
  routeProgressLabel.textContent = '0%';
  syncWalkHUD();
  renderPlanSvg();
}

routeFromSel.addEventListener('change', computeAndRenderRoute);
routeToSel.addEventListener('change', computeAndRenderRoute);

document.getElementById('route-close').addEventListener('click', () => {
  document.getElementById('route-panel').hidden = true;
  routeWalkActive = false;
  syncWalkHUD();
});

document.getElementById('route-clear').addEventListener('click', () => {
  routeWalkActive = false;
  activeRoutePoints3D = [];
  activeRouteLengthMeters = 0;
  while (route3DGroup.children.length) route3DGroup.remove(route3DGroup.children[0]);
  routeSummaryEl.textContent = '路線已清除。選擇兩處校園地點可重新規劃步道。';
  routeProgressWrap.hidden = true;
  document.getElementById('route-walk').textContent = '沿線自動漫步';
  syncWalkHUD();
  renderPlanSvg();
});

function toggleRouteTravel() {
  if (!activeRoutePoints3D.length) computeAndRenderRoute();
  if (!activeRoutePoints3D.length) return;
  if (activeMode !== '3d') switchViewMode('3d');
  routeWalkActive = !routeWalkActive;
  if (routeWalkActive) {
    if (routeWalkProgress >= 0.99) routeWalkProgress = 0;
    walkState.detachedFromRoute = false;
    if (!walkState.active) {
      const p0 = activeRoutePoints3D[0];
      const p1 = activeRoutePoints3D[Math.min(3, activeRoutePoints3D.length - 1)];
      startWalkMode([p0.x, 1.72, p0.z], [p1.x, 1.72, p1.z], true);
      routeWalkActive = true;
      walkState.detachedFromRoute = false;
    }
  }
  syncWalkHUD();
}

document.getElementById('route-walk').addEventListener('click', toggleRouteTravel);
document.getElementById('walk-pause')?.addEventListener('click', toggleRouteTravel);

routeProgressInput.addEventListener('input', e => {
  if (!activeRoutePoints3D.length) computeAndRenderRoute();
  routeWalkActive = false;
  walkState.detachedFromRoute = false;
  routeWalkProgress = parseFloat(e.target.value) / 100;
  routeProgressLabel.textContent = `${Math.round(routeWalkProgress * 100)}%`;
  placeCameraOnRoute(routeWalkProgress);
  syncWalkHUD();
});

function placeCameraOnRoute(t) {
  if (activeRoutePoints3D.length < 2) return;
  const idx = Math.min(activeRoutePoints3D.length - 2, Math.floor(t * (activeRoutePoints3D.length - 1)));
  const frac = t * (activeRoutePoints3D.length - 1) - idx;
  const pos = new THREE.Vector3().lerpVectors(activeRoutePoints3D[idx], activeRoutePoints3D[idx + 1], frac);
  const lookIdx = Math.min(activeRoutePoints3D.length - 1, idx + 4);
  const lookPos = activeRoutePoints3D[lookIdx].clone();
  camera.position.set(pos.x, 1.72, pos.z);
  const dx = lookPos.x - pos.x, dz = lookPos.z - pos.z;
  if (Math.hypot(dx, dz) > 0.05) {
    walkState.yaw = Math.atan2(-dx, -dz);
  }
  if (walkState.active) {
    updateWalkCameraTarget();
  } else {
    controls.target.set(lookPos.x, 1.72, lookPos.z);
  }
}

// ============================================================================
// 10. COLLISION-AWARE FIRST-PERSON GROUND WALK (`PKU-3D FirstPerson` class)
// ============================================================================
// Solid building obstacle footprints (excluding open plazas/tracks and East Breezeway passage)
const SOLID_BUILDING_OBSTACLES = LANDMARKS
  .filter(lm => ['north-building', 'south-building', 'west-building', 'new-building'].includes(lm.id) && lm.pxBounds)
  .map(lm => {
    const [x1, y1, x2, y2] = lm.pxBounds;
    return {
      minX: X(x1) - 0.65,
      maxX: X(x2) + 0.65,
      minZ: Z(y1) - 0.65,
      maxZ: Z(y2) + 0.65
    };
  });
// Add East Building North & South wings while leaving the 1F Central Breezeway (`Z(185)..Z(225)`) open for walking!
SOLID_BUILDING_OBSTACLES.push(
  { minX: X(715) - 0.5, maxX: X(762) + 0.5, minZ: Z(88) - 0.5,  maxZ: Z(199) },
  { minX: X(715) - 0.5, maxX: X(762) + 0.5, minZ: Z(233),       maxZ: Z(315) + 0.5 }
);

// Collision footprint exclusions: allow walking inside North Building (愛悅樓) Front/Rear corridors, Central Stairwell, Basement & Lightwells!
function isWalkPointAllowed(wx, wz) {
  if (wx < -125 || wx > 130 || wz < -60 || wz > 80) return false;

  // North Building (愛悅樓):
  const C = window.NORTH_COLLISION;
  if (C && wx > C.westX - 0.2 && wx < C.eastX + 0.2 && wz > C.zb - 1.95 && wz < C.zf + 2.65) {
    // If exploring Basement (camera Y <= 1.55m): allow full basement rooms, central stair lobby, and lightwells!
    if (typeof camera !== 'undefined' && camera.position.y <= 1.55) {
      if (wz >= C.zb - 1.85 && wz <= C.zb + 0.10) return true; // North Lightwell corridor
      if (wz >= C.zf - 0.10 && wz <= C.zf + 2.55) return true; // South Lightwell corridor & stepped garden planters
      if (wx >= C.hallL - 0.2 && wx <= C.hallR + 0.2 && wz >= C.zCB - 0.2 && wz <= C.zCF + 0.2) return true; // central lobby
      if (wz >= C.zCB + 0.15 && wz <= C.zCF - 0.15) return true; // air-raid shelters and utility rooms
      return false;
    }
    // Ground & upper floors (1F–3F)
    if (wz >= C.zCF - 0.05) return true;                       // front corridor (+ balcony edge)
    if (wz <= C.zCB + 0.05) return true;                       // rear corridor
    if (wx >= C.hallL && wx <= C.hallR) return true;           // central stair hall (including downward stair)
    for (const r of C.rooms) {
      if (wx > r.x1 + 0.25 && wx < r.x2 - 0.25 && wz > C.zCB + 0.25 && wz < C.zCF - 0.25) return true; // classroom interior
      if (Math.abs(wx - r.doorX) < 0.38 && wz >= C.zCF - 0.30 && wz <= C.zCF + 0.05) return true;      // open doorway
    }
    return false;
  }

  // West Building (育樂樓): allow walking along 1F East Corridor (`-27.04..-24.31`), 1F West Corridor (`-38.11..-34.13`),
  // and through the 4-bay open 1F Breezeway (`川堂`, `z = -14.19..-1.06`) & North Entrance Corridor (`z = -16.84..-14.19`)!
  if (wx >= -38.8 && wx <= -23.0 && wz >= -24.0 && wz <= 16.2) {
    if (wx >= -27.1 && wx <= -24.0 && wz >= -17.9 && wz <= 15.9) return true; // 1F/2F/3F East Front Corridor
    if (wx >= -38.3 && wx <= -34.0 && wz >= -17.9 && wz <= 15.9) return true; // 1F/2F/3F West Rear Corridor
    if (wz >= -17.90 && wz <= -1.05 && wx >= -38.3 && wx <= -24.0) return true; // 1F 川堂, East-Up Staircase & Right-Turn Passage
  }

  // New Building <-> South Building `⑩–⑪` Shared Corridor (`wx = -6.72..-4.22`, `wz = 8.78..24.15`): allow walking through the south picket gate and shared corridor!
  if (wx >= -6.85 && wx <= -4.10 && wz >= 8.20 && wz <= 24.50) return true;

  // Remaining solid building obstacles (north-building box is handled above)
  return !SOLID_BUILDING_OBSTACLES.some(b => {
    if (b.minX < -20 && b.maxX > 50 && b.minZ < -35 && b.maxZ > -28) return false;
    return wx > b.minX && wx < b.maxX && wz > b.minZ && wz < b.maxZ;
  });
}

function syncWalkHUD() {
  const hasRoute = activeRoutePoints3D.length > 1;
  const done = hasRoute && routeWalkProgress >= 0.99;
  const pauseBtn = document.getElementById('walk-pause');
  const modeEl = document.getElementById('walk-mode');
  const distEl = document.getElementById('walk-distance');
  const routePlayBtn = document.getElementById('route-walk');

  if (pauseBtn) {
    pauseBtn.hidden = !hasRoute;
    pauseBtn.textContent = routeWalkActive ? '暫停' : (done ? '再走一遍' : (walkState.detachedFromRoute ? '回到路線' : '繼續步行'));
  }
  if (modeEl) {
    modeEl.textContent = routeWalkActive ? '沿路步行' : (hasRoute && !walkState.detachedFromRoute ? (done ? '已抵達終點' : '路線已暫停') : '自由步行');
  }
  if (distEl) {
    const curM = Math.round(routeWalkProgress * activeRouteLengthMeters);
    distEl.textContent = (hasRoute && !walkState.detachedFromRoute)
      ? `${curM} / ${activeRouteLengthMeters} m · W A S D 可隨時自由探索`
      : '沿校園步道漫遊 · W A S D 移動 · 拖曳環顧';
  }
  if (routePlayBtn) {
    routePlayBtn.textContent = routeWalkActive ? '暫停漫步 ❚❚' : (done ? '再走一遍 ▶' : '沿線自動漫步 ▶');
  }
}

function startWalkMode(startPos = null, lookTarget = null, keepRoute = false) {
  stopTour(true);
  followingPedestrianIdx = -1;
  if (!keepRoute) routeWalkActive = false;
  if (isIsolated) setIsolationMode(false);
  if (activeMode !== '3d') switchViewMode('3d');

  // If no explicit startPos is given, snap near the selected landmark or current camera target (`PKU-3D enterNearby`)
  if (!startPos) {
    const lm = selectedId && LANDMARKS.find(l => l.id === selectedId);
    if (lm && lm.views?.entrance) {
      startPos = [lm.views.entrance.p[0], 1.72, lm.views.entrance.p[2]];
      lookTarget = [lm.views.entrance.t[0], 1.72, lm.views.entrance.t[2]];
    } else {
      startPos = [X(680), 1.72, Z(205)];
      lookTarget = [X(575), 1.72, Z(155)];
    }
  }

  walkState.active = true;
  walkState.detachedFromRoute = !keepRoute;
  controls.enabled = false;
  camAnim = null;

  camera.position.set(...startPos);
  const dx = lookTarget[0] - startPos[0];
  const dz = lookTarget[2] - startPos[2];
  walkState.yaw = Math.atan2(-dx, -dz);
  walkState.pitch = 0.04;
  updateWalkCameraTarget();

  document.getElementById('walk-hud').hidden = false;
  document.getElementById('walk-pad').hidden = false;
  document.getElementById('walk-start').classList.add('is-active');
  document.getElementById('view-hint').textContent = '步行模式 · W A S D 或方向鍵移動 · 拖曳畫面環顧四周 · Esc 退出';
  syncWalkHUD();
  showToast('已進入第一人稱校園地面步行模式（身高 1.72m · 自動避開建築牆體）');
}

function exitWalkMode() {
  if (!walkState.active) return;
  walkState.active = false;
  routeWalkActive = false;
  walkState.keys = { forward: false, backward: false, left: false, right: false, sprint: false };
  controls.enabled = true;
  document.getElementById('walk-hud').hidden = true;
  document.getElementById('walk-pad').hidden = true;
  document.getElementById('walk-start').classList.remove('is-active');
  document.getElementById('view-hint').textContent = '左鍵旋轉 · 右鍵平移 · 滾輪縮放 · 點擊建築查看立面與教室';
  syncWalkHUD();

  // Smoothly lift camera back to a comfortable oblique view around current location
  const cur = camera.position.clone();
  flyTo([cur.x - 18, 28, cur.z + 32], [cur.x, 3, cur.z], 750);
}

function updateWalkCameraTarget() {
  const dirX = -Math.sin(walkState.yaw) * Math.cos(walkState.pitch);
  const dirY = Math.sin(walkState.pitch);
  const dirZ = -Math.cos(walkState.yaw) * Math.cos(walkState.pitch);
  controls.target.set(
    camera.position.x + dirX * 10,
    camera.position.y + dirY * 10,
    camera.position.z + dirZ * 10
  );
  camera.lookAt(controls.target);
}

document.getElementById('walk-start').addEventListener('click', () => {
  if (walkState.active) exitWalkMode();
  else startWalkMode();
});
document.getElementById('walk-exit').addEventListener('click', exitWalkMode);

// Quick Floor Jump Shortcuts inside North Building (BF: y=-0.78m, 1F: y=2.97m, 2F: y=6.57m, 3F: y=10.17m)
const jumpToNorthFloor = (floorLevel) => {
  const isBf = (floorLevel === 0 || floorLevel === 'BF' || floorLevel === 'B1');
  const posY = isBf ? (-2.50 + 1.72) : (1.25 + (floorLevel - 1) * 3.6 + 1.72);
  const posZ = isBf ? -30.0 : -26.0;
  const tgtZ = isBf ? -34.0 : -32.0;
  const label = isBf ? 'BF 地下室防空避難大廳' : `${floorLevel}F 走廊`;
  if (!walkState.active) startWalkMode([20.0, posY, posZ], [20.0, posY, tgtZ]);
  else {
    camera.position.set(20.0, posY, posZ);
    walkState.yaw = 0;
    walkState.pitch = 0.02;
    updateWalkCameraTarget();
    showToast(`已抵達北棟（愛悅樓）${label}（可自由走動探索）`);
  }
};
document.getElementById('walk-floor-bf')?.addEventListener('click', () => jumpToNorthFloor('BF'));
document.getElementById('walk-floor-1f')?.addEventListener('click', () => jumpToNorthFloor(1));
document.getElementById('walk-floor-2f')?.addEventListener('click', () => jumpToNorthFloor(2));
document.getElementById('walk-floor-3f')?.addEventListener('click', () => jumpToNorthFloor(3));

// Touch / Mouse D-Pad buttons (`#walk-pad`)
document.querySelectorAll('#walk-pad button').forEach(btn => {
  const dir = btn.dataset.move;
  const setKey = val => {
    walkState.keys[dir] = val;
    if (val && routeWalkActive) {
      routeWalkActive = false;
      walkState.detachedFromRoute = true;
      syncWalkHUD();
    }
  };
  btn.addEventListener('pointerdown', e => { e.preventDefault(); setKey(true); });
  btn.addEventListener('pointerup', () => setKey(false));
  btn.addEventListener('pointerleave', () => setKey(false));
});

// Pointer drag look-around when in Walk Mode
renderer.domElement.addEventListener('pointerdown', e => {
  if (!walkState.active) return;
  walkState.dragging = true;
  walkState.lastX = e.clientX;
  walkState.lastY = e.clientY;
});
window.addEventListener('pointermove', e => {
  if (!walkState.active || !walkState.dragging) return;
  const dx = e.clientX - walkState.lastX;
  const dy = e.clientY - walkState.lastY;
  walkState.lastX = e.clientX;
  walkState.lastY = e.clientY;
  walkState.yaw -= dx * 0.0042;
  walkState.pitch = THREE.MathUtils.clamp(walkState.pitch - dy * 0.0032, -0.55, 0.65);
  updateWalkCameraTarget();
});
window.addEventListener('pointerup', () => { walkState.dragging = false; });

