function renderExtensionDirectory() {
  const col1El = document.getElementById('plan-ext-col1');
  const col2El = document.getElementById('plan-ext-col2');
  if (!col1El || !col2El) return;
  const renderList = items => items.map(it => {
    const isAct = activeRoomCode === it.code;
    return `<button type="button" class="plan-ext-item ${isAct ? 'is-active' : ''}" data-pid="${it.pid}" data-floor="${it.floor}" data-rcode="${it.code}"><span>${it.label}</span><code>${it.ext}</code></button>`;
  }).join('');
  col1El.innerHTML = renderList(EXTENSION_DIR_COL1);
  col2El.innerHTML = renderList(EXTENSION_DIR_COL2);

  document.querySelectorAll('#plan-ext-card .plan-ext-item').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const pid = btn.dataset.pid;
      const fl = btn.dataset.floor;
      const rcode = btn.dataset.rcode;
      activePlanFloor = fl;
      document.querySelectorAll('[data-plan-floor]').forEach(b => b.classList.toggle('is-active', b.dataset.planFloor === fl));
      selectLandmark(pid, 'manual', fl, rcode);
    });
  });
}
renderExtensionDirectory();

// Cache loaded floor plan textures for 3D plane overlay
const planOverlayTexCache = {};
const planTexLoader = new THREE.TextureLoader();

function getPlanOverlayTexture(floorKey) {
  const cfg = OFFICIAL_PLAN_CONFIG[floorKey] || OFFICIAL_PLAN_CONFIG['1F'];
  if (!planOverlayTexCache[floorKey]) {
    const tex = planTexLoader.load(cfg.src);
    tex.colorSpace = THREE.SRGBColorSpace;
    planOverlayTexCache[floorKey] = tex;
  }
  return planOverlayTexCache[floorKey];
}

// Build 3D Campus Walkway Network in `planPaths3DGroup` once
function buildPlanPaths3D() {
  while (planPaths3DGroup.children.length) planPaths3DGroup.remove(planPaths3DGroup.children[0]);
  const pathMat = new THREE.MeshBasicMaterial({ color: 0x315b4e, transparent: true, opacity: 0.72, depthWrite: false });
  ROUTE_EDGES.forEach(([a, b]) => {
    const [ax, ay] = ROUTE_NODES[a], [bx, by] = ROUTE_NODES[b];
    const pA = new THREE.Vector3(X(ax), 0.36, Z(ay));
    const pB = new THREE.Vector3(X(bx), 0.36, Z(by));
    const dist = pA.distanceTo(pB);
    const mid = new THREE.Vector3().addVectors(pA, pB).multiplyScalar(0.5);
    const bar = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.12, dist), pathMat);
    bar.position.copy(mid);
    bar.lookAt(pB.x, mid.y, pB.z);
    planPaths3DGroup.add(bar);
  });
}
buildPlanPaths3D();

// Rebuild 3D Floor Cutaway Slabs & Official Image Plane whenever floor or checkboxes change
function renderPlanSvg() {
  const isPlan = activeMode === 'plan';
  plan3DOverlayGroup.visible = isPlan;
  const extCard = document.getElementById('plan-ext-card');
  if (extCard) extCard.hidden = !(isPlan && planShowExt);

  if (!isPlan) {
    renderer.clippingPlanes = [];
    // Restore normal 3D landmark label text & positions
    labelElements.forEach(({ el, lm, pos }) => {
      el.classList.remove('plan-bldg-header');
      const txtSpan = el.querySelector('.lm-lbl-text');
      if (txtSpan) txtSpan.textContent = lm.name;
      pos.set(...lm.center);
    });
    roomPinElements.forEach(pin => {
      pin.el.textContent = pin.el.dataset.fullText || `${pin.floorKey} ${pin.room.name}`;
    });
    return;
  }

  const cfg = OFFICIAL_PLAN_CONFIG[activePlanFloor] || OFFICIAL_PLAN_CONFIG['1F'];

  // 1) Apply GPU Horizontal Section Cut (`renderer.clippingPlanes`)
  renderer.localClippingEnabled = true;
  if (cfg.clipY !== null) {
    renderer.clippingPlanes = [new THREE.Plane(new THREE.Vector3(0, -1, 0), cfg.clipY)];
  } else {
    renderer.clippingPlanes = [];
  }

  // 2) Update 3D Tree Canopy Visibility (`☑ 樹冠綠帶`)
  if (!isIsolated) {
    layerGroups.vegetation.visible = planShowTrees;
  }

  // 3) Update 3D Walkway Network Visibility (`☑ 步道網路`)
  planPaths3DGroup.visible = planShowPaths;

  // 4) Update 3D Official Floor Plan Texture Overlay (`☐ 疊加官方原圖`)
  while (planImg3DGroup.children.length) planImg3DGroup.remove(planImg3DGroup.children[0]);
  if (planShowImg) {
    const tex = getPlanOverlayTexture(activePlanFloor);
    const imgPlaneGeo = new THREE.PlaneGeometry(1024 * S, 745 * S);
    const imgPlaneMat = new THREE.MeshBasicMaterial({
      map: tex,
      transparent: true,
      opacity: 0.84,
      side: THREE.DoubleSide,
      depthWrite: false
    });
    const imgMesh = new THREE.Mesh(imgPlaneGeo, imgPlaneMat);
    imgMesh.rotation.x = -Math.PI / 2;
    imgMesh.position.set(X(512), cfg.slabY - 0.08, Z(315));
    planImg3DGroup.add(imgMesh);
  }

  // 5) Rebuild 3D Colored Architectural Room Partition Slabs (`planRooms3DGroup`)
  while (planRooms3DGroup.children.length) planRooms3DGroup.remove(planRooms3DGroup.children[0]);
  planRooms3DGroup.visible = planShowRooms;

  const catColorHex = {
    'cat-class':  0x2b6a4c,
    'cat-spec':   0x255c8a,
    'cat-admin':  0xb85224,
    'cat-pub':    0x9a7220,
    'cat-kinder': 0xb83256,
    'cat-b1':     0x1f6b75
  };

  if (planShowRooms) {
    const targetFloors = activePlanFloor === 'ALL' ? ['1F', '2F', '3F'] : [activePlanFloor];
    LANDMARKS.forEach(lm => {
      if (!lm.pxBounds || !lm.rooms) return;
      const [x1, y1, x2, y2] = lm.pxBounds;
      const bw = (x2 - x1) * S, bd = (y2 - y1) * S;
      const bx0 = X(x1), bz0 = Z((y1 + y2) / 2);

      targetFloors.forEach(flKey => {
        const rms = lm.rooms[flKey] || [];
        if (!rms.length) return;
        const flSlabY = (OFFICIAL_PLAN_CONFIG[flKey] || cfg).slabY;
        const isHorizontalBldg = bw >= bd;
        const slabW = isHorizontalBldg ? Math.max(4.2, (bw / Math.max(4, rms.length + 1)) * 0.86) : (bw * 0.68);
        const slabD = isHorizontalBldg ? (bd * 0.62) : Math.max(4.2, (bd / Math.max(3, rms.length + 0.5)) * 0.82);

        rms.forEach(rm => {
          const pin = roomPinElements.find(p => p.code === rm.code && p.floorKey === flKey);
          const isAct = activeRoomCode === rm.code;
          const hex = isAct ? 0xd93829 : (catColorHex[pin?.catClass] || 0x315b4e);
          const wx = bx0 + rm.rx * bw;
          const wz = bz0 + rm.rz * bd;

          const slabGeo = new THREE.BoxGeometry(slabW, 0.24, slabD);
          const slabMat = new THREE.MeshBasicMaterial({
            color: hex,
            transparent: true,
            opacity: isAct ? 0.88 : (activePlanFloor === 'ALL' ? 0.45 : 0.68)
          });
          const slabMesh = new THREE.Mesh(slabGeo, slabMat);
          slabMesh.position.set(wx, flSlabY, wz);
          slabMesh.userData = { landmarkId: lm.id, roomCode: rm.code, floorKey: flKey, isPlanRoomSlab: true };
          planRooms3DGroup.add(slabMesh);

          // Crisp architectural border outline on top of slab
          const edges = new THREE.EdgesGeometry(slabGeo);
          const line = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: isAct ? 0xffffff : 0xfaf8f2 }));
          line.position.copy(slabMesh.position);
          planRooms3DGroup.add(line);
        });
      });
    });
  }

  // 6) Update Landmark Header Badges (`北棟07`, `南棟05`, `西棟03`, `東棟04`, `新棟3`) & Room Label Positions
  labelElements.forEach(({ el, lm, pos }) => {
    const customHeader = cfg.bldgHeaders[lm.id];
    const txtSpan = el.querySelector('.lm-lbl-text');
    if (customHeader) {
      el.classList.add('plan-bldg-header');
      if (txtSpan) txtSpan.textContent = customHeader;
      const [x1, y1, x2, y2] = lm.pxBounds;
      pos.set(X((x1 + x2) / 2), cfg.slabY + 1.2, Z(y1) - 3.2);
    } else {
      el.classList.remove('plan-bldg-header');
      if (txtSpan) txtSpan.textContent = lm.name;
      pos.set(lm.center[0], 1.8, lm.center[2]);
    }
  });

  roomPinElements.forEach(pin => {
    pin.el.textContent = activePlanFloor === 'ALL'
      ? `${pin.floorKey === 'B1' ? 'BF' : pin.floorKey} ${pin.el.dataset.shortText}`
      : (pin.el.dataset.shortText || pin.room.name);
  });

  renderExtensionDirectory();
}

function switchViewMode(mode) {
  activeMode = mode;
  document.querySelectorAll('#modes .mode[data-mode]').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.mode === mode);
  });
  const isPlan = mode === 'plan';
  // Keep legacy SVG hidden; 3D Floor Cutaway renders directly in #sceneHost + #sceneLabels
  planSvg.setAttribute('hidden', '');
  planSvg.style.display = 'none';

  const planToolbar = document.getElementById('plan-toolbar');
  if (planToolbar) planToolbar.hidden = !isPlan;
  document.getElementById('sceneLabels').style.display = 'block';

  if (isPlan) {
    followingPedestrianIdx = -1;
    if (walkState.active) exitWalkMode();
    isOrbiting = false;
    isTopView = true;
    updateToolButtons();
    camera.clearViewOffset();
    renderPlanSvg();
    const cfg = OFFICIAL_PLAN_CONFIG[activePlanFloor] || OFFICIAL_PLAN_CONFIG['1F'];
    flyTo([8, cfg.camY, 0.4], [8, cfg.slabY, 0], 650);
    document.getElementById('view-hint').textContent = '3D 平面布局剖切模式 · 點擊上方「全校 / 1F / 2F / 3F / BF」切換樓層剖切 · 單擊教室查看詳情 · 雙擊直接進入 3D 走廊';
    showToast(`已進入「${activePlanFloor === 'ALL' ? '全校總覽' : (activePlanFloor === 'B1' ? 'BF 地下層' : activePlanFloor)}」3D 樓層俯視剖切模式`);
  } else {
    isTopView = false;
    updateToolButtons();
    if (!isIsolated) layerGroups.vegetation.visible = layerState.vegetation;
    renderPlanSvg();
    document.getElementById('view-hint').textContent = '左鍵旋轉 · 右鍵平移 · 滾輪縮放 · 雙擊建築快速對焦 · 點擊查看教室';
    if (activeRoomCode) {
      const pin = roomPinElements.find(p => p.code === activeRoomCode);
      if (pin) {
        const lm = LANDMARKS.find(l => l.id === pin.landmarkId);
        if (lm) {
          const birdEyeV = getClassroomBirdEyeView(lm, pin.floorKey, pin.room, pin.pos);
          activeViewMode = 'oblique';
          flyTo(birdEyeV.p, birdEyeV.t, 780);
        }
      }
    } else if (selectedId) {
      const lm = LANDMARKS.find(l => l.id === selectedId);
      if (lm && lm.views) {
        const targetV = lm.views.oblique || lm.views.front || lm.views.entrance;
        activeViewMode = (lm.views && lm.views.oblique) ? 'oblique' : 'front';
        if (targetV) flyTo(targetV.p, targetV.t, 780);
      }
    } else {
      resetOverview();
    }
  }
}

