function updateMinimap() {
  const isNight = document.documentElement.dataset.theme === 'night';
  const bFill = isNight ? '#3d5249' : '#b7c4b1';
  const bStroke = isNight ? '#768f80' : '#5c7563';

  let svgHtml = `
    <polygon points="${X(40)},${Z(8)} ${X(972)},${Z(8)} ${X(972)},${Z(336)} ${X(770)},${Z(330)} ${X(494)},${Z(328)} ${X(438)},${Z(384)} ${X(365)},${Z(384)} ${X(176)},${Z(498)} ${X(40)},${Z(334)}" fill="none" stroke="rgba(197,118,94,0.55)" stroke-width="1.2" stroke-dasharray="2 2"/>
    <polygon points="${X(56)},${Z(22)} ${X(955)},${Z(22)} ${X(955)},${Z(326)} ${X(772)},${Z(320)} ${X(496)},${Z(318)} ${X(438)},${Z(374)} ${X(367)},${Z(374)} ${X(180)},${Z(480)} ${X(56)},${Z(328)}" fill="none" stroke="${isNight ? '#8bc7b0' : '#315b4e'}" stroke-width="1.5" opacity="0.85"/>
    <polygon points="${X(58)},${Z(24)} ${X(412)},${Z(24)} ${X(412)},${Z(386)} ${X(403)},${Z(390)} ${X(180)},${Z(477)} ${X(58)},${Z(327)}" fill="${isNight ? 'rgba(54,94,68,0.38)' : 'rgba(165,208,148,0.45)'}" stroke="none"/>
    <rect x="${X(224)}" y="${Z(120)}" width="${128 * S}" height="${256 * S}" rx="${64 * S}" fill="none" stroke="#c85a40" stroke-width="3.2" opacity="0.85"/>
  `;

  if (activeRoutePoints3D.length > 1) {
    const ptsStr = activeRoutePoints3D.map(p => `${p.x.toFixed(1)},${p.z.toFixed(1)}`).join(' ');
    svgHtml += `<polyline points="${ptsStr}" fill="none" stroke="#923c32" stroke-width="2.2" />`;
  }

  LANDMARKS.forEach(lm => {
    if (!lm.pxBounds || lm.id === 'courtyard-plaza' || lm.id === 'sports-track') return;
    const [x1, y1, x2, y2] = lm.pxBounds;
    const rx = X(x1), ry = Z(y1), rw = (x2 - x1) * S, rh = (y2 - y1) * S;
    const isSel = selectedId === lm.id;
    svgHtml += `<rect data-mid="${lm.id}" x="${rx}" y="${ry}" width="${rw}" height="${rh}" rx="1.5" fill="${isSel ? '#923c32' : bFill}" stroke="${isSel ? '#faf8f2' : bStroke}" stroke-width="${isSel ? 1.8 : 1}"/>`;
  });

  const cx = THREE.MathUtils.clamp(camera.position.x, -120, 125);
  const cz = THREE.MathUtils.clamp(camera.position.z, -60, 85);
  const tx = controls.target.x, tz = controls.target.z;
  const ang = Math.atan2(tz - cz, tx - cx);
  const rCone = 28, spread = 0.45;
  const p1x = cx + Math.cos(ang - spread) * rCone, p1z = cz + Math.sin(ang - spread) * rCone;
  const p2x = cx + Math.cos(ang + spread) * rCone, p2z = cz + Math.sin(ang + spread) * rCone;

  svgHtml += `
    <polygon points="${cx},${cz} ${p1x},${p1z} ${p2x},${p2z}" fill="rgba(146, 60, 50, 0.22)" stroke="rgba(146, 60, 50, 0.6)" stroke-width="1"/>
    <circle cx="${tx}" cy="${tz}" r="3" fill="#315b4e" stroke="#faf8f2" stroke-width="1"/>
    <circle cx="${cx}" cy="${cz}" r="3.8" fill="#923c32" stroke="#faf8f2" stroke-width="1.3"/>
  `;
  minimapSvg.innerHTML = svgHtml;
}

minimapSvg.addEventListener('click', e => {
  const rectEl = e.target.closest('[data-mid]');
  if (rectEl) {
    selectLandmark(rectEl.dataset.mid, 'manual');
    return;
  }
  const pt = minimapSvg.createSVGPoint();
  pt.x = e.clientX; pt.y = e.clientY;
  const worldPt = pt.matrixTransform(minimapSvg.getScreenCTM().inverse());
  flyTo([worldPt.x - 20, 55, worldPt.y + 65], [worldPt.x, 2, worldPt.y], 750);
});

