// 12. AUTOMATED CAMPUS TOUR, MAP CONTROLS, PICKING, SHORTCUTS & EXPORT
// ============================================================================
// Westminster School Bell Chime Synthesis (Web Audio API)
function playSchoolBellChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    if (ctx.state === 'suspended') ctx.resume();
    // 4-note Westminster chime: E4, C4, D4, G3
    const notes = [329.63, 261.63, 293.66, 196.00];
    notes.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.42);
      gain.gain.setValueAtTime(0, ctx.currentTime + idx * 0.42);
      gain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + idx * 0.42 + 0.04);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + idx * 0.42 + 1.15);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + idx * 0.42);
      osc.stop(ctx.currentTime + idx * 0.42 + 1.2);
    });
  } catch (e) {}
}

// Native Web Speech API Voice Guide
let speechGuideEnabled = true;
function speakTourStop(text) {
  if (!speechGuideEnabled) return;
  try {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'zh-TW';
    u.rate = 1.02;
    u.pitch = 1.0;
    window.speechSynthesis.speak(u);
  } catch (e) {}
}

