let activePresetRouteKey = null;
let presetRouteStopIdx = 0;
let presetRouteElapsed = 0;

function startPresetRoute(routeKey) {
  const route = PRESET_TOUR_ROUTES[routeKey];
  if (!route) return;
  if (walkState.active) exitWalkMode();
  if (activeMode !== '3d') switchViewMode('3d');

  activePresetRouteKey = routeKey;
  presetRouteStopIdx = 0;
  presetRouteElapsed = 0;
  tourRunning = true;
  tourPaused = false;
  tourBarEl.classList.add('running');
  tourToggleBtn.textContent = '❚❚';

  document.querySelectorAll('.tour-preset-btn').forEach(b => {
    b.classList.toggle('is-active', b.id === (routeKey === 'bell' ? 'tourBellBtn' : 'tourBarrierBtn'));
  });

  if (route.chime) playSchoolBellChime();
  goToPresetStop(0);
}

function goToPresetStop(idx) {
  const route = PRESET_TOUR_ROUTES[activePresetRouteKey];
  if (!route) return;
  presetRouteStopIdx = (idx + route.stops.length) % route.stops.length;
  presetRouteElapsed = 0;
  const stop = route.stops[presetRouteStopIdx];

  tourCounterTextEl.textContent = `${route.icon} ${route.name} · 0${presetRouteStopIdx + 1} / 0${route.stops.length}`;
  tourPlaceTextEl.textContent = stop.title;

  flyTo(stop.cam, stop.target, 850);
  selectLandmark(stop.landmarkId, 'tour');

  // Voice narration & toast
  speakTourStop(`${stop.title}。${stop.desc}`);
  showToast(`${route.icon} 【${stop.tag}】${stop.title}`);
}

function startTour(fromIndex = 0) {
  if (walkState.active) exitWalkMode();
  if (activeMode !== '3d') switchViewMode('3d');
  activePresetRouteKey = null;
  tourRunning = true;
  tourPaused = false;
  tourIdx = fromIndex;
  tourElapsed = 0;
  tourBarEl.classList.add('running');
  tourToggleBtn.textContent = '❚❚';
  document.querySelectorAll('.tour-preset-btn').forEach(b => b.classList.remove('is-active'));
  if (window.innerWidth <= 820 || window.innerHeight <= 640) {
    setCatalogOpen(false);
    detailEl.hidden = true;
  }
  goToTourStop(tourIdx);
}

function goToTourStop(idx) {
  tourIdx = (idx + LANDMARKS.length) % LANDMARKS.length;
  tourElapsed = 0;
  const lm = LANDMARKS[tourIdx];
  tourCounterTextEl.textContent = `${tourPaused ? '已暫停' : '巡禮中'} · ${lm.index} / 12`;
  tourPlaceTextEl.textContent = lm.name;
  selectLandmark(lm.id, 'tour');
}

function stopTour(resetUI = true) {
  tourRunning = false;
  tourPaused = false;
  activePresetRouteKey = null;
  tourElapsed = 0;
  presetRouteElapsed = 0;
  tourProgressFillEl.style.width = '0%';
  if (resetUI) {
    tourBarEl.classList.remove('running');
    document.querySelectorAll('.tour-preset-btn').forEach(b => b.classList.remove('is-active'));
  }
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
}

