document.getElementById('tourBarrierBtn')?.addEventListener('click', () => startPresetRoute('barrier-free'));
document.getElementById('startTourBtn').addEventListener('click', () => {
  const startIdx = selectedId ? Math.max(0, LANDMARKS.findIndex(l => l.id === selectedId)) : 0;
  startTour(startIdx);
});
document.getElementById('tourPrevBtn').addEventListener('click', () => {
  if (activePresetRouteKey) {
    goToPresetStop(presetRouteStopIdx - 1);
  } else {
    goToTourStop(tourIdx - 1);
  }
});
document.getElementById('tourNextBtn').addEventListener('click', () => {
  if (activePresetRouteKey) {
    goToPresetStop(presetRouteStopIdx + 1);
  } else {
    goToTourStop(tourIdx + 1);
  }
});
tourToggleBtn.addEventListener('click', () => {
  tourPaused = !tourPaused;
  isOrbiting = !tourPaused;
  tourToggleBtn.textContent = tourPaused ? '▶' : '❚❚';
  if (activePresetRouteKey) {
    const route = PRESET_TOUR_ROUTES[activePresetRouteKey];
    tourCounterTextEl.textContent = `${tourPaused ? '已暫停' : route.icon + ' 巡禮中'} · 0${presetRouteStopIdx + 1} / 0${route.stops.length}`;
  } else {
    const lm = LANDMARKS[tourIdx];
    tourCounterTextEl.textContent = `${tourPaused ? '已暫停' : '巡禮中'} · ${lm.index} / 12`;
  }
});
document.getElementById('tourStopBtn').addEventListener('click', () => {
  stopTour(true);
  isOrbiting = false;
  updateToolButtons();
});

function updateToolButtons() {
  document.getElementById('toggleOrbitBtn').classList.toggle('is-active', isOrbiting);
  document.getElementById('toggleTopBtn').classList.toggle('is-active', isTopView);
}

document.getElementById('resetHomeBtn').addEventListener('click', resetOverview);
document.getElementById('compassBtn').addEventListener('click', () => {
  const dist = camera.position.distanceTo(controls.target);
  const y = camera.position.y;
  flyTo([controls.target.x, y, controls.target.z + Math.max(30, Math.hypot(dist, 1) * 0.75)], controls.target.toArray(), 700);
  showToast('已對齊正北朝上視角 (North Up)');
});
document.getElementById('zoomInBtn').addEventListener('click', () => {
  const dir = new THREE.Vector3().subVectors(controls.target, camera.position).multiplyScalar(0.24);
  flyTo(camera.position.clone().add(dir).toArray(), controls.target.toArray(), 320);
});
document.getElementById('zoomOutBtn').addEventListener('click', () => {
  const dir = new THREE.Vector3().subVectors(camera.position, controls.target).multiplyScalar(0.28);
  flyTo(camera.position.clone().add(dir).toArray(), controls.target.toArray(), 320);
});
document.getElementById('toggleTopBtn').addEventListener('click', () => {
  isTopView = !isTopView;
  updateToolButtons();
  if (isTopView) {
    flyTo([controls.target.x, 185, controls.target.z + 0.5], controls.target.toArray(), 780);
    showToast('垂直俯視 · 正北朝上');
  } else {
    if (activeMode === 'plan') {
      switchViewMode('3d');
    } else {
      flyTo([controls.target.x - 35, 75, controls.target.z + 110], controls.target.toArray(), 780);
    }
  }
});
document.getElementById('toggleOrbitBtn').addEventListener('click', () => {
  if (activeMode === 'plan') {
    switchViewMode('3d');
  }
  isOrbiting = !isOrbiting;
  updateToolButtons();
});

// Share Current View Snapshot Link (URL Hash)
document.getElementById('shareViewBtn').addEventListener('click', async () => {
  const p = camera.position.toArray().map(n => n.toFixed(1)).join(',');
  const t = controls.target.toArray().map(n => n.toFixed(1)).join(',');
  const params = new URLSearchParams();
  if (selectedId) params.set('place', selectedId);
  params.set('time', String(timeOfDay));
  params.set('season', activeSeason);
  params.set('p', p);
  params.set('t', t);
  const url = `${location.origin}${location.pathname}#${params.toString()}`;
  history.replaceState(null, '', `#${params.toString()}`);
  try {
    await navigator.clipboard.writeText(url);
    showToast('✓ 已複製當前視角與四時光影分享連結！');
  } catch {
    showToast('✓ 視角參數已更新至網址列！');
  }
});

// Export Clean Watermarked PNG (PKU-3D Editorial Seal Style)
document.getElementById('exportPngBtn').addEventListener('click', () => {
  renderer.render(scene, camera);
  const srcCanvas = renderer.domElement;
  const out = document.createElement('canvas');
  out.width = srcCanvas.width;
  out.height = srcCanvas.height;
  const ctx = out.getContext('2d');
  ctx.drawImage(srcCanvas, 0, 0);

  const barH = Math.max(38, Math.round(out.height * 0.046));
  ctx.fillStyle = 'rgba(250, 248, 242, 0.92)';
  ctx.fillRect(0, out.height - barH, out.width, barH);
  ctx.fillStyle = '#923c32';
  ctx.fillRect(0, out.height - barH, 6, barH);
  ctx.fillStyle = '#253d37';
  ctx.font = `600 ${Math.round(barH * 0.42)}px "Noto Serif TC", "Songti TC", serif`;
  ctx.textBaseline = 'middle';
  const lmName = selectedId ? ` · ${LANDMARKS.find(l => l.id === selectedId)?.name || ''}` : '';
  ctx.fillText(`復興 · 一園，四時｜屏東縣復興國小${lmName}`, 20, out.height - barH / 2);
  ctx.textAlign = 'right';
  ctx.fillStyle = '#737c73';
  ctx.font = `500 ${Math.round(barH * 0.36)}px "Inter", "Noto Sans TC", sans-serif`;
  ctx.fillText(`${formatTimeLabel(timeOfDay)} · ${SEASON_PALETTES[activeSeason].label} · 115學年度`, out.width - 20, out.height - barH / 2);

  const a = document.createElement('a');
  a.href = out.toDataURL('image/png');
  a.download = `fuxing-3d-${activeSeason}-${formatTimeLabel(timeOfDay).replace(':', '')}.png`;
  a.click();
  showToast('✓ 已匯出宣紙朱印署名之高畫質校園截圖！');
});

// Raycast Picking & Double-Click Quick Frame on 3D Buildings
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
let downXY = null;

renderer.domElement.addEventListener('pointerdown', e => {
  downXY = [e.clientX, e.clientY];
  followingPedestrianIdx = -1;
  if (tourRunning && !tourPaused) {
    tourPaused = true;
    isOrbiting = false;
    tourToggleBtn.textContent = '▶';
  }
});

renderer.domElement.addEventListener('pointerup', e => {
  if (walkState.active) return;
  if (!downXY || Math.hypot(e.clientX - downXY[0], e.clientY - downXY[1]) > 5) return;
  pointer.set((e.clientX / window.innerWidth) * 2 - 1, -(e.clientY / window.innerHeight) * 2 + 1);
  raycaster.setFromCamera(pointer, camera);

  // In 3D Plan mode, check 3D classroom slabs first so clicking any room selects that exact classroom
  if (activeMode === 'plan' && planRooms3DGroup.children.length > 0) {
    const roomHits = raycaster.intersectObjects(planRooms3DGroup.children, true);
    if (roomHits.length > 0) {
      let rObj = roomHits[0].object;
      while (rObj && !rObj.userData?.roomCode && rObj.parent) rObj = rObj.parent;
      if (rObj && rObj.userData?.landmarkId) {
        selectLandmark(rObj.userData.landmarkId, 'manual', rObj.userData.floorKey, rObj.userData.roomCode);
        return;
      }
    }
  }

  const hits = raycaster.intersectObjects(clickableGroups, true);
  if (hits.length > 0) {
    let obj = hits[0].object;
    while (obj && !obj.userData.landmarkId) obj = obj.parent;
    if (obj && obj.userData.landmarkId) {
      selectLandmark(obj.userData.landmarkId, 'manual');
    }
  }
});

// Double-click any 3D point or 3D Plan classroom slab (`Shift + DblClick` enters ground walk right there!)
renderer.domElement.addEventListener('dblclick', e => {
  if (walkState.active) return;
  pointer.set((e.clientX / window.innerWidth) * 2 - 1, -(e.clientY / window.innerHeight) * 2 + 1);
  raycaster.setFromCamera(pointer, camera);

  if (activeMode === 'plan' && planRooms3DGroup.children.length > 0) {
    const roomHits = raycaster.intersectObjects(planRooms3DGroup.children, true);
    if (roomHits.length > 0) {
      let rObj = roomHits[0].object;
      while (rObj && !rObj.userData?.roomCode && rObj.parent) rObj = rObj.parent;
      if (rObj && rObj.userData?.landmarkId) {
        const lmId = rObj.userData.landmarkId;
        const fKey = rObj.userData.floorKey;
        const rCode = rObj.userData.roomCode;
        switchViewMode('3d');
        selectLandmark(lmId, 'manual', fKey, rCode);
        return;
      }
    }
  }

  const hits = raycaster.intersectObjects(scene.children, true);
  if (hits.length > 0) {
    const pt = hits[0].point;
    if (e.shiftKey) {
      if (activeMode === 'plan') switchViewMode('3d');
      startWalkMode([pt.x, 1.72, pt.z + 4], [pt.x, 1.72, pt.z - 6]);
    } else if (activeMode === 'plan') {
      flyTo([pt.x, 105, pt.z + 0.6], [pt.x, 2, pt.z], 650);
    } else {
      flyTo([pt.x - 16, Math.max(12, pt.y + 18), pt.z + 26], [pt.x, Math.max(1.5, pt.y), pt.z], 720);
    }
  }
});

// Keyboard Shortcuts (`/`, `WASD`, `Arrows`, `Q`/`E`, `+`/`-`, `Shift`, `Esc`, `Home`, `1-4`)
window.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    if (document.querySelector('.modal-backdrop.open')) {
      document.querySelectorAll('.modal-backdrop.open').forEach(m => m.classList.remove('open'));
      return;
    }
    if (walkState.active) { exitWalkMode(); return; }
    if (isIsolated) { setIsolationMode(false); return; }
    if (!detailEl.hidden) { detailEl.hidden = true; setDetailCompact(false); return; }
    document.getElementById('environment').hidden = true;
    document.getElementById('route-panel').hidden = true;
    return;
  }
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName)) {
    if (e.key === 'Escape') document.activeElement.blur();
    return;
  }
  if (e.key === '/') {
    e.preventDefault();
    setCatalogOpen(true, true);
    return;
  }

  // First-person walking keys
  if (walkState.active) {
    const k = e.key.toLowerCase();
    if (e.code === 'Space') {
      e.preventDefault();
      if (activeRoutePoints3D.length > 1) toggleRouteTravel();
      return;
    }
    if (['w', 's', 'a', 'd', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(k)) {
      if (routeWalkActive) {
        routeWalkActive = false;
        walkState.detachedFromRoute = true;
        syncWalkHUD();
      }
    }
    if (k === 'w' || e.key === 'ArrowUp') walkState.keys.forward = true;
    if (k === 's' || e.key === 'ArrowDown') walkState.keys.backward = true;
    if (k === 'a' || e.key === 'ArrowLeft') walkState.keys.left = true;
    if (k === 'd' || e.key === 'ArrowRight') walkState.keys.right = true;
    if (k === 'e' || (e.code === 'Space' && !activeRoutePoints3D.length)) walkState.keys.up = true;
    if (k === 'q' || k === 'c') walkState.keys.down = true;
    if (e.key === 'Shift') walkState.keys.sprint = true;
    return;
  }

  // Browse Mode Keyboard Navigation (`PKU-3D app-v29.js` lines 331-332)
  if (e.key === '+' || e.key === '=') document.getElementById('zoomInBtn').click();
  else if (e.key === '-') document.getElementById('zoomOutBtn').click();
  else if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) {
    e.preventDefault();
    const dx = e.key === 'ArrowLeft' ? -4.5 : (e.key === 'ArrowRight' ? 4.5 : 0);
    const dz = e.key === 'ArrowUp' ? -4.5 : (e.key === 'ArrowDown' ? 4.5 : 0);
    camera.position.x += dx;
    camera.position.z += dz;
    controls.target.x += dx;
    controls.target.z += dz;
  } else if (e.key === 'Home') { e.preventDefault(); resetOverview(); }
  else if (e.key === '1') { timeOfDay = 7.5; updateEnvironmentSimulation(); }
  else if (e.key === '2') { timeOfDay = 10.5; updateEnvironmentSimulation(); }
  else if (e.key === '3') { timeOfDay = 17.5; updateEnvironmentSimulation(); }
  else if (e.key === '4') { timeOfDay = 19.75; updateEnvironmentSimulation(); }
});

window.addEventListener('keyup', e => {
  if (!walkState.active) return;
  const k = e.key.toLowerCase();
  if (k === 'w' || e.key === 'ArrowUp') walkState.keys.forward = false;
  if (k === 's' || e.key === 'ArrowDown') walkState.keys.backward = false;
  if (k === 'a' || e.key === 'ArrowLeft') walkState.keys.left = false;
  if (k === 'd' || e.key === 'ArrowRight') walkState.keys.right = false;
  if (k === 'e' || e.code === 'Space') walkState.keys.up = false;
  if (k === 'q' || k === 'c') walkState.keys.down = false;
  if (e.key === 'Shift') walkState.keys.sprint = false;
});

window.addEventListener('blur', () => {
  walkState.keys = { forward: false, backward: false, left: false, right: false, up: false, down: false, sprint: false };
});

