function showToast(msg) {
  const box = document.getElementById('toastBox');
  box.textContent = msg;
  box.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => box.classList.remove('show'), 3200);
}

// Restore URL Hash Snapshot if present
function restoreHashSnapshot() {
  if (!location.hash || location.hash.length < 2) {
    const searchParams = new URLSearchParams(window.location.search);
    if (!searchParams.has('bldg') && !searchParams.has('landmark') && !searchParams.has('place') && !searchParams.has('room')) {
      fitPrecinct('campus');
    }
    return;
  }
  const params = new URLSearchParams(location.hash.slice(1));
  const tVal = parseFloat(params.get('time'));
  if (Number.isFinite(tVal)) timeOfDay = THREE.MathUtils.clamp(tVal, 6, 21);
  const sVal = params.get('season');
  if (sVal && SEASON_PALETTES[sVal]) activeSeason = sVal;
  updateEnvironmentSimulation();

  const place = params.get('place');
  if (place && LANDMARKS.some(l => l.id === place)) {
    selectLandmark(place, 'manual');
  }
  const p = params.get('p')?.split(',').map(Number);
  const t = params.get('t')?.split(',').map(Number);
  if (p?.length === 3 && t?.length === 3 && p.every(Number.isFinite) && t.every(Number.isFinite)) {
    flyTo(p, t, 0);
  } else if (!place) {
    fitPrecinct('campus');
  }
}

updateEnvironmentSimulation();
renderPlacesList();
restoreHashSnapshot();
// URL Query Parameters support (?landmark=breezeway-hub&vp=read)
try {
  const urlParams = new URLSearchParams(window.location.search);
  const targetLm = urlParams.get('landmark') || urlParams.get('place');
  if (targetLm) {
    const vp = urlParams.get('vp');
    selectLandmark(targetLm, 'card', '1F', null, vp);
    const lm = LANDMARKS.find(l => l.id === targetLm);
    if (vp && lm && lm.views && lm.views[vp]) {
      const v = lm.views[vp];
      flyTo(v.p, v.t, 0);
    }
  }
  const camParam = urlParams.get('cam');
  if (camParam) {
    const parts = camParam.split(',').map(Number);
    if (parts.length === 6 && !parts.some(isNaN)) {
      camAnim = null;
      isOrbiting = false;
      controls.maxPolarAngle = Math.PI - 0.01;
      controls.minPolarAngle = 0.01;
      controls.minDistance = 0.1;
      camera.position.set(parts[0], parts[1], parts[2]);
      controls.target.set(parts[3], parts[4], parts[5]);
      controls.update();
    }
  }
  const cx = urlParams.get('cx'), cy = urlParams.get('cy'), czParam = urlParams.get('cz');
  const tx = urlParams.get('tx'), ty = urlParams.get('ty'), tz = urlParams.get('tz');
  if (cx !== null && tx !== null) {
    camAnim = null;
    isOrbiting = false;
    controls.maxPolarAngle = Math.PI - 0.01;
    controls.minPolarAngle = 0.01;
    controls.minDistance = 0.1;
    camera.position.set(parseFloat(cx), parseFloat(cy), parseFloat(czParam));
    controls.target.set(parseFloat(tx), parseFloat(ty), parseFloat(tz));
    controls.update();
  }
} catch (e) {}

// ============================================================================
// 13. MAIN RENDER LOOP (CAMERA, WALK, ROUTE, PEDESTRIANS, FLAGS, LABELS, FPS)
// ============================================================================
const tempV = new THREE.Vector3();
let frameCount = 0;
let fpsAccum = 0;
let lastMinimapUpdate = 0;

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  if (window.innerWidth > 820 && window.innerHeight > 640) setDetailCompact(false);
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(getOptimalDpr());
  renderer.setSize(window.innerWidth, window.innerHeight);
  requestRender(35);
});

// PKU-3D Smart Label Decluttering & Panel Collision Check (`blocked` in `app-v29.js` line 243)
function getActivePanelRects() {
  const rects = [];
  const cat = document.getElementById('catalog');
  if (cat && !cat.classList.contains('is-collapsed')) rects.push(cat.getBoundingClientRect());
  for (const id of ['detail', 'environment', 'route-panel', 'plan-toolbar', 'plan-ext-card']) {
    const el = document.getElementById(id);
    if (el && !el.hidden) rects.push(el.getBoundingClientRect());
  }
  return rects;
}

function isLabelBlocked(sx, sy, bw, bh, panelRects, occupiedBoxes, isPriority = false) {
  if (sx < bw / 2 + 8 || sx > window.innerWidth - bw / 2 - 8 || sy < 72 || sy > window.innerHeight - 52) return true;
  if (!isPriority) {
    for (const r of panelRects) {
      if (sx + bw / 2 > r.left - 4 && sx - bw / 2 < r.right + 4 && sy > r.top - 4 && sy - bh < r.bottom + 4) {
        return true;
      }
    }
  }
  for (const box of occupiedBoxes) {
    if (sx + bw / 2 > box.x - 6 && sx - bw / 2 < box.x + box.w + 6 && sy > box.y - 4 && sy - bh < box.y + box.h + 4) {
      return true;
    }
  }
  return false;
}

renderer.setAnimationLoop(now => {
  const dt = Math.min(100, now - lastFrameTime);
  const dtSec = dt * 0.001;
  lastFrameTime = now;

  // On-demand rendering condition checks (Camera movement, active tour, walks, weather, or user interactions)
  const hasContinuousAnimation =
    Boolean(camAnim) ||
    walkState.active ||
    routeWalkActive ||
    isOrbiting ||
    tourRunning ||
    followingPedestrianIdx >= 0 ||
    (motionEnabled && weatherPoints && weatherPoints.visible && activeWeather !== 'clear');

  if (hasContinuousAnimation) {
    requestRender(10);
  }

  // When scene is static and no interaction is occurring: bypass rendering & physics to save battery & prevent heating
  if (renderDemandFrames <= 0) {
    return;
  }
  renderDemandFrames--;

  // FPS counter
  frameCount++;
  fpsAccum += dt;
  if (fpsAccum >= 1000) {
    const fps = Math.round((frameCount * 1000) / fpsAccum);
    const fpsEl = document.getElementById('fpsText');
    if (fpsEl) fpsEl.textContent = `${fps} FPS`;
    frameCount = 0;
    fpsAccum = 0;
  }

  // Dynamic Level of Detail (LOD) update across buildings
  updateLODs();

  // 1) Collision-Aware First-Person Ground Walk Movement (`PKU-3D FirstPerson.move` substepping)
  if (walkState.active && !routeWalkActive) {
    const speed = (walkState.keys.sprint ? 16.0 : 8.2) * dtSec;
    const fwdX = -Math.sin(walkState.yaw), fwdZ = -Math.cos(walkState.yaw);
    const rightX = Math.cos(walkState.yaw), rightZ = -Math.sin(walkState.yaw);
    let moveX = 0, moveZ = 0;
    if (walkState.keys.forward) { moveX += fwdX; moveZ += fwdZ; }
    if (walkState.keys.backward) { moveX -= fwdX; moveZ -= fwdZ; }
    if (walkState.keys.right) { moveX += rightX; moveZ += rightZ; }
    if (walkState.keys.left) { moveX -= rightX; moveZ -= rightZ; }
    const len = Math.hypot(moveX, moveZ);
    if (len > 0.001) {
      const dx = (moveX / len) * speed;
      const dz = (moveZ / len) * speed;
      const curX = camera.position.x, curZ = camera.position.z;
      // Check full step, or slide along X / Z axis (`PKU-3D FirstPerson.move` line 63)
      if (isWalkPointAllowed(curX + dx, curZ + dz)) {
        camera.position.x = curX + dx;
        camera.position.z = curZ + dz;
      } else if (isWalkPointAllowed(curX + dx, curZ)) {
        camera.position.x = curX + dx;
      } else if (isWalkPointAllowed(curX, curZ + dz)) {
        camera.position.z = curZ + dz;
      }

      // Vertical Up / Down Movement (Q / E, Space / C, or Up / Down buttons)
      const vSpeed = (walkState.keys.sprint ? 10.0 : 5.0) * dtSec;
      if (walkState.keys.up) {
        camera.position.y += vSpeed;
      } else if (walkState.keys.down) {
        camera.position.y = Math.max(-0.78, camera.position.y - vSpeed);
      } else {
        // Automatic Stair Climbing inside North Building Central Stairwell (⑪–⑫: X from 17.0 to 23.0, Z from -38.5 to -26.5)
        const inStairwell = (camera.position.x >= 17.0 && camera.position.x <= 23.0 && camera.position.z >= -38.5 && camera.position.z <= -26.5);
        if (inStairwell) {
          // Downward flight to Basement on west run (x <= 20.0, z from -26.0 to -32.5, y < 3.20)
          if (camera.position.x <= 20.0 && camera.position.y < 3.20 && camera.position.z >= -32.5 && camera.position.z <= -26.0) {
            const bfProg = (-26.0 - camera.position.z) / 6.0; // 0 at 1F (z=-26.0), 1 at BF (z=-32.0)
            const targetY = THREE.MathUtils.lerp(2.97, -0.78, THREE.MathUtils.clamp(bfProg, 0, 1));
            camera.position.y = THREE.MathUtils.lerp(camera.position.y, targetY, 0.18);
          } else {
            // East flight (x > 20.0): goes up from south (Z=-26.5) to north (Z=-35.0)
            // West flight (x <= 20.0): goes up from north (Z=-35.0) to south (Z=-26.5)
            const curFloor = Math.floor(Math.max(0, (camera.position.y - 1.72 - 1.25) / 3.6));
            const floorBaseY = 1.25 + curFloor * 3.6 + 1.72;
            const isEastUp = camera.position.x > 20.0;
            if (isEastUp && camera.position.z <= -26.5 && camera.position.z >= -35.0) {
              const stairProgress = (-26.5 - camera.position.z) / 8.5; // 0 to 1
              const targetY = floorBaseY + THREE.MathUtils.clamp(stairProgress, 0, 1) * 1.8;
              camera.position.y = THREE.MathUtils.lerp(camera.position.y, targetY, 0.15);
            } else if (!isEastUp && camera.position.z >= -35.0 && camera.position.z <= -26.5) {
              const stairProgress = (camera.position.z - (-35.0)) / 8.5; // 0 to 1
              const targetY = floorBaseY + 1.8 + THREE.MathUtils.clamp(stairProgress, 0, 1) * 1.8;
              camera.position.y = THREE.MathUtils.lerp(camera.position.y, targetY, 0.15);
            }
          }
        }
        // Stepped Garden Planters descent to Basement South Lightwell (X: -26.5..-17.5 & 32.0..43.0, Z: -21.65..-19.15)
        const inSteppedPlanter = (camera.position.z >= -21.65 && camera.position.z <= -19.15 &&
          ((camera.position.x >= -26.5 && camera.position.x <= -17.5) || (camera.position.x >= 32.0 && camera.position.x <= 43.0)));
        if (inSteppedPlanter) {
          const pProg = (camera.position.z - (-19.25)) / (-2.40); // 0 at south ground, 1 at sunken lightwell
          const targetY = THREE.MathUtils.lerp(1.72, -0.78, THREE.MathUtils.clamp(pProg, 0, 1));
          camera.position.y = THREE.MathUtils.lerp(camera.position.y, targetY, 0.18);
        }
        // Automatic Stair Climbing inside West Building North Staircase (東面上樓：X from -26.80 to -32.15, Z from -16.05 to -14.19)
        const inWestNorthStair = (camera.position.x >= -32.25 && camera.position.x <= -26.70 && camera.position.z >= -16.05 && camera.position.z <= -14.19);
        if (inWestNorthStair) {
          const curFloor = (camera.position.y - 1.72 >= 3.80) ? 1 : 0;
          const baseFloorY = (curFloor === 0 ? 0.25 : 3.95) + 1.72;
          const riseH = (curFloor === 0 ? 3.70 : 3.75);
          const stairProgress = (-26.80 - camera.position.x) / 5.35; // 0 (East) to 1 (West)
          const targetY = baseFloorY + THREE.MathUtils.clamp(stairProgress, 0, 1) * riseH;
          camera.position.y = THREE.MathUtils.lerp(camera.position.y, targetY, 0.18);
        }
      }
      camera.position.y += Math.sin(now * 0.012) * (len > 0.001 ? 0.018 : 0);
      updateWalkCameraTarget();
    } else {
      // Idle vertical control handling
      const vSpeed = (walkState.keys.sprint ? 10.0 : 5.0) * dtSec;
      if (walkState.keys.up) {
        camera.position.y += vSpeed;
        updateWalkCameraTarget();
      } else if (walkState.keys.down) {
        camera.position.y = Math.max(-0.78, camera.position.y - vSpeed);
        updateWalkCameraTarget();
      }
    }
  } else if (routeWalkActive && activeRoutePoints3D.length > 1) {
    // 2) Automated Route Explorer Walk Playback (`沿路探索`)
    routeWalkProgress += dtSec * 0.052;
    if (routeWalkProgress >= 1) {
      routeWalkProgress = 1;
      routeWalkActive = false;
      syncWalkHUD();
    }
    const pct = Math.round(routeWalkProgress * 100);
    routeProgressInput.value = String(pct);
    routeProgressLabel.textContent = `${pct}%`;
    placeCameraOnRoute(routeWalkProgress);
    syncWalkHUD();
  } else if (camAnim) {
    // 3) Smooth Camera Flight Tween
    const t = Math.min(1, (now - camAnim.start) / camAnim.duration);
    const ease = 1 - Math.pow(1 - t, 3);
    camera.position.lerpVectors(camAnim.fromPos, camAnim.toPos, ease);
    controls.target.lerpVectors(camAnim.fromTarget, camAnim.toTarget, ease);
    if (t >= 1) camAnim = null;
    controls.update();
  } else if (followingPedestrianIdx >= 0 && pedestrianAgents[followingPedestrianIdx]) {
    // 4) Close-Up Pedestrian Following Camera (`#walkers-view`)
    const ag = pedestrianAgents[followingPedestrianIdx];
    const pos = ag.mesh.position;
    const yaw = ag.mesh.rotation.y;
    const goalEye = new THREE.Vector3(
      pos.x - Math.sin(yaw) * 6.8 + Math.cos(yaw) * 2.2,
      2.05,
      pos.z - Math.cos(yaw) * 6.8 - Math.sin(yaw) * 2.2
    );
    const goalTarget = new THREE.Vector3(
      pos.x + Math.sin(yaw) * 1.8,
      1.20,
      pos.z + Math.cos(yaw) * 1.8
    );
    camera.position.lerp(goalEye, Math.min(1, dtSec * 4.5));
    controls.target.lerp(goalTarget, Math.min(1, dtSec * 6.0));
    controls.update();
  } else {
    if (isOrbiting && motionEnabled && !prefersReducedMotion()) {
      const offset = camera.position.clone().sub(controls.target);
      offset.applyAxisAngle(new THREE.Vector3(0, 1, 0), dt * 0.00028);
      camera.position.copy(controls.target).add(offset);
    }
    controls.update();
  }

  // Update PKU-3D Off-Center Panel Framing (`camera.setViewOffset`)
  updateCameraViewOffset(dtSec);

  // 5) Automated Tour Timer (Preset Routes & Standard Landmark Tour)
  if (tourRunning && !tourPaused) {
    if (activePresetRouteKey) {
      presetRouteElapsed += dt;
      const route = PRESET_TOUR_ROUTES[activePresetRouteKey];
      const stop = route.stops[presetRouteStopIdx];
      const dur = stop.duration || 5200;
      const pct = Math.min(100, (presetRouteElapsed / dur) * 100);
      tourProgressFillEl.style.width = `${pct}%`;
      if (presetRouteElapsed >= dur) {
        if (presetRouteStopIdx < route.stops.length - 1) {
          goToPresetStop(presetRouteStopIdx + 1);
        } else {
          stopTour(true);
          showToast(`✓ 已完成「${route.name}」校園巡禮`);
        }
      }
    } else {
      tourElapsed += dt;
      const pct = Math.min(100, (tourElapsed / TOUR_MS) * 100);
      tourProgressFillEl.style.width = `${pct}%`;
      if (tourElapsed >= TOUR_MS) {
        goToTourStop(tourIdx + 1);
      }
    }
  }

  // 6) Animate 3D Articulated Campus Pedestrians (`校園師生行人`, Arms & Legs Swing + Bob)
  if (motionEnabled && layerState.people && !isIsolated) {
    pedestrianAgents.forEach(ag => {
      const pA = ag.loop[ag.segIdx];
      const pB = ag.loop[(ag.segIdx + 1) % ag.loop.length];
      const segLen = Math.max(0.5, Math.hypot(pB[0] - pA[0], pB[1] - pA[1]));
      ag.segT += (ag.speed * dtSec) / segLen;
      if (ag.segT >= 1) {
        ag.segT -= 1;
        ag.segIdx = (ag.segIdx + 1) % ag.loop.length;
      }
      const curA = ag.loop[ag.segIdx];
      const curB = ag.loop[(ag.segIdx + 1) % ag.loop.length];
      const px = curA[0] + (curB[0] - curA[0]) * ag.segT;
      const pz = curA[1] + (curB[1] - curA[1]) * ag.segT;
      const cycle = now * 0.0085 * ag.speed + ag.phase;
      const bob = Math.abs(Math.cos(cycle)) * 0.025;
      ag.mesh.position.set(px, 0.10 + bob, pz);
      ag.mesh.rotation.y = Math.atan2(curB[0] - curA[0], curB[1] - curA[1]);
      const swing = Math.sin(cycle) * 0.46;
      ag.legL.rotation.x = swing;
      ag.legR.rotation.x = -swing;
      if (ag.armL && ag.armR) {
        ag.armL.rotation.x = -swing * 0.72;
        ag.armR.rotation.x = swing * 0.72;
      }
    });
  }

  // 7) Animate Waving Flags on Command Stage Flagpoles (`司令台國旗隨風飄揚`)
  if (motionEnabled && window.__campusFlags && window.__campusFlags.length > 0) {
    window.__campusFlags.forEach(f => {
      const posAttr = f.mesh.geometry.attributes.position;
      const baseArr = f.baseAttr.array;
      const arr = posAttr.array;
      const halfW = f.halfW || 0.975;
      for (let i = 0; i < posAttr.count; i++) {
        const bx = baseArr[i * 3]; // -halfW (at pole) to +halfW (free tip)
        const by = baseArr[i * 3 + 1];
        const pinFactor = Math.max(0, Math.min(1, (bx + halfW) / (2 * halfW)));
        // 自然微風多頻率正弦布料飄動波浪
        const waveZ = (Math.sin(now * 0.0055 - bx * 3.4 + by * 1.2 + f.phase) * 0.14 +
                       Math.sin(now * 0.0085 - bx * 5.2) * 0.05) * pinFactor;
        arr[i * 3 + 2] = waveZ;
        arr[i * 3 + 1] = by + Math.sin(now * 0.004 + bx * 2.2) * 0.02 * pinFactor;
      }
      posAttr.needsUpdate = true;
    });
  }

  // 8) Animate Weather Particles (`細雨` / `落雪`)
  if (motionEnabled && weatherPoints.visible) {
    const posAttr = weatherGeo.attributes.position;
    const arr = posAttr.array;
    const fallSpeed = activeWeather === 'rain' ? 42 * dtSec : 7.5 * dtSec;
    const drift = activeWeather === 'snow' ? Math.sin(now * 0.0015) * 2.5 * dtSec : 0;
    for (let i = 0; i < WEATHER_COUNT; i++) {
      arr[i * 3 + 1] -= fallSpeed;
      arr[i * 3] += drift;
      if (arr[i * 3 + 1] < 0) {
        arr[i * 3 + 1] = 82;
        arr[i * 3] = (Math.random() - 0.5) * 280;
      }
    }
    posAttr.needsUpdate = true;
  }

  // Update Compass Rotation
  const azimuth = Math.atan2(camera.position.x - controls.target.x, camera.position.z - controls.target.z);
  const compassSvg = document.getElementById('compassSvg');
  if (compassSvg) compassSvg.style.transform = `rotate(${(azimuth * 180 / Math.PI).toFixed(1)}deg)`;

  // Periodically refresh Minimap camera cone
  if (now - lastMinimapUpdate > 90) {
    updateMinimap();
    lastMinimapUpdate = now;
  }

  // 9) Smart 3D Landmark & Classroom Label Projection (`3d` & `plan` Cutaway Modes)
  if (activeMode === '3d' || activeMode === 'plan') {
    const isPlan = activeMode === 'plan';
    const w = window.innerWidth, h = window.innerHeight;
    const panelRects = getActivePanelRects();
    const occupiedBoxes = [];

    // Sort landmarks by priority: selected -> hovered -> featured -> others
    const sortedLandmarks = [...labelElements.entries()].sort(([idA], [idB]) => {
      const score = id => id === selectedId ? -100 : (id === hoveredId ? -50 : (FEATURED_IDS.includes(id) ? FEATURED_IDS.indexOf(id) : 50));
      return score(idA) - score(idB);
    });

    sortedLandmarks.forEach(([id, { el, pos, lm }]) => {
      const showLandmarkLabel = isPlan
        ? (!walkState.active && (!isIsolated || id === selectedId))
        : (layerState.labels && !walkState.active && (!isIsolated || id === selectedId));
      if (!showLandmarkLabel) {
        el.style.display = 'none';
        return;
      }
      tempV.copy(pos);
      if (isPlan && activePlanFloor !== 'ALL') {
        const cfg = OFFICIAL_PLAN_CONFIG[activePlanFloor] || OFFICIAL_PLAN_CONFIG['1F'];
        tempV.y = Math.min(pos.y, cfg.slabY + 2.2);
      }
      tempV.project(camera);
      if (tempV.z > 1 || tempV.x < -1.05 || tempV.x > 1.05 || tempV.y < -1.05 || tempV.y > 1.05) {
        el.style.display = 'none';
        return;
      }
      const sx = (tempV.x * 0.5 + 0.5) * w;
      const sy = (-tempV.y * 0.5 + 0.5) * h;
      const bw = isPlan ? 130 : Math.min(210, lm.name.length * 12 + 38);
      const bh = isPlan ? 24 : 28;
      const isPriority = (id === selectedId || id === hoveredId || isPlan);
      if (isLabelBlocked(sx, sy, bw, bh, panelRects, occupiedBoxes, isPriority)) {
        el.style.display = 'none';
        return;
      }
      occupiedBoxes.push({ x: sx - bw / 2, y: sy - bh, w: bw, h: bh });
      el.style.display = 'inline-flex';
      el.style.transform = `translate3d(${sx.toFixed(1)}px, ${sy.toFixed(1)}px, 0) translate(-50%, -100%)`;
    });

    roomPinElements.forEach(pin => {
      const isSelectedRoom = activeRoomCode && pin.code === activeRoomCode;
      let showPin = false;
      if (isPlan) {
        if (isSelectedRoom) {
          showPin = true;
        } else if (planShowRooms) {
          if (activePlanFloor === 'ALL') {
            showPin = (pin.floorKey === '1F');
          } else {
            showPin = (pin.floorKey === activePlanFloor);
          }
        }
      } else {
        showPin = !walkState.active && (layerState.rooms || isSelectedRoom) && (!isIsolated || pin.landmarkId === selectedId);
      }

      if (!showPin) {
        pin.el.style.display = 'none';
        return;
      }

      tempV.copy(pin.pos).project(camera);
      const dist = camera.position.distanceTo(pin.pos);
      if (tempV.z > 1 || (!isPlan && dist > 145 && !isSelectedRoom)) {
        pin.el.style.display = 'none';
        return;
      }
      const sx = (tempV.x * 0.5 + 0.5) * w;
      const sy = (-tempV.y * 0.5 + 0.5) * h;
      const bw = isPlan ? 46 : 115;
      const bh = isPlan ? 15 : 22;
      if (!isSelectedRoom && isLabelBlocked(sx, sy, bw, bh, panelRects, occupiedBoxes, false)) {
        pin.el.style.display = 'none';
        return;
      }
      occupiedBoxes.push({ x: sx - bw / 2, y: sy - bh, w: bw, h: bh });
      pin.el.style.display = 'inline-flex';
      pin.el.style.transform = `translate3d(${sx.toFixed(1)}px, ${sy.toFixed(1)}px, 0) translate(-50%, -100%)`;
    });

    renderer.render(scene, camera);
    if (!window.__hasFirst3DRender) {
      window.__hasFirst3DRender = true;
      onFirst3DFrameReady();
    }
  }
});

function onFirst3DFrameReady() {
  window.__threeReady = true;
  if (window.__campusBridge) {
    window.__campusBridge.on3dReady({
      selectLandmark,
      focusClassroom,
      fitPrecinct,
      flyTo
    });
  }
  const shell = document.getElementById('campus-preview-shell');
  if (shell) {
    shell.classList.add('is-hidden');
    setTimeout(() => { if (shell.parentNode) shell.remove(); }, 600);
  }
  // Schedule deferred texture loading in background idle time
  const schedule = window.requestIdleCallback || (cb => setTimeout(cb, 120));
  schedule(loadDeferredTextures);

  // Initialize Deep Link URL on initial page boot
  handleDeepLinkOnStartup();

  // Initialize Onboarding Hint
  initOnboarding();

  // Flush pre-interactive queue if user clicked anything during initial load
  if (window.__preQueue && window.__preQueue.length) {
    const act = window.__preQueue[window.__preQueue.length - 1];
    if (act.type === 'landmark') selectLandmark(act.id, 'card');
    else if (act.type === 'precinct') fitPrecinct(act.key);
    window.__preQueue = [];
  }
}

function handleDeepLinkOnStartup() {
  try {
    const params = new URLSearchParams(window.location.search);
    const bldg = params.get('bldg') || params.get('landmark') || params.get('place');
    const room = params.get('room');
    const floor = params.get('floor') || '1F';
    if (bldg && LANDMARKS.some(l => l.id === bldg)) {
      selectLandmark(bldg, 'card', floor, room || undefined);
    } else if (room) {
      for (const lm of LANDMARKS) {
        for (const [fl, rms] of Object.entries(lm.rooms || {})) {
          const matched = rms.find(r => r.code === room);
          if (matched) {
            selectLandmark(lm.id, 'card', fl, room);
            return;
          }
        }
      }
    }
  } catch (e) {
    console.warn('Deep link startup handler:', e);
  }
}

function initOnboarding() {
  const hintEl = document.getElementById('onboardingHint');
  const dismissBtn = document.getElementById('onboardingDismiss');
  if (!hintEl) return;
  const key = 'fuxing_onboarded_v1';
  try {
    if (localStorage.getItem(key)) return;
  } catch {}

  hintEl.hidden = false;

  const dismiss = () => {
    hintEl.classList.add('is-dismissed');
    setTimeout(() => { hintEl.hidden = true; }, 320);
    try { localStorage.setItem(key, '1'); } catch {}
  };

  dismissBtn?.addEventListener('click', dismiss);
  setTimeout(dismiss, 7000);
}

function openQrShareModal(title, url, subtitle) {
  const qrModal = document.getElementById('qrModal');
  const qrTitle = document.getElementById('qrModalTitle');
  const qrSub = document.getElementById('qrModalSubtitle');
  const qrContainer = document.getElementById('qrCodeContainer');
  if (!qrModal || !qrContainer) return;

  qrTitle.textContent = title || '空間專屬 QR Code';
  qrSub.textContent = subtitle || url;
  qrContainer.innerHTML = '<div style="color:var(--muted);font-size:12px;padding:20px">產生 QR Code 中...</div>';
  qrModal.classList.add('open');

  if (window.QRCode && window.QRCode.toString) {
    window.QRCode.toString(url, { type: 'svg', margin: 1, width: 200 }, (err, svg) => {
      if (err) {
        qrContainer.innerHTML = '<div style="color:#c92a2a;font-size:12px">QR Code 產生失敗</div>';
      } else {
        qrContainer.innerHTML = svg;
      }
    });
  } else {
    qrContainer.innerHTML = `<img src="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(url)}" alt="QR Code" width="200" height="200" style="border-radius:6px">`;
  }
}

// Wire Share & QR Code Button in Right Detail Panel
document.getElementById('share-link-btn')?.addEventListener('click', () => {
  const lm = LANDMARKS.find(l => l.id === selectedId);
  if (!lm) return;
  const currentUrl = window.location.href;
  const title = activeRoomCode
    ? `${lm.name} · ${activeRoomCode} 空間分享`
    : `${lm.name} 建築分享`;
  openQrShareModal(title, currentUrl, `掃描 QR 碼直接進入 ${activeRoomCode ? `${lm.name} (${activeRoomCode})` : lm.name}`);
});

document.getElementById('qrCopyUrlBtn')?.addEventListener('click', () => {
  const url = window.location.href;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(() => {
      showToast('✓ 已複製分享連結至剪貼簿！');
    }).catch(() => {
      prompt('請複製以下分享網址：', url);
    });
  } else {
    prompt('請複製以下分享網址：', url);
  }
});

document.getElementById('qrDownloadBtn')?.addEventListener('click', () => {
  const qrContainer = document.getElementById('qrCodeContainer');
  const svg = qrContainer?.querySelector('svg');
  if (!svg) {
    showToast('請稍候，QR 碼載入中');
    return;
  }
  const svgData = new XMLSerializer().serializeToString(svg);
  const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
  const blobUrl = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = blobUrl;
  const lm = LANDMARKS.find(l => l.id === selectedId);
  a.download = `復興國小_${lm ? lm.name : '校園'}_${activeRoomCode || '3D'}_QRCode.svg`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(blobUrl);
  showToast('✓ 已下載專屬 QR Code (SVG) 檔案');
});

function loadDeferredTextures() {
  const loadScript = src => new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
  Promise.all([
    loadScript('./tex/east_mural_data.js'),
    loadScript('./tex/pbr_data.js'),
    loadScript('./tex/campus_detail_textures.js')
  ]).then(() => {
    window.dispatchEvent(new CustomEvent('deferred-textures-loaded'));
  }).catch(e => console.warn('Deferred textures load:', e));
}

// Expose global helpers for interactive navigation & automation
window.selectLandmark = selectLandmark;
window.flyTo = flyTo;
window.camera = camera;
window.controls = controls;
window.scene = scene;
window.getActiveViewMode = () => activeViewMode;
window.getSelectedId = () => selectedId;
window.openQrShareModal = openQrShareModal;
